INSERT INTO `wp_postmeta` VALUES(291, 82, '_form', '<div class=\"form-grid\">\n<div class=\"form-group\">\n<label for=\"clientName\">Full Name *</label>\n[text* clientName id:clientName placeholder \"Your Name\"]\n</div>\n<div class=\"form-group\">\n<label for=\"clientPhone\">Phone Number *</label>\n[tel* clientPhone id:clientPhone placeholder \"+91 98765 43210\"]\n</div>\n<div class=\"form-group\">\n<label for=\"clientEmail\">Email Address *</label>\n[email* clientEmail id:clientEmail placeholder \"your@email.com\"]\n</div>\n<div class=\"form-group\">\n<label for=\"serviceInterest\">Service of Interest *</label>\n[select* serviceInterest id:serviceInterest \"General Hospitality Inquiry\" \"Capital Investment Plan\" \"Location Selection\" \"Outlet & Kitchen Design\" \"Staffing Support\" \"Civil Work\" \"Interior Work\" \"Marketing Service\" \"Food & Running Cost\" \"Vendor Selection & Purchase Advice\" \"Food and Service Quality\"]\n</div>\n<div class=\"form-group full\">\n<label for=\"projectMessage\">Your Message *</label>\n[textarea* projectMessage id:projectMessage placeholder \"Tell us about your hospitality business or project requirements...\"]\n</div>\n</div>\n<div class=\"form-actions\">\n[submit class:btn class:btn-primary \"Send Message ↗\"]\n</div>');
