INSERT INTO `wp_posts` VALUES(11, 1, '2026-11-26 05:42:49', '2026-11-26 05:42:49', '<!-- NEW 75VH ABOUT US HERO SECTION -->\r\n<section class=\"about-editorial-hero\" id=\"about-top\">\r\n  <div class=\"wrap hero-inner\">\r\n\r\n    <!-- Column 1: Editorial Copy & CTAs -->\r\n    <div class=\"hero-story-col anim-base anim-fade-right\">\r\n      <div class=\"hero-top-tags\">\r\n        <nav class=\"breadcrumb-pill\" aria-label=\"Breadcrumb\">\r\n          <a href=\"index.html\">Home</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <span class=\"current\">About Us</span>\r\n        </nav>\r\n        <span class=\"eyebrow\">Who We Are</span>\r\n      </div>\r\n\r\n      <h1>Shaping the Future of <em>Thoughtful Hospitality</em> From Concept to Table.</h1>\r\n      <p>At Artha Hospitality Management, we partner with visionary restaurateurs, hoteliers, and hospitality entrepreneurs to turn ambitious concepts into resilient, high-performing destinations.</p>\r\n\r\n      <div class=\"hero-cta-group\">\r\n        <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-primary\">Partner With Artha <span class=\"arrow\">↗</span></a>\r\n        <a href=\"index.html#services\" class=\"btn btn-ghost\">Our Capabilities</a>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Column 2: Single Image Sculptural Stage with Theme Shapes -->\r\n    <div class=\"hero-visual-stage anim-base anim-fade-left delay-100\">\r\n      <!-- Shape 1: Concentric Gold Contour Rings -->\r\n      <svg class=\"stage-shape-rings\" viewBox=\"0 0 240 240\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"120\" cy=\"120\" r=\"110\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"82\" opacity=\"0.65\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"54\" opacity=\"0.4\" />\r\n      </svg>\r\n\r\n      <!-- Shape 2: Deep Espresso Architectural Offset Slab -->\r\n      <div class=\"stage-shape-slab\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 3: Gold Offset Wireframe Arch -->\r\n      <div class=\"stage-shape-wireframe\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 4: Gold Dot Matrix Pattern -->\r\n      <div class=\"stage-shape-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 5: Floating Espresso & Gold Medallion Seal -->\r\n      <div class=\"stage-medallion\">\r\n        <span class=\"med-icon\" aria-hidden=\"true\"><i class=\"fas fa-award\"></i></span>\r\n        <div class=\"med-text\">\r\n          <strong>15+ Yrs</strong>\r\n          <span>Hospitality Mastery</span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Main Sculpted Arched Image Panel -->\r\n      <div class=\"hero-arch-panel\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-about-us-hero.jpg\" alt=\"Hospitality team collaborating in a professional kitchen\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Hospitality team collaborating in a professional kitchen</figcaption>\r\n        </figure>\r\n        <div class=\"arch-caption-bar\">\r\n          <div>\r\n            <span class=\"tag-sub\">Operational Craft</span>\r\n            <span class=\"tag-title\">Ground-Level Expertise</span>\r\n          </div>\r\n          <span class=\"tag-ic\" aria-hidden=\"true\"><i class=\"fas fa-compass\"></i></span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 1: ENGAGING ABOUT ARTHA HOSPITALITY -->\r\n<section class=\"about-artha-section\" id=\"about-artha\">\r\n  <div class=\"wrap\">\r\n    <div class=\"about-artha-grid\">\r\n\r\n      <!-- Story & Philosophy Copy -->\r\n      <div class=\"artha-story-copy anim-base anim-fade-right\">\r\n        <span class=\"eyebrow\">About Us</span>\r\n        <h2>Hospitality Begins With <em>Great Service.</em></h2>\r\n        <p class=\"lead-p\">At Artha, we believe that great hospitality begins with great service. Our mission is to help restaurant owners and hospitality businesses overcome their toughest service challenges, improve guest satisfaction, and grow sustainably.</p>\r\n        <p>With a deep understanding of the industry and a commitment to excellence, we provide tailor-made solutions that create lasting value for our partners.</p>\r\n\r\n        <div class=\"artha-values-list\">\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-hotel\"></i></span>\r\n            <div>\r\n              <h4>Industry Understanding</h4>\r\n              <p>Grounded in more than 15 years of hospitality and hotel operations experience.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-star\"></i></span>\r\n            <div>\r\n              <h4>Tailor-Made Solutions</h4>\r\n              <p>Approaches shaped around your business, your guests, and your operational goals.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-check-circle\"></i></span>\r\n            <div>\r\n              <h4>Commitment to Excellence</h4>\r\n              <p>A consistent focus on quality, service standards, and sustainable long-term growth.</p>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <a href=\"index.html#services\" class=\"btn btn-primary\">Discover What We Do <span class=\"arrow\">↗</span></a>\r\n      </div>\r\n\r\n      <!-- Layered Hospitality Collage -->\r\n      <div class=\"artha-story-visual anim-base anim-fade-left delay-100\">\r\n        <div class=\"artha-vis-tag\">\r\n          <span class=\"vt-ic\" aria-hidden=\"true\"><i class=\"fas fa-compass\"></i></span>\r\n          <div>\r\n            <span>15+ Years Experience</span>\r\n            <strong>Solutions That Work From Day One</strong>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"artha-vis-main\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/slide-img-2-lgr.jpg\" alt=\"Elegant hospitality reception and dining space\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Elegant hospitality reception and dining space</figcaption>\r\n          </figure>\r\n        </div>\r\n\r\n        <div class=\"artha-vis-sub\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-management-about-us-sml-img.jpg\" alt=\"Premium restaurant dining environment\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Premium restaurant dining environment</figcaption>\r\n          </figure>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 2: LEADERSHIP & VISION + CEO SPOTLIGHT (VIHANI ANIL) -->\r\n<section class=\"leader-spotlight bg-sand-light\" id=\"vihani-anil\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n      <h2>The Minds Driving Culinary, People &amp; Operational Excellence.</h2>\r\n      <p>Guided by visionary leadership, seasoned hospitality veterans, kitchen innovators, HR strategists, and operations leaders committed to building resilient, people-first hospitality ventures.</p>\r\n    </div>\r\n\r\n    <div class=\"spotlight-grid\">\r\n\r\n      <!-- Portrait Column -->\r\n      <div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n        <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-frame\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/vihani-anil.jpg\" alt=\"Vihani Anil - Future CEO, Artha Hospitality Management\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Vihani Anil - Future CEO | Artha Hospitality Management</figcaption>\r\n          </figure>\r\n        </div>\r\n        <div class=\"portrait-exp-badge\">\r\n          <strong>Future</strong>\r\n          <span>CEO · Artha<br>Hospitality</span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Biography & Vision Column -->\r\n      <div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n        <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n        <h2>Vihani Anil</h2>\r\n        <div class=\"role-pill\">\r\n          <i class=\"fas fa-crown\"></i>\r\n          <span>Future CEO | Artha Hospitality Management</span>\r\n        </div>\r\n\r\n        <div class=\"leader-bio\">\r\n          <p>Vihani Anil is the Future CEO of Artha Hospitality Management, representing the next generation of strategic leadership, brand vision, and client-first hospitality advisory across India.</p>\r\n          <p>Guided by the principle <em>Dream · Plan · Achieve</em>, she brings a forward-looking perspective to modern hospitality consulting—bridging creative concept development with disciplined business planning and sustainable growth.</p>\r\n          <p>Her leadership focus centres on empowering restaurant, café, hotel, cloud kitchen, and resort founders with clarity, structured execution, and long-term operational confidence from day one.</p>\r\n        </div>\r\n\r\n        <div class=\"leader-chips\">\r\n          <span>Future Leadership</span>\r\n          <span>Brand Strategy</span>\r\n          <span>Client Partnerships</span>\r\n          <span>Business Growth</span>\r\n          <span>Hospitality Innovation</span>\r\n          <span>Strategic Planning</span>\r\n        </div>\r\n\r\n        <div class=\"vision-callout\">\r\n          <div class=\"vc-head\">\r\n            <i class=\"fas fa-compass\"></i>\r\n            <span>Future Vision &amp; Leadership</span>\r\n          </div>\r\n          <p>As Future CEO, Vihani champions a culture of excellence, transparency, and purposeful execution—ensuring every hospitality venture partnered with Artha transforms ambitious ideas into thriving, guest-loved destinations.</p>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 3: FOUNDER & DIRECTOR SPOTLIGHT (ANIL KUMAR K) -->\r\n<section class=\"leader-spotlight bg-offwhite\" id=\"anil-kumar\">\r\n  <div class=\"wrap\">\r\n    <div class=\"spotlight-grid reverse\">\r\n\r\n      <!-- Biography & Vision Column -->\r\n      <div class=\"leader-copy anim-base anim-fade-right\">\r\n        <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n        <h2>Anil Kumar K</h2>\r\n        <div class=\"role-pill\">\r\n          <i class=\"fas fa-chess-king\"></i>\r\n          <span>Founder &amp; Director – Artha Hospitality</span>\r\n        </div>\r\n\r\n        <div class=\"leader-bio\">\r\n          <p>Chef Anil Kumar K is the Founder &amp; Director of Artha Hospitality, bringing over 25 years of experience in the hospitality industry.</p>\r\n          <p>With a professional background as a Chef, Anil has extensive hands-on experience in professional kitchens, restaurant operations, kitchen planning, commercial kitchen equipment, food production, and hospitality management.</p>\r\n          <p>His 25 years of industry experience provide him with a deep understanding of the practical requirements of hotels, restaurants, cafés, catering businesses, and commercial food-service operations.</p>\r\n        </div>\r\n\r\n        <div class=\"leader-chips\">\r\n          <span>Professional Kitchens</span>\r\n          <span>Restaurant Operations</span>\r\n          <span>Kitchen Planning</span>\r\n          <span>Commercial Kitchen Equipment</span>\r\n          <span>Food Production</span>\r\n          <span>Hospitality Management</span>\r\n        </div>\r\n\r\n        <div class=\"vision-callout\">\r\n          <div class=\"vc-head\">\r\n            <i class=\"fas fa-compass\"></i>\r\n            <span>Strategic Vision &amp; Leadership</span>\r\n          </div>\r\n          <p>As Founder &amp; Director of Artha Hospitality, Anil leads the company’s business strategy, kitchen solutions, operational planning, client relationships, and overall execution, with a vision to deliver reliable, efficient, and sustainable hospitality solutions.</p>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Portrait Column -->\r\n      <div class=\"leader-portrait-stage anim-base anim-fade-left delay-100\">\r\n        <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-frame\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/anil-kumar-k.jpg\" alt=\"Chef Anil Kumar K - Founder & Director of Artha Hospitality\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Chef Anil Kumar K - Founder &amp; Director – Artha Hospitality</figcaption>\r\n          </figure>\r\n        </div>\r\n        <div class=\"portrait-exp-badge\">\r\n          <strong>25+</strong>\r\n          <span>Years in<br>Hospitality</span>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: HR DIRECTOR SPOTLIGHT - SUSHMA AMIN -->\r\n<section class=\"leader-spotlight bg-sand-light\" id=\"sushma-amin\">\r\n  <div class=\"wrap spotlight-grid\">\r\n\r\n    <!-- Portrait Column -->\r\n    <div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n      <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n      <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n      <div class=\"portrait-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/sushma-amin.jpg\" alt=\"Sushma Amin - HR Director & Hospitality HR Professional\" loading=\"lazy\">\r\n          <figcaption class=\"cr-only\">Sushma Amin - HR Director &amp; Hospitality HR Professional</figcaption>\r\n        </figure>\r\n      </div>\r\n      <div class=\"portrait-exp-badge\">\r\n        <strong>20+</strong>\r\n        <span>Years in HR &amp;<br>Hospitality</span>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Biography & Vision Column -->\r\n    <div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n      <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n      <h2>Sushma Amin</h2>\r\n      <div class=\"role-pill\">\r\n        <i class=\"fas fa-balance-scale\"></i>\r\n        <span>HR Director &amp; Hospitality HR Professional</span>\r\n      </div>\r\n\r\n      <div class=\"leader-bio\">\r\n        <p>Sushma Amin is a seasoned Human Resources professional with over 20 years of experience in the HR and hospitality industry, bringing extensive expertise in people management, talent acquisition, employee relations, HR operations, and organizational development.</p>\r\n        <p>With a strong academic background in Bachelor of Arts (BA) and Bachelor of Laws (LLB), she combines professional knowledge with practical industry experience to build effective HR practices and people-centric workplaces.</p>\r\n        <p>Throughout her career, she has worked with leading hospitality establishments, gaining valuable experience in managing diverse workforces, developing HR systems, streamlining recruitment processes, and supporting business growth through effective human resource management.</p>\r\n      </div>\r\n\r\n      <div class=\"leader-chips\">\r\n        <span>People Management</span>\r\n        <span>Talent Acquisition</span>\r\n        <span>Employee Relations</span>\r\n        <span>HR Operations</span>\r\n        <span>Organizational Development</span>\r\n        <span>BA &amp; LLB</span>\r\n      </div>\r\n\r\n      <div class=\"vision-callout\">\r\n        <div class=\"vc-head\">\r\n          <i class=\"fas fa-bullseye\"></i>\r\n          <span>Professional Vision</span>\r\n        </div>\r\n        <p>Her professional vision is to connect the right talent with the right opportunities, empower people, strengthen organizations, and contribute to the growth of the hospitality industry through ethical, transparent, and result-oriented HR practices.</p>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: ARTHA EXECUTIVE MANAGEMENT (SNEHA M. & SANDEEP SHETTY) -->\r\n<section class=\"management-section\" id=\"executive-management\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Artha Hospitality Team</span>\r\n      <h2>Driving Recruitment, Sales &amp; Operational Excellence.</h2>\r\n      <p>Connecting talented hospitality professionals with leading organizations and delivering disciplined, guest-focused operational results every day.</p>\r\n    </div>\r\n\r\n    <!-- Profile 1: Sneha M. -->\r\n    <article class=\"exec-profile-block anim-base anim-fade-up\">\r\n      <div class=\"exec-top-grid\">\r\n        <div class=\"exec-photo-wrap\">\r\n          <div class=\"exec-photo-frame\">\r\n            <figure class=\"cr-figure\">\r\n              <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/sneha-m.jpg\" alt=\"Sneha M. - HR Executive at Artha Hospitality\" loading=\"lazy\">\r\n              <figcaption class=\"cr-only\">Sneha M. - HR Executive | Artha Hospitality</figcaption>\r\n            </figure>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"exec-intro\">\r\n          <span class=\"eyebrow\">People &amp; Talent</span>\r\n          <h3>Sneha M.</h3>\r\n          <div class=\"exec-role\">\r\n            <i class=\"fas fa-id-badge\"></i>\r\n            <span>HR Executive | Artha Hospitality</span>\r\n          </div>\r\n          <p>As an HR Executive at Artha Hospitality, I am responsible for identifying, attracting and connecting the right talent with the right opportunities in the hospitality industry.</p>\r\n          <p>I believe that successful businesses are built by the right people. My focus is on understanding client requirements, building strong relationships with candidates and ensuring a smooth and effective recruitment process.</p>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"exec-pillars-grid\">\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-eye\"></i></span>\r\n            <h4>My Vision</h4>\r\n          </div>\r\n          <p>To connect talented individuals with the right opportunities and help hospitality businesses grow through quality recruitment, trust and strong professional relationships.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box dark\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-bullseye\"></i></span>\r\n            <h4>My Mission</h4>\r\n          </div>\r\n          <p>To make recruitment a meaningful experience by bringing together the right people and the right organizations.</p>\r\n        </div>\r\n      </div>\r\n    </article>\r\n\r\n    <!-- Profile 2: Sandeep Shetty -->\r\n    <article class=\"exec-profile-block reverse anim-base anim-fade-up\">\r\n      <div class=\"exec-top-grid\">\r\n        <div class=\"exec-intro\">\r\n          <span class=\"eyebrow\">Growth &amp; Operations</span>\r\n          <h3>Sandeep Shetty</h3>\r\n          <div class=\"exec-role\">\r\n            <i class=\"fas fa-briefcase\"></i>\r\n            <span>Sales &amp; Operations Manager | Artha Hospitality</span>\r\n          </div>\r\n          <p>As a Sales &amp; Operations Manager at Artha Hospitality, I am responsible for driving business growth, leading operations, and creating exceptional guest experiences in the hospitality industry.</p>\r\n          <p>I believe that successful hospitality businesses are built on strong leadership, consistent service, and the right people. My focus is on understanding client needs, building lasting business relationships, and ensuring smooth, result-driven operations.</p>\r\n        </div>\r\n\r\n        <div class=\"exec-photo-wrap\">\r\n          <div class=\"exec-photo-frame\">\r\n            <figure class=\"cr-figure\">\r\n              <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/sandeep-shetty.jpg\" alt=\"Sandeep Shetty - Sales & Operations Manager at Artha Hospitality\" loading=\"lazy\">\r\n              <figcaption class=\"cr-only\">Sandeep Shetty - Sales &amp; Operations Manager | Artha Hospitality</figcaption>\r\n            </figure>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"exec-pillars-grid cols-3\">\r\n        <div class=\"pillar-box dark\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-chess-knight\"></i></span>\r\n            <h4>My Leadership</h4>\r\n          </div>\r\n          <p>I lead by example — with clarity, accountability, and a people-first approach. My leadership is focused on building high-performing teams, empowering individuals, and creating a culture of ownership, discipline, and excellence.</p>\r\n          <p>I believe a great leader doesn\'t just manage operations; they inspire people to deliver their best every single day.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-eye\"></i></span>\r\n            <h4>My Vision</h4>\r\n          </div>\r\n          <p>To lead Artha Hospitality towards sustainable growth by combining strong sales strategies, operational excellence, and meaningful human connections — and to make it a trusted name in the hospitality industry.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-rocket\"></i></span>\r\n            <h4>My Mission</h4>\r\n          </div>\r\n          <p>To drive sales with integrity, deliver operations with excellence, and create value for clients, guests, and the team — by bringing together the right strategy, the right people, and the right execution.</p>\r\n        </div>\r\n      </div>\r\n    </article>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- WHY CHOOSE US SECTION -->\r\n<section class=\"why-choose-section\" id=\"why-choose-us\">\r\n  <div class=\"wrap\">\r\n    <div class=\"why-choose-head anim-base anim-fade-up\">\r\n      <span class=\"eyebrow\">Why Choose Us?</span>\r\n      <h2>Experience That Turns Ideas Into Successful Operations.</h2>\r\n      <p>“Backed by over <em>15 years</em> of experience in hospitality and hotel operations, our team combines industry insight with proven strategies to deliver solutions that work from day one.”</p>\r\n    </div>\r\n\r\n    <div class=\"why-choose-grid\">\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-100\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-award\"></i></span>\r\n        <h3>Industry Experience</h3>\r\n        <p>More than 15 years of hands-on experience in hospitality and hotel operations.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-200\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-chart-line\"></i></span>\r\n        <h3>Strategic Approach</h3>\r\n        <p>Solutions built around your specific business requirements and operational objectives.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-layer-group\"></i></span>\r\n        <h3>End-to-End Support</h3>\r\n        <p>Comprehensive guidance across planning, development, design, and everyday operations.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-user-check\"></i></span>\r\n        <h3>Guest-Centred Thinking</h3>\r\n        <p>Dedicated focus on elevating guest satisfaction, food quality, and service standards.</p>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 5: CTA -->\r\n<section class=\"cta\">\r\n  <div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n    <span class=\"eyebrow\">Let\'s Work Together</span>\r\n    <h2>Ready to Build or Elevate Your Hospitality Venture?</h2>\r\n    <p>Connect with our leadership and operations team to discuss kitchen planning, recruitment, or end-to-end hospitality consultancy.</p>\r\n    <div class=\"cta-btns\">\r\n      <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-light\">Start a Conversation <span class=\"arrow\">↗</span></a>\r\n      <a href=\"tel:+918951511234\" class=\"btn btn-outline-light\">Call Us Today</a>\r\n    </div>\r\n  </div>\r\n</section>', 'About', '', 'publish', 'closed', 'closed', '', 'about', '', '', '2026-11-26 09:03:38', '2026-11-26 09:03:38', '', 0, 'http://localhost/artha-hospitality-management/?page_id=11', 0, 'page', '', 0);
INSERT INTO `wp_posts` VALUES(12, 1, '2026-11-26 05:42:49', '2026-11-26 05:42:49', '', 'About', '', 'inherit', 'closed', 'closed', '', '11-revision-v1', '', '', '2026-11-26 05:42:49', '2026-11-26 05:42:49', '', 11, 'http://localhost/artha-hospitality-management/?p=12', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(13, 1, '2026-11-27 09:22:29', '2026-11-26 05:43:00', ' ', '', '', 'publish', 'closed', 'closed', '', '13', '', '', '2026-11-27 09:22:29', '2026-11-27 09:22:29', '', 0, 'http://localhost/artha-hospitality-management/?p=13', 2, 'nav_menu_item', '', 0);
INSERT INTO `wp_posts` VALUES(14, 1, '2026-11-26 05:49:02', '2026-11-26 05:49:02', '<article>\r\n<!-- UNIQUE 75VH HERO -->\r\n<section class=\"ind-hero\" id=\"industries-top\">\r\n  <div class=\"wrap ind-hero-grid\">\r\n    <div class=\"ind-hero-copy\">\r\n      <div class=\"hero-top-tags\">\r\n        <div class=\"crumb-badge\">\r\n          <a href=\"http://localhost/artha-hospitality-management/\">Home</a>\r\n          <span class=\"sep\" aria-hidden=\"true\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <span class=\"curr\">Industries We Serve</span>\r\n        </div>\r\n        <span class=\"eyebrow\">Hospitality Sectors</span>\r\n      </div>\r\n      <h1>Operational Excellence Across <em>Every Hospitality Format.</em></h1>\r\n      <p>From boutique hotels and fine-dining restaurants to high-energy resto-bars, neighbourhood cafés, and delivery-first cloud kitchens, Artha builds systems tailored to how each format actually operates.</p>\r\n      <div class=\"ind-hero-ctas\">\r\n        <a href=\"http://localhost/artha-hospitality-management/contact-us#contact-form-section\" class=\"btn btn-primary\">Book a Free Consultation <span class=\"arrow\">&rarr;</span></a>\r\n        <a href=\"#sectors\" class=\"btn btn-ghost\">Explore Sectors</a>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"ind-hero-stage\" aria-hidden=\"true\">\r\n      <div class=\"ind-stage-backdrop\"></div>\r\n      <div class=\"ind-stage-dots\"></div>\r\n      <div class=\"ind-shape-ring\"></div>\r\n      <div class=\"ind-shape-obsidian\"></div>\r\n      <div class=\"ind-shape-pill\"></div>\r\n\r\n      <div class=\"ind-stage-photo\">\r\n        <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-mangement-hotels-img.jpg\" alt=\"Luxury hotel room and hospitality operations\">\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 1: CORE HOSPITALITY SECTORS -->\r\n<section id=\"sectors\" class=\"sectors-sec\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Core Sectors</span>\r\n      <h2>Specialized Solutions for Diverse Hospitality Venues.</h2>\r\n      <p>Every concept has distinct guest expectations, kitchen workflows, and staffing structures. We align capital, space, and daily execution to your format.</p>\r\n    </div>\r\n\r\n    <div class=\"sectors-grid\">\r\n      <article class=\"sector-card\">\r\n        <div class=\"sector-media\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-mangement-restruant-img.jpg\" alt=\"Fine dining and casual restaurant interior\" loading=\"lazy\">\r\n          <span class=\"sector-pill\">Dining</span>\r\n        </div>\r\n        <div class=\"sector-body\">\r\n          <h3>Restaurants &amp; Specialty Dining</h3>\r\n          <p>End-to-end support for fine dining, casual family restaurants, and regional specialty outlets—balancing ambiance, kitchen speed, and table turnover.</p>\r\n          <ul class=\"sector-points\">\r\n            <li><i class=\"fas fa-check\"></i> Kitchen &amp; dining flow planning</li>\r\n            <li><i class=\"fas fa-check\"></i> Chef, steward &amp; captain staffing</li>\r\n            <li><i class=\"fas fa-check\"></i> Food cost &amp; portion control SOPs</li>\r\n          </ul>\r\n        </div>\r\n      </article>\r\n\r\n      <article class=\"sector-card\">\r\n        <div class=\"sector-media\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-mangement-hotels-img.jpg\" alt=\"Business hotel and boutique stay\" loading=\"lazy\">\r\n          <span class=\"sector-pill\">Stays</span>\r\n        </div>\r\n        <div class=\"sector-body\">\r\n          <h3>Hotels &amp; Boutique Properties</h3>\r\n          <p>Structured pre-opening, multi-outlet F&amp;B coordination, and trained front-office and housekeeping teams that elevate guest satisfaction.</p>\r\n          <ul class=\"sector-points\">\r\n            <li><i class=\"fas fa-check\"></i> Front office &amp; housekeeping systems</li>\r\n            <li><i class=\"fas fa-check\"></i> Room service &amp; all-day dining setup</li>\r\n            <li><i class=\"fas fa-check\"></i> Service quality audits &amp; training</li>\r\n          </ul>\r\n        </div>\r\n      </article>\r\n\r\n      <article class=\"sector-card\">\r\n        <div class=\"sector-media\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-mangement-pub-and-resto-img.jpg\" alt=\"Pub and resto-bar interior\" loading=\"lazy\">\r\n          <span class=\"sector-pill\">Nightlife</span>\r\n        </div>\r\n        <div class=\"sector-body\">\r\n          <h3>Pubs, Resto-Bars &amp; Lounges</h3>\r\n          <p>High-throughput bar stations, atmosphere-driven interiors, beverage inventory controls, and agile floor service built for peak weekend volume.</p>\r\n          <ul class=\"sector-points\">\r\n            <li><i class=\"fas fa-check\"></i> Bar ergonomics &amp; dispense flow</li>\r\n            <li><i class=\"fas fa-check\"></i> Bartender &amp; floor team hiring</li>\r\n            <li><i class=\"fas fa-check\"></i> Beverage cost &amp; shrinkage control</li>\r\n          </ul>\r\n        </div>\r\n      </article>\r\n\r\n      <article class=\"sector-card\">\r\n        <div class=\"sector-media\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-location-selection-overview.jpg\" alt=\"Modern café and bakery seating\" loading=\"lazy\">\r\n          <span class=\"sector-pill\">Cafés</span>\r\n        </div>\r\n        <div class=\"sector-body\">\r\n          <h3>Cafés, Bakeries &amp; Patisseries</h3>\r\n          <p>Neighbourhood site selection, compact espresso-bar layouts, and consistent barista and counter service for steady all-day footfall.</p>\r\n          <ul class=\"sector-points\">\r\n            <li><i class=\"fas fa-check\"></i> High-visibility location scouting</li>\r\n            <li><i class=\"fas fa-check\"></i> Compact counter &amp; display design</li>\r\n            <li><i class=\"fas fa-check\"></i> Barista &amp; bakery staff sourcing</li>\r\n          </ul>\r\n        </div>\r\n      </article>\r\n\r\n      <article class=\"sector-card\">\r\n        <div class=\"sector-media\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-kitchen-design-hero.jpg\" alt=\"Commercial cloud kitchen workflow\" loading=\"lazy\">\r\n          <span class=\"sector-pill\">Delivery</span>\r\n        </div>\r\n        <div class=\"sector-body\">\r\n          <h3>Cloud Kitchens &amp; QSR Hubs</h3>\r\n          <p>Efficiency-first commercial kitchens engineered for rapid ticket times, low overhead, multi-brand output, and strict packaging and hygiene standards.</p>\r\n          <ul class=\"sector-points\">\r\n            <li><i class=\"fas fa-check\"></i> Zero-bottleneck prep &amp; dispatch zones</li>\r\n            <li><i class=\"fas fa-check\"></i> Vendor &amp; bulk purchase negotiation</li>\r\n            <li><i class=\"fas fa-check\"></i> Unit-level running cost optimization</li>\r\n          </ul>\r\n        </div>\r\n      </article>\r\n\r\n      <article class=\"sector-card\">\r\n        <div class=\"sector-media\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/slide-img-2-lgr.jpg\" alt=\"Luxury resort and banquet venue\" loading=\"lazy\">\r\n          <span class=\"sector-pill\">Events</span>\r\n        </div>\r\n        <div class=\"sector-body\">\r\n          <h3>Resorts &amp; Banquet Venues</h3>\r\n          <p>High-capacity banquet kitchens, outdoor-indoor service logistics, and scalable hospitality teams for destination stays and large celebrations.</p>\r\n          <ul class=\"sector-points\">\r\n            <li><i class=\"fas fa-check\"></i> Bulk kitchen &amp; cold-chain planning</li>\r\n            <li><i class=\"fas fa-check\"></i> Event F&amp;B &amp; banquet staffing</li>\r\n            <li><i class=\"fas fa-check\"></i> Five-star guest experience standards</li>\r\n          </ul>\r\n        </div>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 2: HOW WE TAILOR BY FORMAT -->\r\n<section id=\"matrix\" class=\"tailor-sec\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-split anim-base anim-fade-right\">\r\n      <div>\r\n        <span class=\"eyebrow\">Format-Specific Execution</span>\r\n        <h2>One Methodology, Customized to Your Business Model.</h2>\r\n      </div>\r\n      <p>Whether you are launching a 30-seat neighbourhood café or a full-service hotel, we adapt four core pillars to protect your investment and service standards.</p>\r\n    </div>\r\n\r\n    <div class=\"tailor-grid\">\r\n      <article class=\"tailor-card\">\r\n        <span class=\"tailor-num\">01</span>\r\n        <h3>Capital &amp; Feasibility</h3>\r\n        <p>Format-accurate CapEx budgets, equipment schedules, and break-even projections before civil work begins.</p>\r\n      </article>\r\n      <article class=\"tailor-card\">\r\n        <span class=\"tailor-num\">02</span>\r\n        <h3>Spatial &amp; Kitchen Flow</h3>\r\n        <p>Custom front-of-house seating ratios and back-of-house kitchen layouts tailored to your menu and cover volume.</p>\r\n      </article>\r\n      <article class=\"tailor-card\">\r\n        <span class=\"tailor-num\">03</span>\r\n        <h3>Staffing &amp; Training</h3>\r\n        <p>Verified recruitment across chefs, front office, housekeeping, baristas, and F&amp;B service aligned to your outlet tier.</p>\r\n      </article>\r\n      <article class=\"tailor-card\">\r\n        <span class=\"tailor-num\">04</span>\r\n        <h3>Cost &amp; Quality SOPs</h3>\r\n        <p>Daily food cost tracking, vendor audits, and guest service checklists that keep quality consistent after launch.</p>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 3: STRATEGIC IMPACT -->\r\n<section id=\"value\" class=\"impact-sec\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">The Artha Advantage</span>\r\n      <h2>Built for Owners Seeking Long-Term Operational Clarity.</h2>\r\n    </div>\r\n\r\n    <div class=\"impact-grid\">\r\n      <article class=\"impact-card\">\r\n        <span class=\"impact-ic\" aria-hidden=\"true\"><i class=\"fas fa-compass-drafting\"></i></span>\r\n        <h3>Format-Specific Blueprints</h3>\r\n        <p>No cookie-cutter templates—every layout, staffing roster, and vendor list is built around your exact cuisine, seating, and city market.</p>\r\n      </article>\r\n      <article class=\"impact-card\">\r\n        <span class=\"impact-ic\" aria-hidden=\"true\"><i class=\"fas fa-layer-group\"></i></span>\r\n        <h3>End-to-End Execution</h3>\r\n        <p>Single-point coordination from location scouting and civil interiors to pre-opening launch and ongoing staff recruitment.</p>\r\n      </article>\r\n      <article class=\"impact-card\">\r\n        <span class=\"impact-ic\" aria-hidden=\"true\"><i class=\"fas fa-chart-line\"></i></span>\r\n        <h3>Sustainable Unit Economics</h3>\r\n        <p>Practical cost controls and verified vendor partnerships that protect margins without compromising the guest experience.</p>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- CTA -->\r\n<section class=\"cta\">\r\n  <div class=\"wrap\">\r\n    <div class=\"cta-split-grid\">\r\n      <article class=\"cta-box\">\r\n        <span class=\"cta-box-ic\" aria-hidden=\"true\"><i class=\"fas fa-hotel\"></i></span>\r\n        <span class=\"eyebrow\">FOR HOTEL OWNERS</span>\r\n        <h2>Need Staff for Your Hotel?</h2>\r\n        <p>Hire trained, verified staff with Artha.</p>\r\n        <a href=\"http://localhost/artha-hospitality-management/contact-us#contact-form-section\" class=\"btn\">Hire Staff Now <span class=\"arrow\">&rarr;</span></a>\r\n      </article>\r\n\r\n      <article class=\"cta-box\">\r\n        <span class=\"cta-box-ic\" aria-hidden=\"true\"><i class=\"fas fa-briefcase\"></i></span>\r\n        <span class=\"eyebrow\">FOR JOB SEEKERS</span>\r\n        <h2>Looking for a Hotel Job?</h2>\r\n        <p>Apply for Chef, Front Office, Housekeeping &amp; F&amp;B jobs.</p>\r\n        <a href=\"http://localhost/artha-hospitality-management/#job-opportunities\" class=\"btn\">Apply for Jobs <span class=\"arrow\">&rarr;</span></a>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n</article>', 'Industries', '', 'publish', 'closed', 'closed', '', 'industries', '', '', '2026-11-26 09:55:29', '2026-11-26 09:55:29', '', 0, 'http://localhost/artha-hospitality-management/?page_id=14', 0, 'page', '', 0);
INSERT INTO `wp_posts` VALUES(15, 1, '2026-11-26 05:49:02', '2026-11-26 05:49:02', 'sdlfhsjkdhf', 'Industries', '', 'inherit', 'closed', 'closed', '', '14-revision-v1', '', '', '2026-11-26 05:49:02', '2026-11-26 05:49:02', '', 14, 'http://localhost/artha-hospitality-management/?p=15', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(17, 1, '2026-11-26 05:53:15', '2026-11-26 05:53:15', '<!-- NEW 75VH ABOUT US HERO SECTION -->\r\n\r\n<section id=\"about-top\" class=\"about-editorial-hero\">\r\n<div class=\"wrap hero-inner\">\r\n\r\n<!-- Column 1: Editorial Copy & CTAs -->\r\n<div class=\"hero-story-col anim-base anim-fade-right\">\r\n<div class=\"hero-top-tags\"><nav class=\"breadcrumb-pill\" aria-label=\"Breadcrumb\"><a href=\"index.html\">Home</a>\r\n<i class=\"fas fa-chevron-right\"></i>\r\n<span class=\"current\">About Us</span></nav><span class=\"eyebrow\">Who We Are</span>\r\n\r\n</div>\r\n<h1>Shaping the Future of <em>Thoughtful Hospitality</em> From Concept to Table.</h1>\r\nAt Artha Hospitality Management, we partner with visionary restaurateurs, hoteliers, and hospitality entrepreneurs to turn ambitious concepts into resilient, high-performing destinations.\r\n<div class=\"hero-cta-group\"><a class=\"btn btn-primary\" href=\"artha-hospitality-contact-us.html\">Partner With Artha <span class=\"arrow\">↗</span></a>\r\n<a class=\"btn btn-ghost\" href=\"index.html#services\">Our Capabilities</a></div>\r\n</div>\r\n<!-- Column 2: Single Image Sculptural Stage with Theme Shapes -->\r\n<div class=\"hero-visual-stage anim-base anim-fade-left delay-100\"><!-- Shape 1: Concentric Gold Contour Rings -->\r\n\r\n\r\n\r\n\r\n<!-- Shape 2: Deep Espresso Architectural Offset Slab -->\r\n<div class=\"stage-shape-slab\" aria-hidden=\"true\"></div>\r\n<!-- Shape 3: Gold Offset Wireframe Arch -->\r\n<div class=\"stage-shape-wireframe\" aria-hidden=\"true\"></div>\r\n<!-- Shape 4: Gold Dot Matrix Pattern -->\r\n<div class=\"stage-shape-dots\" aria-hidden=\"true\"></div>\r\n<!-- Shape 5: Floating Espresso & Gold Medallion Seal -->\r\n<div class=\"stage-medallion\"><i class=\"fas fa-award\"></i>\r\n<div class=\"med-text\"><strong>15+ Yrs</strong>\r\nHospitality Mastery</div>\r\n</div>\r\n<!-- Main Sculpted Arched Image Panel -->\r\n<div class=\"hero-arch-panel\">\r\n<figure class=\"cr-figure\"><img src=\"images/artha-hospitality-about-us-hero.jpg\" alt=\"Hospitality team collaborating in a professional kitchen\" /><figcaption class=\"cr-only\">Hospitality team collaborating in a professional kitchen</figcaption></figure>\r\n<div class=\"arch-caption-bar\">\r\n<div><span class=\"tag-sub\">Operational Craft</span>\r\n<span class=\"tag-title\">Ground-Level Expertise</span></div>\r\n&nbsp;\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 1: ENGAGING ABOUT ARTHA HOSPITALITY -->\r\n\r\n<section id=\"about-artha\" class=\"about-artha-section\">\r\n<div class=\"wrap\">\r\n<div class=\"about-artha-grid\">\r\n\r\n<!-- Story & Philosophy Copy -->\r\n<div class=\"artha-story-copy anim-base anim-fade-right\"><span class=\"eyebrow\">About Us</span>\r\n<h2>Hospitality Begins With <em>Great Service.</em></h2>\r\n<p class=\"lead-p\">At Artha, we believe that great hospitality begins with great service. Our mission is to help restaurant owners and hospitality businesses overcome their toughest service challenges, improve guest satisfaction, and grow sustainably.</p>\r\nWith a deep understanding of the industry and a commitment to excellence, we provide tailor-made solutions that create lasting value for our partners.\r\n<div class=\"artha-values-list\">\r\n<div class=\"artha-value-item\"><i class=\"fas fa-hotel\"></i>\r\n<div>\r\n<h4>Industry Understanding</h4>\r\nGrounded in more than 15 years of hospitality and hotel operations experience.\r\n\r\n</div>\r\n</div>\r\n<div class=\"artha-value-item\"><i class=\"fas fa-star\"></i>\r\n<div>\r\n<h4>Tailor-Made Solutions</h4>\r\nApproaches shaped around your business, your guests, and your operational goals.\r\n\r\n</div>\r\n</div>\r\n<div class=\"artha-value-item\"><i class=\"fas fa-check-circle\"></i>\r\n<div>\r\n<h4>Commitment to Excellence</h4>\r\nA consistent focus on quality, service standards, and sustainable long-term growth.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n<a class=\"btn btn-primary\" href=\"index.html#services\">Discover What We Do <span class=\"arrow\">↗</span></a>\r\n\r\n</div>\r\n<!-- Layered Hospitality Collage -->\r\n<div class=\"artha-story-visual anim-base anim-fade-left delay-100\">\r\n<div class=\"artha-vis-tag\"><i class=\"fas fa-compass\"></i>\r\n<div>15+ Years Experience\r\n<strong>Solutions That Work From Day One</strong></div>\r\n</div>\r\n<div class=\"artha-vis-main\">\r\n<figure class=\"cr-figure\"><img src=\"images/slide-img-2-lgr.jpg\" alt=\"Elegant hospitality reception and dining space\" /><figcaption class=\"cr-only\">Elegant hospitality reception and dining space</figcaption></figure>\r\n</div>\r\n<div class=\"artha-vis-sub\">\r\n<figure class=\"cr-figure\"><img src=\"images/artha-hospitality-management-about-us-sml-img.jpg\" alt=\"Premium restaurant dining environment\" /><figcaption class=\"cr-only\">Premium restaurant dining environment</figcaption></figure>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 2: LEADERSHIP & VISION + CEO SPOTLIGHT (VIHANI ANIL) -->\r\n\r\n<section id=\"vihani-anil\" class=\"leader-spotlight bg-sand-light\">\r\n<div class=\"wrap\">\r\n<div class=\"head-center anim-base anim-fade-right\"><span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>The Minds Driving Culinary, People &amp; Operational Excellence.</h2>\r\nGuided by visionary leadership, seasoned hospitality veterans, kitchen innovators, HR strategists, and operations leaders committed to building resilient, people-first hospitality ventures.\r\n\r\n</div>\r\n<div class=\"spotlight-grid\">\r\n\r\n<!-- Portrait Column -->\r\n<div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-frame\">\r\n<figure class=\"cr-figure\"><img src=\"images/vihani-anil.jpg\" alt=\"Vihani Anil - Future CEO, Artha Hospitality Management\" /><figcaption class=\"cr-only\">Vihani Anil - Future CEO | Artha Hospitality Management</figcaption></figure>\r\n</div>\r\n<div class=\"portrait-exp-badge\"><strong>Future</strong>\r\nCEO · Artha\r\nHospitality</div>\r\n</div>\r\n<!-- Biography & Vision Column -->\r\n<div class=\"leader-copy anim-base anim-fade-left delay-100\"><span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>Vihani Anil</h2>\r\n<div class=\"role-pill\"><i class=\"fas fa-crown\"></i>\r\nFuture CEO | Artha Hospitality Management</div>\r\n<div class=\"leader-bio\">\r\n\r\nVihani Anil is the Future CEO of Artha Hospitality Management, representing the next generation of strategic leadership, brand vision, and client-first hospitality advisory across India.\r\n\r\nGuided by the principle <em>Dream · Plan · Achieve</em>, she brings a forward-looking perspective to modern hospitality consulting—bridging creative concept development with disciplined business planning and sustainable growth.\r\n\r\nHer leadership focus centres on empowering restaurant, café, hotel, cloud kitchen, and resort founders with clarity, structured execution, and long-term operational confidence from day one.\r\n\r\n</div>\r\n<div class=\"leader-chips\">Future Leadership\r\nBrand Strategy\r\nClient Partnerships\r\nBusiness Growth\r\nHospitality Innovation\r\nStrategic Planning</div>\r\n<div class=\"vision-callout\">\r\n<div class=\"vc-head\"><i class=\"fas fa-compass\"></i>\r\nFuture Vision &amp; Leadership</div>\r\nAs Future CEO, Vihani champions a culture of excellence, transparency, and purposeful execution—ensuring every hospitality venture partnered with Artha transforms ambitious ideas into thriving, guest-loved destinations.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 3: FOUNDER & DIRECTOR SPOTLIGHT (ANIL KUMAR K) -->\r\n\r\n<section id=\"anil-kumar\" class=\"leader-spotlight bg-offwhite\">\r\n<div class=\"wrap\">\r\n<div class=\"spotlight-grid reverse\">\r\n\r\n<!-- Biography & Vision Column -->\r\n<div class=\"leader-copy anim-base anim-fade-right\"><span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>Anil Kumar K</h2>\r\n<div class=\"role-pill\"><i class=\"fas fa-chess-king\"></i>\r\nFounder &amp; Director – Artha Hospitality</div>\r\n<div class=\"leader-bio\">\r\n\r\nChef Anil Kumar K is the Founder &amp; Director of Artha Hospitality, bringing over 25 years of experience in the hospitality industry.\r\n\r\nWith a professional background as a Chef, Anil has extensive hands-on experience in professional kitchens, restaurant operations, kitchen planning, commercial kitchen equipment, food production, and hospitality management.\r\n\r\nHis 25 years of industry experience provide him with a deep understanding of the practical requirements of hotels, restaurants, cafés, catering businesses, and commercial food-service operations.\r\n\r\n</div>\r\n<div class=\"leader-chips\">Professional Kitchens\r\nRestaurant Operations\r\nKitchen Planning\r\nCommercial Kitchen Equipment\r\nFood Production\r\nHospitality Management</div>\r\n<div class=\"vision-callout\">\r\n<div class=\"vc-head\"><i class=\"fas fa-compass\"></i>\r\nStrategic Vision &amp; Leadership</div>\r\nAs Founder &amp; Director of Artha Hospitality, Anil leads the company’s business strategy, kitchen solutions, operational planning, client relationships, and overall execution, with a vision to deliver reliable, efficient, and sustainable hospitality solutions.\r\n\r\n</div>\r\n</div>\r\n<!-- Portrait Column -->\r\n<div class=\"leader-portrait-stage anim-base anim-fade-left delay-100\">\r\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-frame\">\r\n<figure class=\"cr-figure\"><img src=\"images/about-us-images/anil-kumar-k.jpg\" alt=\"Chef Anil Kumar K - Founder &amp; Director of Artha Hospitality\" /><figcaption class=\"cr-only\">Chef Anil Kumar K - Founder &amp; Director – Artha Hospitality</figcaption></figure>\r\n</div>\r\n<div class=\"portrait-exp-badge\"><strong>25+</strong>\r\nYears in\r\nHospitality</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 4: HR DIRECTOR SPOTLIGHT - SUSHMA AMIN -->\r\n\r\n<section id=\"sushma-amin\" class=\"leader-spotlight bg-sand-light\">\r\n<div class=\"wrap spotlight-grid\">\r\n\r\n<!-- Portrait Column -->\r\n<div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-frame\">\r\n<figure class=\"cr-figure\"><img src=\"images/about-us-images/sushma-amin.jpg\" alt=\"Sushma Amin - HR Director &amp; Hospitality HR Professional\" /><figcaption class=\"cr-only\">Sushma Amin - HR Director &amp; Hospitality HR Professional</figcaption></figure>\r\n</div>\r\n<div class=\"portrait-exp-badge\"><strong>20+</strong>\r\nYears in HR &amp;\r\nHospitality</div>\r\n</div>\r\n<!-- Biography & Vision Column -->\r\n<div class=\"leader-copy anim-base anim-fade-left delay-100\"><span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>Sushma Amin</h2>\r\n<div class=\"role-pill\"><i class=\"fas fa-balance-scale\"></i>\r\nHR Director &amp; Hospitality HR Professional</div>\r\n<div class=\"leader-bio\">\r\n\r\nSushma Amin is a seasoned Human Resources professional with over 20 years of experience in the HR and hospitality industry, bringing extensive expertise in people management, talent acquisition, employee relations, HR operations, and organizational development.\r\n\r\nWith a strong academic background in Bachelor of Arts (BA) and Bachelor of Laws (LLB), she combines professional knowledge with practical industry experience to build effective HR practices and people-centric workplaces.\r\n\r\nThroughout her career, she has worked with leading hospitality establishments, gaining valuable experience in managing diverse workforces, developing HR systems, streamlining recruitment processes, and supporting business growth through effective human resource management.\r\n\r\n</div>\r\n<div class=\"leader-chips\">People Management\r\nTalent Acquisition\r\nEmployee Relations\r\nHR Operations\r\nOrganizational Development\r\nBA &amp; LLB</div>\r\n<div class=\"vision-callout\">\r\n<div class=\"vc-head\"><i class=\"fas fa-bullseye\"></i>\r\nProfessional Vision</div>\r\nHer professional vision is to connect the right talent with the right opportunities, empower people, strengthen organizations, and contribute to the growth of the hospitality industry through ethical, transparent, and result-oriented HR practices.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 4: ARTHA EXECUTIVE MANAGEMENT (SNEHA M. & SANDEEP SHETTY) -->\r\n\r\n<section id=\"executive-management\" class=\"management-section\">\r\n<div class=\"wrap\">\r\n<div class=\"head-center anim-base anim-fade-right\"><span class=\"eyebrow\">Artha Hospitality Team</span>\r\n<h2>Driving Recruitment, Sales &amp; Operational Excellence.</h2>\r\nConnecting talented hospitality professionals with leading organizations and delivering disciplined, guest-focused operational results every day.\r\n\r\n</div>\r\n<!-- Profile 1: Sneha M. -->\r\n\r\n<article class=\"exec-profile-block anim-base anim-fade-up\">\r\n<div class=\"exec-top-grid\">\r\n<div class=\"exec-photo-wrap\">\r\n<div class=\"exec-photo-frame\">\r\n<figure class=\"cr-figure\"><img src=\"images/about-us-images/sneha-m.jpg\" alt=\"Sneha M. - HR Executive at Artha Hospitality\" /><figcaption class=\"cr-only\">Sneha M. - HR Executive | Artha Hospitality</figcaption></figure>\r\n</div>\r\n</div>\r\n<div class=\"exec-intro\"><span class=\"eyebrow\">People &amp; Talent</span>\r\n<h3>Sneha M.</h3>\r\n<div class=\"exec-role\"><i class=\"fas fa-id-badge\"></i>\r\nHR Executive | Artha Hospitality</div>\r\nAs an HR Executive at Artha Hospitality, I am responsible for identifying, attracting and connecting the right talent with the right opportunities in the hospitality industry.\r\n\r\nI believe that successful businesses are built by the right people. My focus is on understanding client requirements, building strong relationships with candidates and ensuring a smooth and effective recruitment process.\r\n\r\n</div>\r\n</div>\r\n<div class=\"exec-pillars-grid\">\r\n<div class=\"pillar-box\">\r\n<div class=\"pb-head\"><i class=\"fas fa-eye\"></i>\r\n<h4>My Vision</h4>\r\n</div>\r\nTo connect talented individuals with the right opportunities and help hospitality businesses grow through quality recruitment, trust and strong professional relationships.\r\n\r\n</div>\r\n<div class=\"pillar-box dark\">\r\n<div class=\"pb-head\"><i class=\"fas fa-bullseye\"></i>\r\n<h4>My Mission</h4>\r\n</div>\r\nTo make recruitment a meaningful experience by bringing together the right people and the right organizations.\r\n\r\n</div>\r\n</div>\r\n</article><!-- Profile 2: Sandeep Shetty -->\r\n\r\n<article class=\"exec-profile-block reverse anim-base anim-fade-up\">\r\n<div class=\"exec-top-grid\">\r\n<div class=\"exec-intro\"><span class=\"eyebrow\">Growth &amp; Operations</span>\r\n<h3>Sandeep Shetty</h3>\r\n<div class=\"exec-role\"><i class=\"fas fa-briefcase\"></i>\r\nSales &amp; Operations Manager | Artha Hospitality</div>\r\nAs a Sales &amp; Operations Manager at Artha Hospitality, I am responsible for driving business growth, leading operations, and creating exceptional guest experiences in the hospitality industry.\r\n\r\nI believe that successful hospitality businesses are built on strong leadership, consistent service, and the right people. My focus is on understanding client needs, building lasting business relationships, and ensuring smooth, result-driven operations.\r\n\r\n</div>\r\n<div class=\"exec-photo-wrap\">\r\n<div class=\"exec-photo-frame\">\r\n<figure class=\"cr-figure\"><img src=\"images/about-us-images/sandeep-shetty.jpg\" alt=\"Sandeep Shetty - Sales &amp; Operations Manager at Artha Hospitality\" /><figcaption class=\"cr-only\">Sandeep Shetty - Sales &amp; Operations Manager | Artha Hospitality</figcaption></figure>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"exec-pillars-grid cols-3\">\r\n<div class=\"pillar-box dark\">\r\n<div class=\"pb-head\"><i class=\"fas fa-chess-knight\"></i>\r\n<h4>My Leadership</h4>\r\n</div>\r\nI lead by example — with clarity, accountability, and a people-first approach. My leadership is focused on building high-performing teams, empowering individuals, and creating a culture of ownership, discipline, and excellence.\r\n\r\nI believe a great leader doesn\'t just manage operations; they inspire people to deliver their best every single day.\r\n\r\n</div>\r\n<div class=\"pillar-box\">\r\n<div class=\"pb-head\"><i class=\"fas fa-eye\"></i>\r\n<h4>My Vision</h4>\r\n</div>\r\nTo lead Artha Hospitality towards sustainable growth by combining strong sales strategies, operational excellence, and meaningful human connections — and to make it a trusted name in the hospitality industry.\r\n\r\n</div>\r\n<div class=\"pillar-box\">\r\n<div class=\"pb-head\"><i class=\"fas fa-rocket\"></i>\r\n<h4>My Mission</h4>\r\n</div>\r\nTo drive sales with integrity, deliver operations with excellence, and create value for clients, guests, and the team — by bringing together the right strategy, the right people, and the right execution.\r\n\r\n</div>\r\n</div>\r\n</article></div>\r\n</section><!-- WHY CHOOSE US SECTION -->\r\n\r\n<section id=\"why-choose-us\" class=\"why-choose-section\">\r\n<div class=\"wrap\">\r\n<div class=\"why-choose-head anim-base anim-fade-up\"><span class=\"eyebrow\">Why Choose Us?</span>\r\n<h2>Experience That Turns Ideas Into Successful Operations.</h2>\r\n“Backed by over <em>15 years</em> of experience in hospitality and hotel operations, our team combines industry insight with proven strategies to deliver solutions that work from day one.”\r\n\r\n</div>\r\n<div class=\"why-choose-grid\"><article class=\"why-choose-card anim-base anim-fade-up delay-100\"><i class=\"fas fa-award\"></i>\r\n<h3>Industry Experience</h3>\r\nMore than 15 years of hands-on experience in hospitality and hotel operations.\r\n\r\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-200\"><i class=\"fas fa-chart-line\"></i>\r\n<h3>Strategic Approach</h3>\r\nSolutions built around your specific business requirements and operational objectives.\r\n\r\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-300\"><i class=\"fas fa-layer-group\"></i>\r\n<h3>End-to-End Support</h3>\r\nComprehensive guidance across planning, development, design, and everyday operations.\r\n\r\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-300\"><i class=\"fas fa-user-check\"></i>\r\n<h3>Guest-Centred Thinking</h3>\r\nDedicated focus on elevating guest satisfaction, food quality, and service standards.\r\n\r\n</article></div>\r\n</div>\r\n</section><!-- SECTION 5: CTA -->\r\n\r\n<section class=\"cta\">\r\n<div class=\"wrap cta-inner anim-base anim-zoom-in\"><span class=\"eyebrow\">Let\'s Work Together</span>\r\n<h2>Ready to Build or Elevate Your Hospitality Venture?</h2>\r\nConnect with our leadership and operations team to discuss kitchen planning, recruitment, or end-to-end hospitality consultancy.\r\n<div class=\"cta-btns\"><a class=\"btn btn-light\" href=\"artha-hospitality-contact-us.html\">Start a Conversation <span class=\"arrow\">↗</span></a>\r\n<a class=\"btn btn-outline-light\" href=\"tel:+918951511234\">Call Us Today</a></div>\r\n</div>\r\n</section>', 'About', '', 'inherit', 'closed', 'closed', '', '11-revision-v1', '', '', '2026-11-26 05:53:15', '2026-11-26 05:53:15', '', 11, 'http://localhost/artha-hospitality-management/?p=17', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(18, 1, '2026-11-26 05:54:17', '2026-11-26 05:54:17', '<!-- NEW 75VH ABOUT US HERO SECTION -->\n\n<section id=\"about-top\" class=\"about-editorial-hero\">\n<div class=\"wrap hero-inner\">\n\n<!-- Column 1: Editorial Copy & CTAs -->\n<div class=\"hero-story-col anim-base anim-fade-right\">\n<div class=\"hero-top-tags\"><nav class=\"breadcrumb-pill\" aria-label=\"Breadcrumb\"><a href=\"index.html\">Home</a>\n<i class=\"fas fa-chevron-right\"></i>\n<span class=\"current\">About Us</span></nav><span class=\"eyebrow\">Who We Are</span>\n\n</div>\n<h1>Shaping the Future of <em>Thoughtful Hospitality</em> From Concept to Table.</h1>\nAt Artha Hospitality Management, we partner with visionary restaurateurs, hoteliers, and hospitality entrepreneurs to turn ambitious concepts into resilient, high-performing destinations.\n<div class=\"hero-cta-group\"><a class=\"btn btn-primary\" href=\"artha-hospitality-contact-us.html\">Partner With Artha <span class=\"arrow\">↗</span></a>\n<a class=\"btn btn-ghost\" href=\"index.html#services\">Our Capabilities</a></div>\n</div>\n<!-- Column 2: Single Image Sculptural Stage with Theme Shapes -->\n<div class=\"hero-visual-stage anim-base anim-fade-left delay-100\">\n\n<!-- Shape 1: Concentric Gold Contour Rings -->\n\n<!-- Shape 2: Deep Espresso Architectural Offset Slab -->\n<div class=\"stage-shape-slab\" aria-hidden=\"true\"></div>\n<!-- Shape 3: Gold Offset Wireframe Arch -->\n<div class=\"stage-shape-wireframe\" aria-hidden=\"true\"></div>\n<!-- Shape 4: Gold Dot Matrix Pattern -->\n<div class=\"stage-shape-dots\" aria-hidden=\"true\"></div>\n<!-- Shape 5: Floating Espresso & Gold Medallion Seal -->\n<div class=\"stage-medallion\">\n\n&nbsp;\n<div class=\"med-text\"><strong>15+ Yrs</strong>\nHospitality Mastery</div>\n</div>\n<!-- Main Sculpted Arched Image Panel -->\n<div class=\"hero-arch-panel\">\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/artha-hospitality-about-us-hero.jpg\" alt=\"Hospitality team collaborating in a professional kitchen\" /><figcaption class=\"cr-only\">Hospitality team collaborating in a professional kitchen</figcaption></figure>\n<div class=\"arch-caption-bar\">\n<div><span class=\"tag-sub\">Operational Craft</span>\n<span class=\"tag-title\">Ground-Level Expertise</span></div>\n&nbsp;\n\n</div>\n</div>\n</div>\n</div>\n</section><!-- SECTION 1: ENGAGING ABOUT ARTHA HOSPITALITY -->\n\n<section id=\"about-artha\" class=\"about-artha-section\">\n<div class=\"wrap\">\n<div class=\"about-artha-grid\">\n\n<!-- Story & Philosophy Copy -->\n<div class=\"artha-story-copy anim-base anim-fade-right\">\n\n<span class=\"eyebrow\">About Us</span>\n<h2>Hospitality Begins With <em>Great Service.</em></h2>\n<p class=\"lead-p\">At Artha, we believe that great hospitality begins with great service. Our mission is to help restaurant owners and hospitality businesses overcome their toughest service challenges, improve guest satisfaction, and grow sustainably.</p>\nWith a deep understanding of the industry and a commitment to excellence, we provide tailor-made solutions that create lasting value for our partners.\n<div class=\"artha-values-list\">\n<div class=\"artha-value-item\">\n\n&nbsp;\n<div>\n<h4>Industry Understanding</h4>\nGrounded in more than 15 years of hospitality and hotel operations experience.\n\n</div>\n</div>\n<div class=\"artha-value-item\">\n\n&nbsp;\n<div>\n<h4>Tailor-Made Solutions</h4>\nApproaches shaped around your business, your guests, and your operational goals.\n\n</div>\n</div>\n<div class=\"artha-value-item\">\n\n&nbsp;\n<div>\n<h4>Commitment to Excellence</h4>\nA consistent focus on quality, service standards, and sustainable long-term growth.\n\n</div>\n</div>\n</div>\n<a class=\"btn btn-primary\" href=\"index.html#services\">Discover What We Do <span class=\"arrow\">↗</span></a>\n\n</div>\n<!-- Layered Hospitality Collage -->\n<div class=\"artha-story-visual anim-base anim-fade-left delay-100\">\n<div class=\"artha-vis-tag\">\n\n&nbsp;\n<div>15+ Years Experience\n<strong>Solutions That Work From Day One</strong></div>\n</div>\n<div class=\"artha-vis-main\">\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/slide-img-2-lgr.jpg\" alt=\"Elegant hospitality reception and dining space\" /><figcaption class=\"cr-only\">Elegant hospitality reception and dining space</figcaption></figure>\n</div>\n<div class=\"artha-vis-sub\">\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/artha-hospitality-management-about-us-sml-img.jpg\" alt=\"Premium restaurant dining environment\" /><figcaption class=\"cr-only\">Premium restaurant dining environment</figcaption></figure>\n</div>\n</div>\n</div>\n</div>\n</section><!-- SECTION 2: LEADERSHIP & VISION + CEO SPOTLIGHT (VIHANI ANIL) -->\n\n<section id=\"vihani-anil\" class=\"leader-spotlight bg-sand-light\">\n<div class=\"wrap\">\n<div class=\"head-center anim-base anim-fade-right\">\n\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\n<h2>The Minds Driving Culinary, People &amp; Operational Excellence.</h2>\nGuided by visionary leadership, seasoned hospitality veterans, kitchen innovators, HR strategists, and operations leaders committed to building resilient, people-first hospitality ventures.\n\n</div>\n<div class=\"spotlight-grid\">\n\n<!-- Portrait Column -->\n<div class=\"leader-portrait-stage anim-base anim-fade-right\">\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\n<div class=\"portrait-frame\">\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/vihani-anil.jpg\" alt=\"Vihani Anil - Future CEO, Artha Hospitality Management\" /><figcaption class=\"cr-only\">Vihani Anil - Future CEO | Artha Hospitality Management</figcaption></figure>\n</div>\n<div class=\"portrait-exp-badge\"><strong>Future</strong>\nCEO · Artha\nHospitality</div>\n</div>\n<!-- Biography & Vision Column -->\n<div class=\"leader-copy anim-base anim-fade-left delay-100\">\n\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\n<h2>Vihani Anil</h2>\n<div class=\"role-pill\"><i class=\"fas fa-crown\"></i>\nFuture CEO | Artha Hospitality Management</div>\n<div class=\"leader-bio\">\n\nVihani Anil is the Future CEO of Artha Hospitality Management, representing the next generation of strategic leadership, brand vision, and client-first hospitality advisory across India.\n\nGuided by the principle <em>Dream · Plan · Achieve</em>, she brings a forward-looking perspective to modern hospitality consulting—bridging creative concept development with disciplined business planning and sustainable growth.\n\nHer leadership focus centres on empowering restaurant, café, hotel, cloud kitchen, and resort founders with clarity, structured execution, and long-term operational confidence from day one.\n\n</div>\n<div class=\"leader-chips\">Future Leadership\nBrand Strategy\nClient Partnerships\nBusiness Growth\nHospitality Innovation\nStrategic Planning</div>\n<div class=\"vision-callout\">\n<div class=\"vc-head\"><i class=\"fas fa-compass\"></i>\nFuture Vision &amp; Leadership</div>\nAs Future CEO, Vihani champions a culture of excellence, transparency, and purposeful execution—ensuring every hospitality venture partnered with Artha transforms ambitious ideas into thriving, guest-loved destinations.\n\n</div>\n</div>\n</div>\n</div>\n</section><!-- SECTION 3: FOUNDER & DIRECTOR SPOTLIGHT (ANIL KUMAR K) -->\n\n<section id=\"anil-kumar\" class=\"leader-spotlight bg-offwhite\">\n<div class=\"wrap\">\n<div class=\"spotlight-grid reverse\">\n\n<!-- Biography & Vision Column -->\n<div class=\"leader-copy anim-base anim-fade-right\">\n\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\n<h2>Anil Kumar K</h2>\n<div class=\"role-pill\"><i class=\"fas fa-chess-king\"></i>\nFounder &amp; Director – Artha Hospitality</div>\n<div class=\"leader-bio\">\n\nChef Anil Kumar K is the Founder &amp; Director of Artha Hospitality, bringing over 25 years of experience in the hospitality industry.\n\nWith a professional background as a Chef, Anil has extensive hands-on experience in professional kitchens, restaurant operations, kitchen planning, commercial kitchen equipment, food production, and hospitality management.\n\nHis 25 years of industry experience provide him with a deep understanding of the practical requirements of hotels, restaurants, cafés, catering businesses, and commercial food-service operations.\n\n</div>\n<div class=\"leader-chips\">Professional Kitchens\nRestaurant Operations\nKitchen Planning\nCommercial Kitchen Equipment\nFood Production\nHospitality Management</div>\n<div class=\"vision-callout\">\n<div class=\"vc-head\"><i class=\"fas fa-compass\"></i>\nStrategic Vision &amp; Leadership</div>\nAs Founder &amp; Director of Artha Hospitality, Anil leads the company’s business strategy, kitchen solutions, operational planning, client relationships, and overall execution, with a vision to deliver reliable, efficient, and sustainable hospitality solutions.\n\n</div>\n</div>\n<!-- Portrait Column -->\n<div class=\"leader-portrait-stage anim-base anim-fade-left delay-100\">\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\n<div class=\"portrait-frame\">\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/about-us-images/anil-kumar-k.jpg\" alt=\"Chef Anil Kumar K - Founder &amp; Director of Artha Hospitality\" /><figcaption class=\"cr-only\">Chef Anil Kumar K - Founder &amp; Director – Artha Hospitality</figcaption></figure>\n</div>\n<div class=\"portrait-exp-badge\"><strong>25+</strong>\nYears in\nHospitality</div>\n</div>\n</div>\n</div>\n</section><!-- SECTION 4: HR DIRECTOR SPOTLIGHT - SUSHMA AMIN -->\n\n<section id=\"sushma-amin\" class=\"leader-spotlight bg-sand-light\">\n<div class=\"wrap spotlight-grid\">\n\n<!-- Portrait Column -->\n<div class=\"leader-portrait-stage anim-base anim-fade-right\">\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\n<div class=\"portrait-frame\">\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/about-us-images/sushma-amin.jpg\" alt=\"Sushma Amin - HR Director &amp; Hospitality HR Professional\" /><figcaption class=\"cr-only\">Sushma Amin - HR Director &amp; Hospitality HR Professional</figcaption></figure>\n</div>\n<div class=\"portrait-exp-badge\"><strong>20+</strong>\nYears in HR &amp;\nHospitality</div>\n</div>\n<!-- Biography & Vision Column -->\n<div class=\"leader-copy anim-base anim-fade-left delay-100\">\n\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\n<h2>Sushma Amin</h2>\n<div class=\"role-pill\"><i class=\"fas fa-balance-scale\"></i>\nHR Director &amp; Hospitality HR Professional</div>\n<div class=\"leader-bio\">\n\nSushma Amin is a seasoned Human Resources professional with over 20 years of experience in the HR and hospitality industry, bringing extensive expertise in people management, talent acquisition, employee relations, HR operations, and organizational development.\n\nWith a strong academic background in Bachelor of Arts (BA) and Bachelor of Laws (LLB), she combines professional knowledge with practical industry experience to build effective HR practices and people-centric workplaces.\n\nThroughout her career, she has worked with leading hospitality establishments, gaining valuable experience in managing diverse workforces, developing HR systems, streamlining recruitment processes, and supporting business growth through effective human resource management.\n\n</div>\n<div class=\"leader-chips\">People Management\nTalent Acquisition\nEmployee Relations\nHR Operations\nOrganizational Development\nBA &amp; LLB</div>\n<div class=\"vision-callout\">\n<div class=\"vc-head\"><i class=\"fas fa-bullseye\"></i>\nProfessional Vision</div>\nHer professional vision is to connect the right talent with the right opportunities, empower people, strengthen organizations, and contribute to the growth of the hospitality industry through ethical, transparent, and result-oriented HR practices.\n\n</div>\n</div>\n</div>\n</section><!-- SECTION 4: ARTHA EXECUTIVE MANAGEMENT (SNEHA M. & SANDEEP SHETTY) -->\n\n<section id=\"executive-management\" class=\"management-section\">\n<div class=\"wrap\">\n<div class=\"head-center anim-base anim-fade-right\">\n\n<span class=\"eyebrow\">Artha Hospitality Team</span>\n<h2>Driving Recruitment, Sales &amp; Operational Excellence.</h2>\nConnecting talented hospitality professionals with leading organizations and delivering disciplined, guest-focused operational results every day.\n\n</div>\n<!-- Profile 1: Sneha M. -->\n\n<article class=\"exec-profile-block anim-base anim-fade-up\">\n<div class=\"exec-top-grid\">\n<div class=\"exec-photo-wrap\">\n<div class=\"exec-photo-frame\">\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/about-us-images/sneha-m.jpg\" alt=\"Sneha M. - HR Executive at Artha Hospitality\" /><figcaption class=\"cr-only\">Sneha M. - HR Executive | Artha Hospitality</figcaption></figure>\n</div>\n</div>\n<div class=\"exec-intro\">\n\n<span class=\"eyebrow\">People &amp; Talent</span>\n<h3>Sneha M.</h3>\n<div class=\"exec-role\"><i class=\"fas fa-id-badge\"></i>\nHR Executive | Artha Hospitality</div>\nAs an HR Executive at Artha Hospitality, I am responsible for identifying, attracting and connecting the right talent with the right opportunities in the hospitality industry.\n\nI believe that successful businesses are built by the right people. My focus is on understanding client requirements, building strong relationships with candidates and ensuring a smooth and effective recruitment process.\n\n</div>\n</div>\n<div class=\"exec-pillars-grid\">\n<div class=\"pillar-box\">\n<div class=\"pb-head\">\n\n&nbsp;\n<h4>My Vision</h4>\n</div>\nTo connect talented individuals with the right opportunities and help hospitality businesses grow through quality recruitment, trust and strong professional relationships.\n\n</div>\n<div class=\"pillar-box dark\">\n<div class=\"pb-head\">\n\n&nbsp;\n<h4>My Mission</h4>\n</div>\nTo make recruitment a meaningful experience by bringing together the right people and the right organizations.\n\n</div>\n</div>\n</article><!-- Profile 2: Sandeep Shetty -->\n\n<article class=\"exec-profile-block reverse anim-base anim-fade-up\">\n<div class=\"exec-top-grid\">\n<div class=\"exec-intro\">\n\n<span class=\"eyebrow\">Growth &amp; Operations</span>\n<h3>Sandeep Shetty</h3>\n<div class=\"exec-role\"><i class=\"fas fa-briefcase\"></i>\nSales &amp; Operations Manager | Artha Hospitality</div>\nAs a Sales &amp; Operations Manager at Artha Hospitality, I am responsible for driving business growth, leading operations, and creating exceptional guest experiences in the hospitality industry.\n\nI believe that successful hospitality businesses are built on strong leadership, consistent service, and the right people. My focus is on understanding client needs, building lasting business relationships, and ensuring smooth, result-driven operations.\n\n</div>\n<div class=\"exec-photo-wrap\">\n<div class=\"exec-photo-frame\">\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/about-us-images/sandeep-shetty.jpg\" alt=\"Sandeep Shetty - Sales &amp; Operations Manager at Artha Hospitality\" /><figcaption class=\"cr-only\">Sandeep Shetty - Sales &amp; Operations Manager | Artha Hospitality</figcaption></figure>\n</div>\n</div>\n</div>\n<div class=\"exec-pillars-grid cols-3\">\n<div class=\"pillar-box dark\">\n<div class=\"pb-head\">\n\n&nbsp;\n<h4>My Leadership</h4>\n</div>\nI lead by example — with clarity, accountability, and a people-first approach. My leadership is focused on building high-performing teams, empowering individuals, and creating a culture of ownership, discipline, and excellence.\n\nI believe a great leader doesn\'t just manage operations; they inspire people to deliver their best every single day.\n\n</div>\n<div class=\"pillar-box\">\n<div class=\"pb-head\">\n\n&nbsp;\n<h4>My Vision</h4>\n</div>\nTo lead Artha Hospitality towards sustainable growth by combining strong sales strategies, operational excellence, and meaningful human connections — and to make it a trusted name in the hospitality industry.\n\n</div>\n<div class=\"pillar-box\">\n<div class=\"pb-head\">\n\n&nbsp;\n<h4>My Mission</h4>\n</div>\nTo drive sales with integrity, deliver operations with excellence, and create value for clients, guests, and the team — by bringing together the right strategy, the right people, and the right execution.\n\n</div>\n</div>\n</article></div>\n</section><!-- WHY CHOOSE US SECTION -->\n\n<section id=\"why-choose-us\" class=\"why-choose-section\">\n<div class=\"wrap\">\n<div class=\"why-choose-head anim-base anim-fade-up\">\n\n<span class=\"eyebrow\">Why Choose Us?</span>\n<h2>Experience That Turns Ideas Into Successful Operations.</h2>\n“Backed by over <em>15 years</em> of experience in hospitality and hotel operations, our team combines industry insight with proven strategies to deliver solutions that work from day one.”\n\n</div>\n<div class=\"why-choose-grid\"><article class=\"why-choose-card anim-base anim-fade-up delay-100\"><i class=\"fas fa-award\"></i>\n<h3>Industry Experience</h3>\nMore than 15 years of hands-on experience in hospitality and hotel operations.\n\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-200\"><i class=\"fas fa-chart-line\"></i>\n<h3>Strategic Approach</h3>\nSolutions built around your specific business requirements and operational objectives.\n\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-300\"><i class=\"fas fa-layer-group\"></i>\n<h3>End-to-End Support</h3>\nComprehensive guidance across planning, development, design, and everyday operations.\n\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-300\"><i class=\"fas fa-user-check\"></i>\n<h3>Guest-Centred Thinking</h3>\nDedicated focus on elevating guest satisfaction, food quality, and service standards.\n\n</article></div>\n</div>\n</section><!-- SECTION 5: CTA -->\n\n<section class=\"cta\">\n<div class=\"wrap cta-inner anim-base anim-zoom-in\">\n\n<span class=\"eyebrow\">Let\'s Work Together</span>\n<h2>Ready to Build or Elevate Your Hospitality Venture?</h2>\nConnect with our leadership and operations team to discuss kitchen planning, recruitment, or end-to-end hospitality consultancy.\n<div class=\"cta-btns\"><a class=\"btn btn-light\" href=\"artha-hospitality-contact-us.html\">Start a Conversation <span class=\"arrow\">↗</span></a>\n<a class=\"btn btn-outline-light\" href=\"tel:+918951511234\">Call Us Today</a></div>\n</div>\n</section>', 'About', '', 'inherit', 'closed', 'closed', '', '11-autosave-v1', '', '', '2026-11-26 05:54:17', '2026-11-26 05:54:17', '', 11, 'http://localhost/artha-hospitality-management/?p=18', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(19, 1, '2026-11-26 05:54:18', '2026-11-26 05:54:18', '<!-- NEW 75VH ABOUT US HERO SECTION -->\r\n\r\n<section id=\"about-top\" class=\"about-editorial-hero\">\r\n<div class=\"wrap hero-inner\">\r\n\r\n<!-- Column 1: Editorial Copy & CTAs -->\r\n<div class=\"hero-story-col anim-base anim-fade-right\">\r\n<div class=\"hero-top-tags\"><nav class=\"breadcrumb-pill\" aria-label=\"Breadcrumb\"><a href=\"index.html\">Home</a>\r\n<i class=\"fas fa-chevron-right\"></i>\r\n<span class=\"current\">About Us</span></nav><span class=\"eyebrow\">Who We Are</span>\r\n\r\n</div>\r\n<h1>Shaping the Future of <em>Thoughtful Hospitality</em> From Concept to Table.</h1>\r\nAt Artha Hospitality Management, we partner with visionary restaurateurs, hoteliers, and hospitality entrepreneurs to turn ambitious concepts into resilient, high-performing destinations.\r\n<div class=\"hero-cta-group\"><a class=\"btn btn-primary\" href=\"artha-hospitality-contact-us.html\">Partner With Artha <span class=\"arrow\">↗</span></a>\r\n<a class=\"btn btn-ghost\" href=\"index.html#services\">Our Capabilities</a></div>\r\n</div>\r\n<!-- Column 2: Single Image Sculptural Stage with Theme Shapes -->\r\n<div class=\"hero-visual-stage anim-base anim-fade-left delay-100\">\r\n\r\n<!-- Shape 1: Concentric Gold Contour Rings -->\r\n\r\n<!-- Shape 2: Deep Espresso Architectural Offset Slab -->\r\n<div class=\"stage-shape-slab\" aria-hidden=\"true\"></div>\r\n<!-- Shape 3: Gold Offset Wireframe Arch -->\r\n<div class=\"stage-shape-wireframe\" aria-hidden=\"true\"></div>\r\n<!-- Shape 4: Gold Dot Matrix Pattern -->\r\n<div class=\"stage-shape-dots\" aria-hidden=\"true\"></div>\r\n<!-- Shape 5: Floating Espresso & Gold Medallion Seal -->\r\n<div class=\"stage-medallion\">\r\n\r\n&nbsp;\r\n<div class=\"med-text\"><strong>15+ Yrs</strong>\r\nHospitality Mastery</div>\r\n</div>\r\n<!-- Main Sculpted Arched Image Panel -->\r\n<div class=\"hero-arch-panel\">\r\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/artha-hospitality-about-us-hero.jpg\" alt=\"Hospitality team collaborating in a professional kitchen\" /><figcaption class=\"cr-only\">Hospitality team collaborating in a professional kitchen</figcaption></figure>\r\n<div class=\"arch-caption-bar\">\r\n<div><span class=\"tag-sub\">Operational Craft</span>\r\n<span class=\"tag-title\">Ground-Level Expertise</span></div>\r\n&nbsp;\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 1: ENGAGING ABOUT ARTHA HOSPITALITY -->\r\n\r\n<section id=\"about-artha\" class=\"about-artha-section\">\r\n<div class=\"wrap\">\r\n<div class=\"about-artha-grid\">\r\n\r\n<!-- Story & Philosophy Copy -->\r\n<div class=\"artha-story-copy anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">About Us</span>\r\n<h2>Hospitality Begins With <em>Great Service.</em></h2>\r\n<p class=\"lead-p\">At Artha, we believe that great hospitality begins with great service. Our mission is to help restaurant owners and hospitality businesses overcome their toughest service challenges, improve guest satisfaction, and grow sustainably.</p>\r\nWith a deep understanding of the industry and a commitment to excellence, we provide tailor-made solutions that create lasting value for our partners.\r\n<div class=\"artha-values-list\">\r\n<div class=\"artha-value-item\">\r\n\r\n&nbsp;\r\n<div>\r\n<h4>Industry Understanding</h4>\r\nGrounded in more than 15 years of hospitality and hotel operations experience.\r\n\r\n</div>\r\n</div>\r\n<div class=\"artha-value-item\">\r\n\r\n&nbsp;\r\n<div>\r\n<h4>Tailor-Made Solutions</h4>\r\nApproaches shaped around your business, your guests, and your operational goals.\r\n\r\n</div>\r\n</div>\r\n<div class=\"artha-value-item\">\r\n\r\n&nbsp;\r\n<div>\r\n<h4>Commitment to Excellence</h4>\r\nA consistent focus on quality, service standards, and sustainable long-term growth.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n<a class=\"btn btn-primary\" href=\"index.html#services\">Discover What We Do <span class=\"arrow\">↗</span></a>\r\n\r\n</div>\r\n<!-- Layered Hospitality Collage -->\r\n<div class=\"artha-story-visual anim-base anim-fade-left delay-100\">\r\n<div class=\"artha-vis-tag\">\r\n\r\n&nbsp;\r\n<div>15+ Years Experience\r\n<strong>Solutions That Work From Day One</strong></div>\r\n</div>\r\n<div class=\"artha-vis-main\">\r\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/slide-img-2-lgr.jpg\" alt=\"Elegant hospitality reception and dining space\" /><figcaption class=\"cr-only\">Elegant hospitality reception and dining space</figcaption></figure>\r\n</div>\r\n<div class=\"artha-vis-sub\">\r\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/artha-hospitality-management-about-us-sml-img.jpg\" alt=\"Premium restaurant dining environment\" /><figcaption class=\"cr-only\">Premium restaurant dining environment</figcaption></figure>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 2: LEADERSHIP & VISION + CEO SPOTLIGHT (VIHANI ANIL) -->\r\n\r\n<section id=\"vihani-anil\" class=\"leader-spotlight bg-sand-light\">\r\n<div class=\"wrap\">\r\n<div class=\"head-center anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>The Minds Driving Culinary, People &amp; Operational Excellence.</h2>\r\nGuided by visionary leadership, seasoned hospitality veterans, kitchen innovators, HR strategists, and operations leaders committed to building resilient, people-first hospitality ventures.\r\n\r\n</div>\r\n<div class=\"spotlight-grid\">\r\n\r\n<!-- Portrait Column -->\r\n<div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-frame\">\r\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/vihani-anil.jpg\" alt=\"Vihani Anil - Future CEO, Artha Hospitality Management\" /><figcaption class=\"cr-only\">Vihani Anil - Future CEO | Artha Hospitality Management</figcaption></figure>\r\n</div>\r\n<div class=\"portrait-exp-badge\"><strong>Future</strong>\r\nCEO · Artha\r\nHospitality</div>\r\n</div>\r\n<!-- Biography & Vision Column -->\r\n<div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>Vihani Anil</h2>\r\n<div class=\"role-pill\"><i class=\"fas fa-crown\"></i>\r\nFuture CEO | Artha Hospitality Management</div>\r\n<div class=\"leader-bio\">\r\n\r\nVihani Anil is the Future CEO of Artha Hospitality Management, representing the next generation of strategic leadership, brand vision, and client-first hospitality advisory across India.\r\n\r\nGuided by the principle <em>Dream · Plan · Achieve</em>, she brings a forward-looking perspective to modern hospitality consulting—bridging creative concept development with disciplined business planning and sustainable growth.\r\n\r\nHer leadership focus centres on empowering restaurant, café, hotel, cloud kitchen, and resort founders with clarity, structured execution, and long-term operational confidence from day one.\r\n\r\n</div>\r\n<div class=\"leader-chips\">Future Leadership\r\nBrand Strategy\r\nClient Partnerships\r\nBusiness Growth\r\nHospitality Innovation\r\nStrategic Planning</div>\r\n<div class=\"vision-callout\">\r\n<div class=\"vc-head\"><i class=\"fas fa-compass\"></i>\r\nFuture Vision &amp; Leadership</div>\r\nAs Future CEO, Vihani champions a culture of excellence, transparency, and purposeful execution—ensuring every hospitality venture partnered with Artha transforms ambitious ideas into thriving, guest-loved destinations.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 3: FOUNDER & DIRECTOR SPOTLIGHT (ANIL KUMAR K) -->\r\n\r\n<section id=\"anil-kumar\" class=\"leader-spotlight bg-offwhite\">\r\n<div class=\"wrap\">\r\n<div class=\"spotlight-grid reverse\">\r\n\r\n<!-- Biography & Vision Column -->\r\n<div class=\"leader-copy anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>Anil Kumar K</h2>\r\n<div class=\"role-pill\"><i class=\"fas fa-chess-king\"></i>\r\nFounder &amp; Director – Artha Hospitality</div>\r\n<div class=\"leader-bio\">\r\n\r\nChef Anil Kumar K is the Founder &amp; Director of Artha Hospitality, bringing over 25 years of experience in the hospitality industry.\r\n\r\nWith a professional background as a Chef, Anil has extensive hands-on experience in professional kitchens, restaurant operations, kitchen planning, commercial kitchen equipment, food production, and hospitality management.\r\n\r\nHis 25 years of industry experience provide him with a deep understanding of the practical requirements of hotels, restaurants, cafés, catering businesses, and commercial food-service operations.\r\n\r\n</div>\r\n<div class=\"leader-chips\">Professional Kitchens\r\nRestaurant Operations\r\nKitchen Planning\r\nCommercial Kitchen Equipment\r\nFood Production\r\nHospitality Management</div>\r\n<div class=\"vision-callout\">\r\n<div class=\"vc-head\"><i class=\"fas fa-compass\"></i>\r\nStrategic Vision &amp; Leadership</div>\r\nAs Founder &amp; Director of Artha Hospitality, Anil leads the company’s business strategy, kitchen solutions, operational planning, client relationships, and overall execution, with a vision to deliver reliable, efficient, and sustainable hospitality solutions.\r\n\r\n</div>\r\n</div>\r\n<!-- Portrait Column -->\r\n<div class=\"leader-portrait-stage anim-base anim-fade-left delay-100\">\r\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-frame\">\r\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/about-us-images/anil-kumar-k.jpg\" alt=\"Chef Anil Kumar K - Founder &amp; Director of Artha Hospitality\" /><figcaption class=\"cr-only\">Chef Anil Kumar K - Founder &amp; Director – Artha Hospitality</figcaption></figure>\r\n</div>\r\n<div class=\"portrait-exp-badge\"><strong>25+</strong>\r\nYears in\r\nHospitality</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 4: HR DIRECTOR SPOTLIGHT - SUSHMA AMIN -->\r\n\r\n<section id=\"sushma-amin\" class=\"leader-spotlight bg-sand-light\">\r\n<div class=\"wrap spotlight-grid\">\r\n\r\n<!-- Portrait Column -->\r\n<div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-frame\">\r\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/about-us-images/sushma-amin.jpg\" alt=\"Sushma Amin - HR Director &amp; Hospitality HR Professional\" /><figcaption class=\"cr-only\">Sushma Amin - HR Director &amp; Hospitality HR Professional</figcaption></figure>\r\n</div>\r\n<div class=\"portrait-exp-badge\"><strong>20+</strong>\r\nYears in HR &amp;\r\nHospitality</div>\r\n</div>\r\n<!-- Biography & Vision Column -->\r\n<div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>Sushma Amin</h2>\r\n<div class=\"role-pill\"><i class=\"fas fa-balance-scale\"></i>\r\nHR Director &amp; Hospitality HR Professional</div>\r\n<div class=\"leader-bio\">\r\n\r\nSushma Amin is a seasoned Human Resources professional with over 20 years of experience in the HR and hospitality industry, bringing extensive expertise in people management, talent acquisition, employee relations, HR operations, and organizational development.\r\n\r\nWith a strong academic background in Bachelor of Arts (BA) and Bachelor of Laws (LLB), she combines professional knowledge with practical industry experience to build effective HR practices and people-centric workplaces.\r\n\r\nThroughout her career, she has worked with leading hospitality establishments, gaining valuable experience in managing diverse workforces, developing HR systems, streamlining recruitment processes, and supporting business growth through effective human resource management.\r\n\r\n</div>\r\n<div class=\"leader-chips\">People Management\r\nTalent Acquisition\r\nEmployee Relations\r\nHR Operations\r\nOrganizational Development\r\nBA &amp; LLB</div>\r\n<div class=\"vision-callout\">\r\n<div class=\"vc-head\"><i class=\"fas fa-bullseye\"></i>\r\nProfessional Vision</div>\r\nHer professional vision is to connect the right talent with the right opportunities, empower people, strengthen organizations, and contribute to the growth of the hospitality industry through ethical, transparent, and result-oriented HR practices.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 4: ARTHA EXECUTIVE MANAGEMENT (SNEHA M. & SANDEEP SHETTY) -->\r\n\r\n<section id=\"executive-management\" class=\"management-section\">\r\n<div class=\"wrap\">\r\n<div class=\"head-center anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">Artha Hospitality Team</span>\r\n<h2>Driving Recruitment, Sales &amp; Operational Excellence.</h2>\r\nConnecting talented hospitality professionals with leading organizations and delivering disciplined, guest-focused operational results every day.\r\n\r\n</div>\r\n<!-- Profile 1: Sneha M. -->\r\n\r\n<article class=\"exec-profile-block anim-base anim-fade-up\">\r\n<div class=\"exec-top-grid\">\r\n<div class=\"exec-photo-wrap\">\r\n<div class=\"exec-photo-frame\">\r\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/about-us-images/sneha-m.jpg\" alt=\"Sneha M. - HR Executive at Artha Hospitality\" /><figcaption class=\"cr-only\">Sneha M. - HR Executive | Artha Hospitality</figcaption></figure>\r\n</div>\r\n</div>\r\n<div class=\"exec-intro\">\r\n\r\n<span class=\"eyebrow\">People &amp; Talent</span>\r\n<h3>Sneha M.</h3>\r\n<div class=\"exec-role\"><i class=\"fas fa-id-badge\"></i>\r\nHR Executive | Artha Hospitality</div>\r\nAs an HR Executive at Artha Hospitality, I am responsible for identifying, attracting and connecting the right talent with the right opportunities in the hospitality industry.\r\n\r\nI believe that successful businesses are built by the right people. My focus is on understanding client requirements, building strong relationships with candidates and ensuring a smooth and effective recruitment process.\r\n\r\n</div>\r\n</div>\r\n<div class=\"exec-pillars-grid\">\r\n<div class=\"pillar-box\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Vision</h4>\r\n</div>\r\nTo connect talented individuals with the right opportunities and help hospitality businesses grow through quality recruitment, trust and strong professional relationships.\r\n\r\n</div>\r\n<div class=\"pillar-box dark\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Mission</h4>\r\n</div>\r\nTo make recruitment a meaningful experience by bringing together the right people and the right organizations.\r\n\r\n</div>\r\n</div>\r\n</article><!-- Profile 2: Sandeep Shetty -->\r\n\r\n<article class=\"exec-profile-block reverse anim-base anim-fade-up\">\r\n<div class=\"exec-top-grid\">\r\n<div class=\"exec-intro\">\r\n\r\n<span class=\"eyebrow\">Growth &amp; Operations</span>\r\n<h3>Sandeep Shetty</h3>\r\n<div class=\"exec-role\"><i class=\"fas fa-briefcase\"></i>\r\nSales &amp; Operations Manager | Artha Hospitality</div>\r\nAs a Sales &amp; Operations Manager at Artha Hospitality, I am responsible for driving business growth, leading operations, and creating exceptional guest experiences in the hospitality industry.\r\n\r\nI believe that successful hospitality businesses are built on strong leadership, consistent service, and the right people. My focus is on understanding client needs, building lasting business relationships, and ensuring smooth, result-driven operations.\r\n\r\n</div>\r\n<div class=\"exec-photo-wrap\">\r\n<div class=\"exec-photo-frame\">\r\n<figure class=\"cr-figure\"><img src=\"<?php echo get_stylesheet_directory_uri(); ?>/assets/images/about-us-images/sandeep-shetty.jpg\" alt=\"Sandeep Shetty - Sales &amp; Operations Manager at Artha Hospitality\" /><figcaption class=\"cr-only\">Sandeep Shetty - Sales &amp; Operations Manager | Artha Hospitality</figcaption></figure>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"exec-pillars-grid cols-3\">\r\n<div class=\"pillar-box dark\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Leadership</h4>\r\n</div>\r\nI lead by example — with clarity, accountability, and a people-first approach. My leadership is focused on building high-performing teams, empowering individuals, and creating a culture of ownership, discipline, and excellence.\r\n\r\nI believe a great leader doesn\'t just manage operations; they inspire people to deliver their best every single day.\r\n\r\n</div>\r\n<div class=\"pillar-box\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Vision</h4>\r\n</div>\r\nTo lead Artha Hospitality towards sustainable growth by combining strong sales strategies, operational excellence, and meaningful human connections — and to make it a trusted name in the hospitality industry.\r\n\r\n</div>\r\n<div class=\"pillar-box\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Mission</h4>\r\n</div>\r\nTo drive sales with integrity, deliver operations with excellence, and create value for clients, guests, and the team — by bringing together the right strategy, the right people, and the right execution.\r\n\r\n</div>\r\n</div>\r\n</article></div>\r\n</section><!-- WHY CHOOSE US SECTION -->\r\n\r\n<section id=\"why-choose-us\" class=\"why-choose-section\">\r\n<div class=\"wrap\">\r\n<div class=\"why-choose-head anim-base anim-fade-up\">\r\n\r\n<span class=\"eyebrow\">Why Choose Us?</span>\r\n<h2>Experience That Turns Ideas Into Successful Operations.</h2>\r\n“Backed by over <em>15 years</em> of experience in hospitality and hotel operations, our team combines industry insight with proven strategies to deliver solutions that work from day one.”\r\n\r\n</div>\r\n<div class=\"why-choose-grid\"><article class=\"why-choose-card anim-base anim-fade-up delay-100\"><i class=\"fas fa-award\"></i>\r\n<h3>Industry Experience</h3>\r\nMore than 15 years of hands-on experience in hospitality and hotel operations.\r\n\r\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-200\"><i class=\"fas fa-chart-line\"></i>\r\n<h3>Strategic Approach</h3>\r\nSolutions built around your specific business requirements and operational objectives.\r\n\r\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-300\"><i class=\"fas fa-layer-group\"></i>\r\n<h3>End-to-End Support</h3>\r\nComprehensive guidance across planning, development, design, and everyday operations.\r\n\r\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-300\"><i class=\"fas fa-user-check\"></i>\r\n<h3>Guest-Centred Thinking</h3>\r\nDedicated focus on elevating guest satisfaction, food quality, and service standards.\r\n\r\n</article></div>\r\n</div>\r\n</section><!-- SECTION 5: CTA -->\r\n\r\n<section class=\"cta\">\r\n<div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n\r\n<span class=\"eyebrow\">Let\'s Work Together</span>\r\n<h2>Ready to Build or Elevate Your Hospitality Venture?</h2>\r\nConnect with our leadership and operations team to discuss kitchen planning, recruitment, or end-to-end hospitality consultancy.\r\n<div class=\"cta-btns\"><a class=\"btn btn-light\" href=\"artha-hospitality-contact-us.html\">Start a Conversation <span class=\"arrow\">↗</span></a>\r\n<a class=\"btn btn-outline-light\" href=\"tel:+918951511234\">Call Us Today</a></div>\r\n</div>\r\n</section>', 'About', '', 'inherit', 'closed', 'closed', '', '11-revision-v1', '', '', '2026-11-26 05:54:18', '2026-11-26 05:54:18', '', 11, 'http://localhost/artha-hospitality-management/?p=19', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(20, 1, '2026-11-26 05:57:24', '2026-11-26 05:57:24', '<!-- NEW 75VH ABOUT US HERO SECTION -->\r\n\r\n<section id=\"about-top\" class=\"about-editorial-hero\">\r\n<div class=\"wrap hero-inner\">\r\n\r\n<!-- Column 1: Editorial Copy & CTAs -->\r\n<div class=\"hero-story-col anim-base anim-fade-right\">\r\n<div class=\"hero-top-tags\"><nav class=\"breadcrumb-pill\" aria-label=\"Breadcrumb\"><a href=\"index.html\">Home</a>\r\n<i class=\"fas fa-chevron-right\"></i>\r\n<span class=\"current\">About Us</span></nav><span class=\"eyebrow\">Who We Are</span>\r\n\r\n</div>\r\n<h1>Shaping the Future of <em>Thoughtful Hospitality</em> From Concept to Table.</h1>\r\nAt Artha Hospitality Management, we partner with visionary restaurateurs, hoteliers, and hospitality entrepreneurs to turn ambitious concepts into resilient, high-performing destinations.\r\n<div class=\"hero-cta-group\"><a class=\"btn btn-primary\" href=\"artha-hospitality-contact-us.html\">Partner With Artha <span class=\"arrow\">↗</span></a>\r\n<a class=\"btn btn-ghost\" href=\"index.html#services\">Our Capabilities</a></div>\r\n</div>\r\n<!-- Column 2: Single Image Sculptural Stage with Theme Shapes -->\r\n<div class=\"hero-visual-stage anim-base anim-fade-left delay-100\">\r\n\r\n<!-- Shape 1: Concentric Gold Contour Rings -->\r\n\r\n<!-- Shape 2: Deep Espresso Architectural Offset Slab -->\r\n<div class=\"stage-shape-slab\" aria-hidden=\"true\"></div>\r\n<!-- Shape 3: Gold Offset Wireframe Arch -->\r\n<div class=\"stage-shape-wireframe\" aria-hidden=\"true\"></div>\r\n<!-- Shape 4: Gold Dot Matrix Pattern -->\r\n<div class=\"stage-shape-dots\" aria-hidden=\"true\"></div>\r\n<!-- Shape 5: Floating Espresso & Gold Medallion Seal -->\r\n<div class=\"stage-medallion\">\r\n\r\n&nbsp;\r\n<div class=\"med-text\"><strong>15+ Yrs</strong>\r\nHospitality Mastery</div>\r\n</div>\r\n<!-- Main Sculpted Arched Image Panel -->\r\n<div class=\"hero-arch-panel\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/images/artha-hospitality-about-us-hero.jpg\" alt=\"Hospitality team collaborating in a professional kitchen\" /><figcaption class=\"cr-only\">Hospitality team collaborating in a professional kitchen</figcaption></figure>\r\n<div class=\"arch-caption-bar\">\r\n<div><span class=\"tag-sub\">Operational Craft</span>\r\n<span class=\"tag-title\">Ground-Level Expertise</span></div>\r\n&nbsp;\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 1: ENGAGING ABOUT ARTHA HOSPITALITY -->\r\n\r\n<section id=\"about-artha\" class=\"about-artha-section\">\r\n<div class=\"wrap\">\r\n<div class=\"about-artha-grid\">\r\n\r\n<!-- Story & Philosophy Copy -->\r\n<div class=\"artha-story-copy anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">About Us</span>\r\n<h2>Hospitality Begins With <em>Great Service.</em></h2>\r\n<p class=\"lead-p\">At Artha, we believe that great hospitality begins with great service. Our mission is to help restaurant owners and hospitality businesses overcome their toughest service challenges, improve guest satisfaction, and grow sustainably.</p>\r\nWith a deep understanding of the industry and a commitment to excellence, we provide tailor-made solutions that create lasting value for our partners.\r\n<div class=\"artha-values-list\">\r\n<div class=\"artha-value-item\">\r\n\r\n&nbsp;\r\n<div>\r\n<h4>Industry Understanding</h4>\r\nGrounded in more than 15 years of hospitality and hotel operations experience.\r\n\r\n</div>\r\n</div>\r\n<div class=\"artha-value-item\">\r\n\r\n&nbsp;\r\n<div>\r\n<h4>Tailor-Made Solutions</h4>\r\nApproaches shaped around your business, your guests, and your operational goals.\r\n\r\n</div>\r\n</div>\r\n<div class=\"artha-value-item\">\r\n\r\n&nbsp;\r\n<div>\r\n<h4>Commitment to Excellence</h4>\r\nA consistent focus on quality, service standards, and sustainable long-term growth.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n<a class=\"btn btn-primary\" href=\"index.html#services\">Discover What We Do <span class=\"arrow\">↗</span></a>\r\n\r\n</div>\r\n<!-- Layered Hospitality Collage -->\r\n<div class=\"artha-story-visual anim-base anim-fade-left delay-100\">\r\n<div class=\"artha-vis-tag\">\r\n\r\n&nbsp;\r\n<div>15+ Years Experience\r\n<strong>Solutions That Work From Day One</strong></div>\r\n</div>\r\n<div class=\"artha-vis-main\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/images/slide-img-2-lgr.jpg\" alt=\"Elegant hospitality reception and dining space\" /><figcaption class=\"cr-only\">Elegant hospitality reception and dining space</figcaption></figure>\r\n</div>\r\n<div class=\"artha-vis-sub\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/images/artha-hospitality-management-about-us-sml-img.jpg\" alt=\"Premium restaurant dining environment\" /><figcaption class=\"cr-only\">Premium restaurant dining environment</figcaption></figure>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 2: LEADERSHIP & VISION + CEO SPOTLIGHT (VIHANI ANIL) -->\r\n\r\n<section id=\"vihani-anil\" class=\"leader-spotlight bg-sand-light\">\r\n<div class=\"wrap\">\r\n<div class=\"head-center anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>The Minds Driving Culinary, People &amp; Operational Excellence.</h2>\r\nGuided by visionary leadership, seasoned hospitality veterans, kitchen innovators, HR strategists, and operations leaders committed to building resilient, people-first hospitality ventures.\r\n\r\n</div>\r\n<div class=\"spotlight-grid\">\r\n\r\n<!-- Portrait Column -->\r\n<div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-frame\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/images/vihani-anil.jpg\" alt=\"Vihani Anil - Future CEO, Artha Hospitality Management\" /><figcaption class=\"cr-only\">Vihani Anil - Future CEO | Artha Hospitality Management</figcaption></figure>\r\n</div>\r\n<div class=\"portrait-exp-badge\"><strong>Future</strong>\r\nCEO · Artha\r\nHospitality</div>\r\n</div>\r\n<!-- Biography & Vision Column -->\r\n<div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>Vihani Anil</h2>\r\n<div class=\"role-pill\"><i class=\"fas fa-crown\"></i>\r\nFuture CEO | Artha Hospitality Management</div>\r\n<div class=\"leader-bio\">\r\n\r\nVihani Anil is the Future CEO of Artha Hospitality Management, representing the next generation of strategic leadership, brand vision, and client-first hospitality advisory across India.\r\n\r\nGuided by the principle <em>Dream · Plan · Achieve</em>, she brings a forward-looking perspective to modern hospitality consulting—bridging creative concept development with disciplined business planning and sustainable growth.\r\n\r\nHer leadership focus centres on empowering restaurant, café, hotel, cloud kitchen, and resort founders with clarity, structured execution, and long-term operational confidence from day one.\r\n\r\n</div>\r\n<div class=\"leader-chips\">Future Leadership\r\nBrand Strategy\r\nClient Partnerships\r\nBusiness Growth\r\nHospitality Innovation\r\nStrategic Planning</div>\r\n<div class=\"vision-callout\">\r\n<div class=\"vc-head\"><i class=\"fas fa-compass\"></i>\r\nFuture Vision &amp; Leadership</div>\r\nAs Future CEO, Vihani champions a culture of excellence, transparency, and purposeful execution—ensuring every hospitality venture partnered with Artha transforms ambitious ideas into thriving, guest-loved destinations.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 3: FOUNDER & DIRECTOR SPOTLIGHT (ANIL KUMAR K) -->\r\n\r\n<section id=\"anil-kumar\" class=\"leader-spotlight bg-offwhite\">\r\n<div class=\"wrap\">\r\n<div class=\"spotlight-grid reverse\">\r\n\r\n<!-- Biography & Vision Column -->\r\n<div class=\"leader-copy anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>Anil Kumar K</h2>\r\n<div class=\"role-pill\"><i class=\"fas fa-chess-king\"></i>\r\nFounder &amp; Director – Artha Hospitality</div>\r\n<div class=\"leader-bio\">\r\n\r\nChef Anil Kumar K is the Founder &amp; Director of Artha Hospitality, bringing over 25 years of experience in the hospitality industry.\r\n\r\nWith a professional background as a Chef, Anil has extensive hands-on experience in professional kitchens, restaurant operations, kitchen planning, commercial kitchen equipment, food production, and hospitality management.\r\n\r\nHis 25 years of industry experience provide him with a deep understanding of the practical requirements of hotels, restaurants, cafés, catering businesses, and commercial food-service operations.\r\n\r\n</div>\r\n<div class=\"leader-chips\">Professional Kitchens\r\nRestaurant Operations\r\nKitchen Planning\r\nCommercial Kitchen Equipment\r\nFood Production\r\nHospitality Management</div>\r\n<div class=\"vision-callout\">\r\n<div class=\"vc-head\"><i class=\"fas fa-compass\"></i>\r\nStrategic Vision &amp; Leadership</div>\r\nAs Founder &amp; Director of Artha Hospitality, Anil leads the company’s business strategy, kitchen solutions, operational planning, client relationships, and overall execution, with a vision to deliver reliable, efficient, and sustainable hospitality solutions.\r\n\r\n</div>\r\n</div>\r\n<!-- Portrait Column -->\r\n<div class=\"leader-portrait-stage anim-base anim-fade-left delay-100\">\r\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-frame\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/images/about-us-images/anil-kumar-k.jpg\" alt=\"Chef Anil Kumar K - Founder &amp; Director of Artha Hospitality\" /><figcaption class=\"cr-only\">Chef Anil Kumar K - Founder &amp; Director – Artha Hospitality</figcaption></figure>\r\n</div>\r\n<div class=\"portrait-exp-badge\"><strong>25+</strong>\r\nYears in\r\nHospitality</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 4: HR DIRECTOR SPOTLIGHT - SUSHMA AMIN -->\r\n\r\n<section id=\"sushma-amin\" class=\"leader-spotlight bg-sand-light\">\r\n<div class=\"wrap spotlight-grid\">\r\n\r\n<!-- Portrait Column -->\r\n<div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-frame\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/images/about-us-images/sushma-amin.jpg\" alt=\"Sushma Amin - HR Director &amp; Hospitality HR Professional\" /><figcaption class=\"cr-only\">Sushma Amin - HR Director &amp; Hospitality HR Professional</figcaption></figure>\r\n</div>\r\n<div class=\"portrait-exp-badge\"><strong>20+</strong>\r\nYears in HR &amp;\r\nHospitality</div>\r\n</div>\r\n<!-- Biography & Vision Column -->\r\n<div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>Sushma Amin</h2>\r\n<div class=\"role-pill\"><i class=\"fas fa-balance-scale\"></i>\r\nHR Director &amp; Hospitality HR Professional</div>\r\n<div class=\"leader-bio\">\r\n\r\nSushma Amin is a seasoned Human Resources professional with over 20 years of experience in the HR and hospitality industry, bringing extensive expertise in people management, talent acquisition, employee relations, HR operations, and organizational development.\r\n\r\nWith a strong academic background in Bachelor of Arts (BA) and Bachelor of Laws (LLB), she combines professional knowledge with practical industry experience to build effective HR practices and people-centric workplaces.\r\n\r\nThroughout her career, she has worked with leading hospitality establishments, gaining valuable experience in managing diverse workforces, developing HR systems, streamlining recruitment processes, and supporting business growth through effective human resource management.\r\n\r\n</div>\r\n<div class=\"leader-chips\">People Management\r\nTalent Acquisition\r\nEmployee Relations\r\nHR Operations\r\nOrganizational Development\r\nBA &amp; LLB</div>\r\n<div class=\"vision-callout\">\r\n<div class=\"vc-head\"><i class=\"fas fa-bullseye\"></i>\r\nProfessional Vision</div>\r\nHer professional vision is to connect the right talent with the right opportunities, empower people, strengthen organizations, and contribute to the growth of the hospitality industry through ethical, transparent, and result-oriented HR practices.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 4: ARTHA EXECUTIVE MANAGEMENT (SNEHA M. & SANDEEP SHETTY) -->\r\n\r\n<section id=\"executive-management\" class=\"management-section\">\r\n<div class=\"wrap\">\r\n<div class=\"head-center anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">Artha Hospitality Team</span>\r\n<h2>Driving Recruitment, Sales &amp; Operational Excellence.</h2>\r\nConnecting talented hospitality professionals with leading organizations and delivering disciplined, guest-focused operational results every day.\r\n\r\n</div>\r\n<!-- Profile 1: Sneha M. -->\r\n\r\n<article class=\"exec-profile-block anim-base anim-fade-up\">\r\n<div class=\"exec-top-grid\">\r\n<div class=\"exec-photo-wrap\">\r\n<div class=\"exec-photo-frame\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/images/about-us-images/sneha-m.jpg\" alt=\"Sneha M. - HR Executive at Artha Hospitality\" /><figcaption class=\"cr-only\">Sneha M. - HR Executive | Artha Hospitality</figcaption></figure>\r\n</div>\r\n</div>\r\n<div class=\"exec-intro\">\r\n\r\n<span class=\"eyebrow\">People &amp; Talent</span>\r\n<h3>Sneha M.</h3>\r\n<div class=\"exec-role\"><i class=\"fas fa-id-badge\"></i>\r\nHR Executive | Artha Hospitality</div>\r\nAs an HR Executive at Artha Hospitality, I am responsible for identifying, attracting and connecting the right talent with the right opportunities in the hospitality industry.\r\n\r\nI believe that successful businesses are built by the right people. My focus is on understanding client requirements, building strong relationships with candidates and ensuring a smooth and effective recruitment process.\r\n\r\n</div>\r\n</div>\r\n<div class=\"exec-pillars-grid\">\r\n<div class=\"pillar-box\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Vision</h4>\r\n</div>\r\nTo connect talented individuals with the right opportunities and help hospitality businesses grow through quality recruitment, trust and strong professional relationships.\r\n\r\n</div>\r\n<div class=\"pillar-box dark\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Mission</h4>\r\n</div>\r\nTo make recruitment a meaningful experience by bringing together the right people and the right organizations.\r\n\r\n</div>\r\n</div>\r\n</article><!-- Profile 2: Sandeep Shetty -->\r\n\r\n<article class=\"exec-profile-block reverse anim-base anim-fade-up\">\r\n<div class=\"exec-top-grid\">\r\n<div class=\"exec-intro\">\r\n\r\n<span class=\"eyebrow\">Growth &amp; Operations</span>\r\n<h3>Sandeep Shetty</h3>\r\n<div class=\"exec-role\"><i class=\"fas fa-briefcase\"></i>\r\nSales &amp; Operations Manager | Artha Hospitality</div>\r\nAs a Sales &amp; Operations Manager at Artha Hospitality, I am responsible for driving business growth, leading operations, and creating exceptional guest experiences in the hospitality industry.\r\n\r\nI believe that successful hospitality businesses are built on strong leadership, consistent service, and the right people. My focus is on understanding client needs, building lasting business relationships, and ensuring smooth, result-driven operations.\r\n\r\n</div>\r\n<div class=\"exec-photo-wrap\">\r\n<div class=\"exec-photo-frame\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/images/about-us-images/sandeep-shetty.jpg\" alt=\"Sandeep Shetty - Sales &amp; Operations Manager at Artha Hospitality\" /><figcaption class=\"cr-only\">Sandeep Shetty - Sales &amp; Operations Manager | Artha Hospitality</figcaption></figure>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"exec-pillars-grid cols-3\">\r\n<div class=\"pillar-box dark\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Leadership</h4>\r\n</div>\r\nI lead by example — with clarity, accountability, and a people-first approach. My leadership is focused on building high-performing teams, empowering individuals, and creating a culture of ownership, discipline, and excellence.\r\n\r\nI believe a great leader doesn\'t just manage operations; they inspire people to deliver their best every single day.\r\n\r\n</div>\r\n<div class=\"pillar-box\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Vision</h4>\r\n</div>\r\nTo lead Artha Hospitality towards sustainable growth by combining strong sales strategies, operational excellence, and meaningful human connections — and to make it a trusted name in the hospitality industry.\r\n\r\n</div>\r\n<div class=\"pillar-box\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Mission</h4>\r\n</div>\r\nTo drive sales with integrity, deliver operations with excellence, and create value for clients, guests, and the team — by bringing together the right strategy, the right people, and the right execution.\r\n\r\n</div>\r\n</div>\r\n</article></div>\r\n</section><!-- WHY CHOOSE US SECTION -->\r\n\r\n<section id=\"why-choose-us\" class=\"why-choose-section\">\r\n<div class=\"wrap\">\r\n<div class=\"why-choose-head anim-base anim-fade-up\">\r\n\r\n<span class=\"eyebrow\">Why Choose Us?</span>\r\n<h2>Experience That Turns Ideas Into Successful Operations.</h2>\r\n“Backed by over <em>15 years</em> of experience in hospitality and hotel operations, our team combines industry insight with proven strategies to deliver solutions that work from day one.”\r\n\r\n</div>\r\n<div class=\"why-choose-grid\"><article class=\"why-choose-card anim-base anim-fade-up delay-100\"><i class=\"fas fa-award\"></i>\r\n<h3>Industry Experience</h3>\r\nMore than 15 years of hands-on experience in hospitality and hotel operations.\r\n\r\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-200\"><i class=\"fas fa-chart-line\"></i>\r\n<h3>Strategic Approach</h3>\r\nSolutions built around your specific business requirements and operational objectives.\r\n\r\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-300\"><i class=\"fas fa-layer-group\"></i>\r\n<h3>End-to-End Support</h3>\r\nComprehensive guidance across planning, development, design, and everyday operations.\r\n\r\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-300\"><i class=\"fas fa-user-check\"></i>\r\n<h3>Guest-Centred Thinking</h3>\r\nDedicated focus on elevating guest satisfaction, food quality, and service standards.\r\n\r\n</article></div>\r\n</div>\r\n</section><!-- SECTION 5: CTA -->\r\n\r\n<section class=\"cta\">\r\n<div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n\r\n<span class=\"eyebrow\">Let\'s Work Together</span>\r\n<h2>Ready to Build or Elevate Your Hospitality Venture?</h2>\r\nConnect with our leadership and operations team to discuss kitchen planning, recruitment, or end-to-end hospitality consultancy.\r\n<div class=\"cta-btns\"><a class=\"btn btn-light\" href=\"artha-hospitality-contact-us.html\">Start a Conversation <span class=\"arrow\">↗</span></a>\r\n<a class=\"btn btn-outline-light\" href=\"tel:+918951511234\">Call Us Today</a></div>\r\n</div>\r\n</section>', 'About', '', 'inherit', 'closed', 'closed', '', '11-revision-v1', '', '', '2026-11-26 05:57:24', '2026-11-26 05:57:24', '', 11, 'http://localhost/artha-hospitality-management/?p=20', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(21, 1, '2026-11-26 05:58:11', '2026-11-26 05:58:11', '<!-- NEW 75VH ABOUT US HERO SECTION -->\r\n\r\n<section id=\"about-top\" class=\"about-editorial-hero\">\r\n<div class=\"wrap hero-inner\">\r\n\r\n<!-- Column 1: Editorial Copy & CTAs -->\r\n<div class=\"hero-story-col anim-base anim-fade-right\">\r\n<div class=\"hero-top-tags\"><nav class=\"breadcrumb-pill\" aria-label=\"Breadcrumb\"><a href=\"index.html\">Home</a>\r\n<i class=\"fas fa-chevron-right\"></i>\r\n<span class=\"current\">About Us</span></nav><span class=\"eyebrow\">Who We Are</span>\r\n\r\n</div>\r\n<h1>Shaping the Future of <em>Thoughtful Hospitality</em> From Concept to Table.</h1>\r\nAt Artha Hospitality Management, we partner with visionary restaurateurs, hoteliers, and hospitality entrepreneurs to turn ambitious concepts into resilient, high-performing destinations.\r\n<div class=\"hero-cta-group\"><a class=\"btn btn-primary\" href=\"artha-hospitality-contact-us.html\">Partner With Artha <span class=\"arrow\">↗</span></a>\r\n<a class=\"btn btn-ghost\" href=\"index.html#services\">Our Capabilities</a></div>\r\n</div>\r\n<!-- Column 2: Single Image Sculptural Stage with Theme Shapes -->\r\n<div class=\"hero-visual-stage anim-base anim-fade-left delay-100\">\r\n\r\n<!-- Shape 1: Concentric Gold Contour Rings -->\r\n\r\n<!-- Shape 2: Deep Espresso Architectural Offset Slab -->\r\n<div class=\"stage-shape-slab\" aria-hidden=\"true\"></div>\r\n<!-- Shape 3: Gold Offset Wireframe Arch -->\r\n<div class=\"stage-shape-wireframe\" aria-hidden=\"true\"></div>\r\n<!-- Shape 4: Gold Dot Matrix Pattern -->\r\n<div class=\"stage-shape-dots\" aria-hidden=\"true\"></div>\r\n<!-- Shape 5: Floating Espresso & Gold Medallion Seal -->\r\n<div class=\"stage-medallion\">\r\n\r\n&nbsp;\r\n<div class=\"med-text\"><strong>15+ Yrs</strong>\r\nHospitality Mastery</div>\r\n</div>\r\n<!-- Main Sculpted Arched Image Panel -->\r\n<div class=\"hero-arch-panel\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/assets/images/artha-hospitality-about-us-hero.jpg\" alt=\"Hospitality team collaborating in a professional kitchen\" /><figcaption class=\"cr-only\">Hospitality team collaborating in a professional kitchen</figcaption></figure>\r\n<div class=\"arch-caption-bar\">\r\n<div><span class=\"tag-sub\">Operational Craft</span>\r\n<span class=\"tag-title\">Ground-Level Expertise</span></div>\r\n&nbsp;\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 1: ENGAGING ABOUT ARTHA HOSPITALITY -->\r\n\r\n<section id=\"about-artha\" class=\"about-artha-section\">\r\n<div class=\"wrap\">\r\n<div class=\"about-artha-grid\">\r\n\r\n<!-- Story & Philosophy Copy -->\r\n<div class=\"artha-story-copy anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">About Us</span>\r\n<h2>Hospitality Begins With <em>Great Service.</em></h2>\r\n<p class=\"lead-p\">At Artha, we believe that great hospitality begins with great service. Our mission is to help restaurant owners and hospitality businesses overcome their toughest service challenges, improve guest satisfaction, and grow sustainably.</p>\r\nWith a deep understanding of the industry and a commitment to excellence, we provide tailor-made solutions that create lasting value for our partners.\r\n<div class=\"artha-values-list\">\r\n<div class=\"artha-value-item\">\r\n\r\n&nbsp;\r\n<div>\r\n<h4>Industry Understanding</h4>\r\nGrounded in more than 15 years of hospitality and hotel operations experience.\r\n\r\n</div>\r\n</div>\r\n<div class=\"artha-value-item\">\r\n\r\n&nbsp;\r\n<div>\r\n<h4>Tailor-Made Solutions</h4>\r\nApproaches shaped around your business, your guests, and your operational goals.\r\n\r\n</div>\r\n</div>\r\n<div class=\"artha-value-item\">\r\n\r\n&nbsp;\r\n<div>\r\n<h4>Commitment to Excellence</h4>\r\nA consistent focus on quality, service standards, and sustainable long-term growth.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n<a class=\"btn btn-primary\" href=\"index.html#services\">Discover What We Do <span class=\"arrow\">↗</span></a>\r\n\r\n</div>\r\n<!-- Layered Hospitality Collage -->\r\n<div class=\"artha-story-visual anim-base anim-fade-left delay-100\">\r\n<div class=\"artha-vis-tag\">\r\n\r\n&nbsp;\r\n<div>15+ Years Experience\r\n<strong>Solutions That Work From Day One</strong></div>\r\n</div>\r\n<div class=\"artha-vis-main\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/assets/images/slide-img-2-lgr.jpg\" alt=\"Elegant hospitality reception and dining space\" /><figcaption class=\"cr-only\">Elegant hospitality reception and dining space</figcaption></figure>\r\n</div>\r\n<div class=\"artha-vis-sub\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/assets/images/artha-hospitality-management-about-us-sml-img.jpg\" alt=\"Premium restaurant dining environment\" /><figcaption class=\"cr-only\">Premium restaurant dining environment</figcaption></figure>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 2: LEADERSHIP & VISION + CEO SPOTLIGHT (VIHANI ANIL) -->\r\n\r\n<section id=\"vihani-anil\" class=\"leader-spotlight bg-sand-light\">\r\n<div class=\"wrap\">\r\n<div class=\"head-center anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>The Minds Driving Culinary, People &amp; Operational Excellence.</h2>\r\nGuided by visionary leadership, seasoned hospitality veterans, kitchen innovators, HR strategists, and operations leaders committed to building resilient, people-first hospitality ventures.\r\n\r\n</div>\r\n<div class=\"spotlight-grid\">\r\n\r\n<!-- Portrait Column -->\r\n<div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-frame\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/assets/images/vihani-anil.jpg\" alt=\"Vihani Anil - Future CEO, Artha Hospitality Management\" /><figcaption class=\"cr-only\">Vihani Anil - Future CEO | Artha Hospitality Management</figcaption></figure>\r\n</div>\r\n<div class=\"portrait-exp-badge\"><strong>Future</strong>\r\nCEO · Artha\r\nHospitality</div>\r\n</div>\r\n<!-- Biography & Vision Column -->\r\n<div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>Vihani Anil</h2>\r\n<div class=\"role-pill\"><i class=\"fas fa-crown\"></i>\r\nFuture CEO | Artha Hospitality Management</div>\r\n<div class=\"leader-bio\">\r\n\r\nVihani Anil is the Future CEO of Artha Hospitality Management, representing the next generation of strategic leadership, brand vision, and client-first hospitality advisory across India.\r\n\r\nGuided by the principle <em>Dream · Plan · Achieve</em>, she brings a forward-looking perspective to modern hospitality consulting—bridging creative concept development with disciplined business planning and sustainable growth.\r\n\r\nHer leadership focus centres on empowering restaurant, café, hotel, cloud kitchen, and resort founders with clarity, structured execution, and long-term operational confidence from day one.\r\n\r\n</div>\r\n<div class=\"leader-chips\">Future Leadership\r\nBrand Strategy\r\nClient Partnerships\r\nBusiness Growth\r\nHospitality Innovation\r\nStrategic Planning</div>\r\n<div class=\"vision-callout\">\r\n<div class=\"vc-head\"><i class=\"fas fa-compass\"></i>\r\nFuture Vision &amp; Leadership</div>\r\nAs Future CEO, Vihani champions a culture of excellence, transparency, and purposeful execution—ensuring every hospitality venture partnered with Artha transforms ambitious ideas into thriving, guest-loved destinations.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 3: FOUNDER & DIRECTOR SPOTLIGHT (ANIL KUMAR K) -->\r\n\r\n<section id=\"anil-kumar\" class=\"leader-spotlight bg-offwhite\">\r\n<div class=\"wrap\">\r\n<div class=\"spotlight-grid reverse\">\r\n\r\n<!-- Biography & Vision Column -->\r\n<div class=\"leader-copy anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>Anil Kumar K</h2>\r\n<div class=\"role-pill\"><i class=\"fas fa-chess-king\"></i>\r\nFounder &amp; Director – Artha Hospitality</div>\r\n<div class=\"leader-bio\">\r\n\r\nChef Anil Kumar K is the Founder &amp; Director of Artha Hospitality, bringing over 25 years of experience in the hospitality industry.\r\n\r\nWith a professional background as a Chef, Anil has extensive hands-on experience in professional kitchens, restaurant operations, kitchen planning, commercial kitchen equipment, food production, and hospitality management.\r\n\r\nHis 25 years of industry experience provide him with a deep understanding of the practical requirements of hotels, restaurants, cafés, catering businesses, and commercial food-service operations.\r\n\r\n</div>\r\n<div class=\"leader-chips\">Professional Kitchens\r\nRestaurant Operations\r\nKitchen Planning\r\nCommercial Kitchen Equipment\r\nFood Production\r\nHospitality Management</div>\r\n<div class=\"vision-callout\">\r\n<div class=\"vc-head\"><i class=\"fas fa-compass\"></i>\r\nStrategic Vision &amp; Leadership</div>\r\nAs Founder &amp; Director of Artha Hospitality, Anil leads the company’s business strategy, kitchen solutions, operational planning, client relationships, and overall execution, with a vision to deliver reliable, efficient, and sustainable hospitality solutions.\r\n\r\n</div>\r\n</div>\r\n<!-- Portrait Column -->\r\n<div class=\"leader-portrait-stage anim-base anim-fade-left delay-100\">\r\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-frame\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/assets/images/about-us-images/anil-kumar-k.jpg\" alt=\"Chef Anil Kumar K - Founder &amp; Director of Artha Hospitality\" /><figcaption class=\"cr-only\">Chef Anil Kumar K - Founder &amp; Director – Artha Hospitality</figcaption></figure>\r\n</div>\r\n<div class=\"portrait-exp-badge\"><strong>25+</strong>\r\nYears in\r\nHospitality</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 4: HR DIRECTOR SPOTLIGHT - SUSHMA AMIN -->\r\n\r\n<section id=\"sushma-amin\" class=\"leader-spotlight bg-sand-light\">\r\n<div class=\"wrap spotlight-grid\">\r\n\r\n<!-- Portrait Column -->\r\n<div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-frame\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/assets/images/about-us-images/sushma-amin.jpg\" alt=\"Sushma Amin - HR Director &amp; Hospitality HR Professional\" /><figcaption class=\"cr-only\">Sushma Amin - HR Director &amp; Hospitality HR Professional</figcaption></figure>\r\n</div>\r\n<div class=\"portrait-exp-badge\"><strong>20+</strong>\r\nYears in HR &amp;\r\nHospitality</div>\r\n</div>\r\n<!-- Biography & Vision Column -->\r\n<div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>Sushma Amin</h2>\r\n<div class=\"role-pill\"><i class=\"fas fa-balance-scale\"></i>\r\nHR Director &amp; Hospitality HR Professional</div>\r\n<div class=\"leader-bio\">\r\n\r\nSushma Amin is a seasoned Human Resources professional with over 20 years of experience in the HR and hospitality industry, bringing extensive expertise in people management, talent acquisition, employee relations, HR operations, and organizational development.\r\n\r\nWith a strong academic background in Bachelor of Arts (BA) and Bachelor of Laws (LLB), she combines professional knowledge with practical industry experience to build effective HR practices and people-centric workplaces.\r\n\r\nThroughout her career, she has worked with leading hospitality establishments, gaining valuable experience in managing diverse workforces, developing HR systems, streamlining recruitment processes, and supporting business growth through effective human resource management.\r\n\r\n</div>\r\n<div class=\"leader-chips\">People Management\r\nTalent Acquisition\r\nEmployee Relations\r\nHR Operations\r\nOrganizational Development\r\nBA &amp; LLB</div>\r\n<div class=\"vision-callout\">\r\n<div class=\"vc-head\"><i class=\"fas fa-bullseye\"></i>\r\nProfessional Vision</div>\r\nHer professional vision is to connect the right talent with the right opportunities, empower people, strengthen organizations, and contribute to the growth of the hospitality industry through ethical, transparent, and result-oriented HR practices.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 4: ARTHA EXECUTIVE MANAGEMENT (SNEHA M. & SANDEEP SHETTY) -->\r\n\r\n<section id=\"executive-management\" class=\"management-section\">\r\n<div class=\"wrap\">\r\n<div class=\"head-center anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">Artha Hospitality Team</span>\r\n<h2>Driving Recruitment, Sales &amp; Operational Excellence.</h2>\r\nConnecting talented hospitality professionals with leading organizations and delivering disciplined, guest-focused operational results every day.\r\n\r\n</div>\r\n<!-- Profile 1: Sneha M. -->\r\n\r\n<article class=\"exec-profile-block anim-base anim-fade-up\">\r\n<div class=\"exec-top-grid\">\r\n<div class=\"exec-photo-wrap\">\r\n<div class=\"exec-photo-frame\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/assets/images/about-us-images/sneha-m.jpg\" alt=\"Sneha M. - HR Executive at Artha Hospitality\" /><figcaption class=\"cr-only\">Sneha M. - HR Executive | Artha Hospitality</figcaption></figure>\r\n</div>\r\n</div>\r\n<div class=\"exec-intro\">\r\n\r\n<span class=\"eyebrow\">People &amp; Talent</span>\r\n<h3>Sneha M.</h3>\r\n<div class=\"exec-role\"><i class=\"fas fa-id-badge\"></i>\r\nHR Executive | Artha Hospitality</div>\r\nAs an HR Executive at Artha Hospitality, I am responsible for identifying, attracting and connecting the right talent with the right opportunities in the hospitality industry.\r\n\r\nI believe that successful businesses are built by the right people. My focus is on understanding client requirements, building strong relationships with candidates and ensuring a smooth and effective recruitment process.\r\n\r\n</div>\r\n</div>\r\n<div class=\"exec-pillars-grid\">\r\n<div class=\"pillar-box\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Vision</h4>\r\n</div>\r\nTo connect talented individuals with the right opportunities and help hospitality businesses grow through quality recruitment, trust and strong professional relationships.\r\n\r\n</div>\r\n<div class=\"pillar-box dark\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Mission</h4>\r\n</div>\r\nTo make recruitment a meaningful experience by bringing together the right people and the right organizations.\r\n\r\n</div>\r\n</div>\r\n</article><!-- Profile 2: Sandeep Shetty -->\r\n\r\n<article class=\"exec-profile-block reverse anim-base anim-fade-up\">\r\n<div class=\"exec-top-grid\">\r\n<div class=\"exec-intro\">\r\n\r\n<span class=\"eyebrow\">Growth &amp; Operations</span>\r\n<h3>Sandeep Shetty</h3>\r\n<div class=\"exec-role\"><i class=\"fas fa-briefcase\"></i>\r\nSales &amp; Operations Manager | Artha Hospitality</div>\r\nAs a Sales &amp; Operations Manager at Artha Hospitality, I am responsible for driving business growth, leading operations, and creating exceptional guest experiences in the hospitality industry.\r\n\r\nI believe that successful hospitality businesses are built on strong leadership, consistent service, and the right people. My focus is on understanding client needs, building lasting business relationships, and ensuring smooth, result-driven operations.\r\n\r\n</div>\r\n<div class=\"exec-photo-wrap\">\r\n<div class=\"exec-photo-frame\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/assets/images/about-us-images/sandeep-shetty.jpg\" alt=\"Sandeep Shetty - Sales &amp; Operations Manager at Artha Hospitality\" /><figcaption class=\"cr-only\">Sandeep Shetty - Sales &amp; Operations Manager | Artha Hospitality</figcaption></figure>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"exec-pillars-grid cols-3\">\r\n<div class=\"pillar-box dark\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Leadership</h4>\r\n</div>\r\nI lead by example — with clarity, accountability, and a people-first approach. My leadership is focused on building high-performing teams, empowering individuals, and creating a culture of ownership, discipline, and excellence.\r\n\r\nI believe a great leader doesn\'t just manage operations; they inspire people to deliver their best every single day.\r\n\r\n</div>\r\n<div class=\"pillar-box\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Vision</h4>\r\n</div>\r\nTo lead Artha Hospitality towards sustainable growth by combining strong sales strategies, operational excellence, and meaningful human connections — and to make it a trusted name in the hospitality industry.\r\n\r\n</div>\r\n<div class=\"pillar-box\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Mission</h4>\r\n</div>\r\nTo drive sales with integrity, deliver operations with excellence, and create value for clients, guests, and the team — by bringing together the right strategy, the right people, and the right execution.\r\n\r\n</div>\r\n</div>\r\n</article></div>\r\n</section><!-- WHY CHOOSE US SECTION -->\r\n\r\n<section id=\"why-choose-us\" class=\"why-choose-section\">\r\n<div class=\"wrap\">\r\n<div class=\"why-choose-head anim-base anim-fade-up\">\r\n\r\n<span class=\"eyebrow\">Why Choose Us?</span>\r\n<h2>Experience That Turns Ideas Into Successful Operations.</h2>\r\n“Backed by over <em>15 years</em> of experience in hospitality and hotel operations, our team combines industry insight with proven strategies to deliver solutions that work from day one.”\r\n\r\n</div>\r\n<div class=\"why-choose-grid\"><article class=\"why-choose-card anim-base anim-fade-up delay-100\"><i class=\"fas fa-award\"></i>\r\n<h3>Industry Experience</h3>\r\nMore than 15 years of hands-on experience in hospitality and hotel operations.\r\n\r\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-200\"><i class=\"fas fa-chart-line\"></i>\r\n<h3>Strategic Approach</h3>\r\nSolutions built around your specific business requirements and operational objectives.\r\n\r\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-300\"><i class=\"fas fa-layer-group\"></i>\r\n<h3>End-to-End Support</h3>\r\nComprehensive guidance across planning, development, design, and everyday operations.\r\n\r\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-300\"><i class=\"fas fa-user-check\"></i>\r\n<h3>Guest-Centred Thinking</h3>\r\nDedicated focus on elevating guest satisfaction, food quality, and service standards.\r\n\r\n</article></div>\r\n</div>\r\n</section><!-- SECTION 5: CTA -->\r\n\r\n<section class=\"cta\">\r\n<div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n\r\n<span class=\"eyebrow\">Let\'s Work Together</span>\r\n<h2>Ready to Build or Elevate Your Hospitality Venture?</h2>\r\nConnect with our leadership and operations team to discuss kitchen planning, recruitment, or end-to-end hospitality consultancy.\r\n<div class=\"cta-btns\"><a class=\"btn btn-light\" href=\"artha-hospitality-contact-us.html\">Start a Conversation <span class=\"arrow\">↗</span></a>\r\n<a class=\"btn btn-outline-light\" href=\"tel:+918951511234\">Call Us Today</a></div>\r\n</div>\r\n</section>', 'About', '', 'inherit', 'closed', 'closed', '', '11-revision-v1', '', '', '2026-11-26 05:58:11', '2026-11-26 05:58:11', '', 11, 'http://localhost/artha-hospitality-management/?p=21', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(22, 1, '2026-11-26 06:01:00', '2026-11-26 06:01:00', '<!-- NEW 75VH ABOUT US HERO SECTION -->\r\n\r\n<section id=\"about-top\" class=\"about-editorial-hero\">\r\n<div class=\"wrap hero-inner\">\r\n\r\n<!-- Column 1: Editorial Copy & CTAs -->\r\n<div class=\"hero-story-col anim-base anim-fade-right\">\r\n<div class=\"hero-top-tags\"><nav class=\"breadcrumb-pill\" aria-label=\"Breadcrumb\"><a href=\"index.html\">Home</a>\r\n<i class=\"fas fa-chevron-right\"></i>\r\n<span class=\"current\">About Us</span></nav><span class=\"eyebrow\">Who We Are</span>\r\n\r\n</div>\r\n<h1>Shaping the Future of <em>Thoughtful Hospitality</em> From Concept to Table.</h1>\r\nAt Artha Hospitality Management, we partner with visionary restaurateurs, hoteliers, and hospitality entrepreneurs to turn ambitious concepts into resilient, high-performing destinations.\r\n<div class=\"hero-cta-group\"><a class=\"btn btn-primary\" href=\"artha-hospitality-contact-us.html\">Partner With Artha <span class=\"arrow\">↗</span></a>\r\n<a class=\"btn btn-ghost\" href=\"index.html#services\">Our Capabilities</a></div>\r\n</div>\r\n<!-- Column 2: Single Image Sculptural Stage with Theme Shapes -->\r\n<div class=\"hero-visual-stage anim-base anim-fade-left delay-100\">\r\n\r\n<!-- Shape 1: Concentric Gold Contour Rings -->\r\n\r\n<!-- Shape 2: Deep Espresso Architectural Offset Slab -->\r\n<div class=\"stage-shape-slab\" aria-hidden=\"true\"></div>\r\n<!-- Shape 3: Gold Offset Wireframe Arch -->\r\n<div class=\"stage-shape-wireframe\" aria-hidden=\"true\"></div>\r\n<!-- Shape 4: Gold Dot Matrix Pattern -->\r\n<div class=\"stage-shape-dots\" aria-hidden=\"true\"></div>\r\n<!-- Shape 5: Floating Espresso & Gold Medallion Seal -->\r\n<div class=\"stage-medallion\">\r\n\r\n&nbsp;\r\n<div class=\"med-text\"><strong>15+ Yrs</strong>\r\nHospitality Mastery</div>\r\n</div>\r\n<!-- Main Sculpted Arched Image Panel -->\r\n<div class=\"hero-arch-panel\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-about-us-hero.jpg\" alt=\"Hospitality team collaborating in a professional kitchen\" /><figcaption class=\"cr-only\">Hospitality team collaborating in a professional kitchen</figcaption></figure>\r\n<div class=\"arch-caption-bar\">\r\n<div><span class=\"tag-sub\">Operational Craft</span>\r\n<span class=\"tag-title\">Ground-Level Expertise</span></div>\r\n&nbsp;\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 1: ENGAGING ABOUT ARTHA HOSPITALITY -->\r\n\r\n<section id=\"about-artha\" class=\"about-artha-section\">\r\n<div class=\"wrap\">\r\n<div class=\"about-artha-grid\">\r\n\r\n<!-- Story & Philosophy Copy -->\r\n<div class=\"artha-story-copy anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">About Us</span>\r\n<h2>Hospitality Begins With <em>Great Service.</em></h2>\r\n<p class=\"lead-p\">At Artha, we believe that great hospitality begins with great service. Our mission is to help restaurant owners and hospitality businesses overcome their toughest service challenges, improve guest satisfaction, and grow sustainably.</p>\r\nWith a deep understanding of the industry and a commitment to excellence, we provide tailor-made solutions that create lasting value for our partners.\r\n<div class=\"artha-values-list\">\r\n<div class=\"artha-value-item\">\r\n\r\n&nbsp;\r\n<div>\r\n<h4>Industry Understanding</h4>\r\nGrounded in more than 15 years of hospitality and hotel operations experience.\r\n\r\n</div>\r\n</div>\r\n<div class=\"artha-value-item\">\r\n\r\n&nbsp;\r\n<div>\r\n<h4>Tailor-Made Solutions</h4>\r\nApproaches shaped around your business, your guests, and your operational goals.\r\n\r\n</div>\r\n</div>\r\n<div class=\"artha-value-item\">\r\n\r\n&nbsp;\r\n<div>\r\n<h4>Commitment to Excellence</h4>\r\nA consistent focus on quality, service standards, and sustainable long-term growth.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n<a class=\"btn btn-primary\" href=\"index.html#services\">Discover What We Do <span class=\"arrow\">↗</span></a>\r\n\r\n</div>\r\n<!-- Layered Hospitality Collage -->\r\n<div class=\"artha-story-visual anim-base anim-fade-left delay-100\">\r\n<div class=\"artha-vis-tag\">\r\n\r\n&nbsp;\r\n<div>15+ Years Experience\r\n<strong>Solutions That Work From Day One</strong></div>\r\n</div>\r\n<div class=\"artha-vis-main\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/slide-img-2-lgr.jpg\" alt=\"Elegant hospitality reception and dining space\" /><figcaption class=\"cr-only\">Elegant hospitality reception and dining space</figcaption></figure>\r\n</div>\r\n<div class=\"artha-vis-sub\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-management-about-us-sml-img.jpg\" alt=\"Premium restaurant dining environment\" /><figcaption class=\"cr-only\">Premium restaurant dining environment</figcaption></figure>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 2: LEADERSHIP & VISION + CEO SPOTLIGHT (VIHANI ANIL) -->\r\n\r\n<section id=\"vihani-anil\" class=\"leader-spotlight bg-sand-light\">\r\n<div class=\"wrap\">\r\n<div class=\"head-center anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>The Minds Driving Culinary, People &amp; Operational Excellence.</h2>\r\nGuided by visionary leadership, seasoned hospitality veterans, kitchen innovators, HR strategists, and operations leaders committed to building resilient, people-first hospitality ventures.\r\n\r\n</div>\r\n<div class=\"spotlight-grid\">\r\n\r\n<!-- Portrait Column -->\r\n<div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-frame\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/vihani-anil.jpg\" alt=\"Vihani Anil - Future CEO, Artha Hospitality Management\" /><figcaption class=\"cr-only\">Vihani Anil - Future CEO | Artha Hospitality Management</figcaption></figure>\r\n</div>\r\n<div class=\"portrait-exp-badge\"><strong>Future</strong>\r\nCEO · Artha\r\nHospitality</div>\r\n</div>\r\n<!-- Biography & Vision Column -->\r\n<div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>Vihani Anil</h2>\r\n<div class=\"role-pill\"><i class=\"fas fa-crown\"></i>\r\nFuture CEO | Artha Hospitality Management</div>\r\n<div class=\"leader-bio\">\r\n\r\nVihani Anil is the Future CEO of Artha Hospitality Management, representing the next generation of strategic leadership, brand vision, and client-first hospitality advisory across India.\r\n\r\nGuided by the principle <em>Dream · Plan · Achieve</em>, she brings a forward-looking perspective to modern hospitality consulting—bridging creative concept development with disciplined business planning and sustainable growth.\r\n\r\nHer leadership focus centres on empowering restaurant, café, hotel, cloud kitchen, and resort founders with clarity, structured execution, and long-term operational confidence from day one.\r\n\r\n</div>\r\n<div class=\"leader-chips\">Future Leadership\r\nBrand Strategy\r\nClient Partnerships\r\nBusiness Growth\r\nHospitality Innovation\r\nStrategic Planning</div>\r\n<div class=\"vision-callout\">\r\n<div class=\"vc-head\"><i class=\"fas fa-compass\"></i>\r\nFuture Vision &amp; Leadership</div>\r\nAs Future CEO, Vihani champions a culture of excellence, transparency, and purposeful execution—ensuring every hospitality venture partnered with Artha transforms ambitious ideas into thriving, guest-loved destinations.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 3: FOUNDER & DIRECTOR SPOTLIGHT (ANIL KUMAR K) -->\r\n\r\n<section id=\"anil-kumar\" class=\"leader-spotlight bg-offwhite\">\r\n<div class=\"wrap\">\r\n<div class=\"spotlight-grid reverse\">\r\n\r\n<!-- Biography & Vision Column -->\r\n<div class=\"leader-copy anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>Anil Kumar K</h2>\r\n<div class=\"role-pill\"><i class=\"fas fa-chess-king\"></i>\r\nFounder &amp; Director – Artha Hospitality</div>\r\n<div class=\"leader-bio\">\r\n\r\nChef Anil Kumar K is the Founder &amp; Director of Artha Hospitality, bringing over 25 years of experience in the hospitality industry.\r\n\r\nWith a professional background as a Chef, Anil has extensive hands-on experience in professional kitchens, restaurant operations, kitchen planning, commercial kitchen equipment, food production, and hospitality management.\r\n\r\nHis 25 years of industry experience provide him with a deep understanding of the practical requirements of hotels, restaurants, cafés, catering businesses, and commercial food-service operations.\r\n\r\n</div>\r\n<div class=\"leader-chips\">Professional Kitchens\r\nRestaurant Operations\r\nKitchen Planning\r\nCommercial Kitchen Equipment\r\nFood Production\r\nHospitality Management</div>\r\n<div class=\"vision-callout\">\r\n<div class=\"vc-head\"><i class=\"fas fa-compass\"></i>\r\nStrategic Vision &amp; Leadership</div>\r\nAs Founder &amp; Director of Artha Hospitality, Anil leads the company’s business strategy, kitchen solutions, operational planning, client relationships, and overall execution, with a vision to deliver reliable, efficient, and sustainable hospitality solutions.\r\n\r\n</div>\r\n</div>\r\n<!-- Portrait Column -->\r\n<div class=\"leader-portrait-stage anim-base anim-fade-left delay-100\">\r\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-frame\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/anil-kumar-k.jpg\" alt=\"Chef Anil Kumar K - Founder &amp; Director of Artha Hospitality\" /><figcaption class=\"cr-only\">Chef Anil Kumar K - Founder &amp; Director – Artha Hospitality</figcaption></figure>\r\n</div>\r\n<div class=\"portrait-exp-badge\"><strong>25+</strong>\r\nYears in\r\nHospitality</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 4: HR DIRECTOR SPOTLIGHT - SUSHMA AMIN -->\r\n\r\n<section id=\"sushma-amin\" class=\"leader-spotlight bg-sand-light\">\r\n<div class=\"wrap spotlight-grid\">\r\n\r\n<!-- Portrait Column -->\r\n<div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n<div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n<div class=\"portrait-frame\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/sushma-amin.jpg\" alt=\"Sushma Amin - HR Director &amp; Hospitality HR Professional\" /><figcaption class=\"cr-only\">Sushma Amin - HR Director &amp; Hospitality HR Professional</figcaption></figure>\r\n</div>\r\n<div class=\"portrait-exp-badge\"><strong>20+</strong>\r\nYears in HR &amp;\r\nHospitality</div>\r\n</div>\r\n<!-- Biography & Vision Column -->\r\n<div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n\r\n<span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n<h2>Sushma Amin</h2>\r\n<div class=\"role-pill\"><i class=\"fas fa-balance-scale\"></i>\r\nHR Director &amp; Hospitality HR Professional</div>\r\n<div class=\"leader-bio\">\r\n\r\nSushma Amin is a seasoned Human Resources professional with over 20 years of experience in the HR and hospitality industry, bringing extensive expertise in people management, talent acquisition, employee relations, HR operations, and organizational development.\r\n\r\nWith a strong academic background in Bachelor of Arts (BA) and Bachelor of Laws (LLB), she combines professional knowledge with practical industry experience to build effective HR practices and people-centric workplaces.\r\n\r\nThroughout her career, she has worked with leading hospitality establishments, gaining valuable experience in managing diverse workforces, developing HR systems, streamlining recruitment processes, and supporting business growth through effective human resource management.\r\n\r\n</div>\r\n<div class=\"leader-chips\">People Management\r\nTalent Acquisition\r\nEmployee Relations\r\nHR Operations\r\nOrganizational Development\r\nBA &amp; LLB</div>\r\n<div class=\"vision-callout\">\r\n<div class=\"vc-head\"><i class=\"fas fa-bullseye\"></i>\r\nProfessional Vision</div>\r\nHer professional vision is to connect the right talent with the right opportunities, empower people, strengthen organizations, and contribute to the growth of the hospitality industry through ethical, transparent, and result-oriented HR practices.\r\n\r\n</div>\r\n</div>\r\n</div>\r\n</section><!-- SECTION 4: ARTHA EXECUTIVE MANAGEMENT (SNEHA M. & SANDEEP SHETTY) -->\r\n\r\n<section id=\"executive-management\" class=\"management-section\">\r\n<div class=\"wrap\">\r\n<div class=\"head-center anim-base anim-fade-right\">\r\n\r\n<span class=\"eyebrow\">Artha Hospitality Team</span>\r\n<h2>Driving Recruitment, Sales &amp; Operational Excellence.</h2>\r\nConnecting talented hospitality professionals with leading organizations and delivering disciplined, guest-focused operational results every day.\r\n\r\n</div>\r\n<!-- Profile 1: Sneha M. -->\r\n\r\n<article class=\"exec-profile-block anim-base anim-fade-up\">\r\n<div class=\"exec-top-grid\">\r\n<div class=\"exec-photo-wrap\">\r\n<div class=\"exec-photo-frame\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/sneha-m.jpg\" alt=\"Sneha M. - HR Executive at Artha Hospitality\" /><figcaption class=\"cr-only\">Sneha M. - HR Executive | Artha Hospitality</figcaption></figure>\r\n</div>\r\n</div>\r\n<div class=\"exec-intro\">\r\n\r\n<span class=\"eyebrow\">People &amp; Talent</span>\r\n<h3>Sneha M.</h3>\r\n<div class=\"exec-role\"><i class=\"fas fa-id-badge\"></i>\r\nHR Executive | Artha Hospitality</div>\r\nAs an HR Executive at Artha Hospitality, I am responsible for identifying, attracting and connecting the right talent with the right opportunities in the hospitality industry.\r\n\r\nI believe that successful businesses are built by the right people. My focus is on understanding client requirements, building strong relationships with candidates and ensuring a smooth and effective recruitment process.\r\n\r\n</div>\r\n</div>\r\n<div class=\"exec-pillars-grid\">\r\n<div class=\"pillar-box\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Vision</h4>\r\n</div>\r\nTo connect talented individuals with the right opportunities and help hospitality businesses grow through quality recruitment, trust and strong professional relationships.\r\n\r\n</div>\r\n<div class=\"pillar-box dark\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Mission</h4>\r\n</div>\r\nTo make recruitment a meaningful experience by bringing together the right people and the right organizations.\r\n\r\n</div>\r\n</div>\r\n</article><!-- Profile 2: Sandeep Shetty -->\r\n\r\n<article class=\"exec-profile-block reverse anim-base anim-fade-up\">\r\n<div class=\"exec-top-grid\">\r\n<div class=\"exec-intro\">\r\n\r\n<span class=\"eyebrow\">Growth &amp; Operations</span>\r\n<h3>Sandeep Shetty</h3>\r\n<div class=\"exec-role\"><i class=\"fas fa-briefcase\"></i>\r\nSales &amp; Operations Manager | Artha Hospitality</div>\r\nAs a Sales &amp; Operations Manager at Artha Hospitality, I am responsible for driving business growth, leading operations, and creating exceptional guest experiences in the hospitality industry.\r\n\r\nI believe that successful hospitality businesses are built on strong leadership, consistent service, and the right people. My focus is on understanding client needs, building lasting business relationships, and ensuring smooth, result-driven operations.\r\n\r\n</div>\r\n<div class=\"exec-photo-wrap\">\r\n<div class=\"exec-photo-frame\">\r\n<figure class=\"cr-figure\"><img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/sandeep-shetty.jpg\" alt=\"Sandeep Shetty - Sales &amp; Operations Manager at Artha Hospitality\" /><figcaption class=\"cr-only\">Sandeep Shetty - Sales &amp; Operations Manager | Artha Hospitality</figcaption></figure>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"exec-pillars-grid cols-3\">\r\n<div class=\"pillar-box dark\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Leadership</h4>\r\n</div>\r\nI lead by example — with clarity, accountability, and a people-first approach. My leadership is focused on building high-performing teams, empowering individuals, and creating a culture of ownership, discipline, and excellence.\r\n\r\nI believe a great leader doesn\'t just manage operations; they inspire people to deliver their best every single day.\r\n\r\n</div>\r\n<div class=\"pillar-box\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Vision</h4>\r\n</div>\r\nTo lead Artha Hospitality towards sustainable growth by combining strong sales strategies, operational excellence, and meaningful human connections — and to make it a trusted name in the hospitality industry.\r\n\r\n</div>\r\n<div class=\"pillar-box\">\r\n<div class=\"pb-head\">\r\n\r\n&nbsp;\r\n<h4>My Mission</h4>\r\n</div>\r\nTo drive sales with integrity, deliver operations with excellence, and create value for clients, guests, and the team — by bringing together the right strategy, the right people, and the right execution.\r\n\r\n</div>\r\n</div>\r\n</article></div>\r\n</section><!-- WHY CHOOSE US SECTION -->\r\n\r\n<section id=\"why-choose-us\" class=\"why-choose-section\">\r\n<div class=\"wrap\">\r\n<div class=\"why-choose-head anim-base anim-fade-up\">\r\n\r\n<span class=\"eyebrow\">Why Choose Us?</span>\r\n<h2>Experience That Turns Ideas Into Successful Operations.</h2>\r\n“Backed by over <em>15 years</em> of experience in hospitality and hotel operations, our team combines industry insight with proven strategies to deliver solutions that work from day one.”\r\n\r\n</div>\r\n<div class=\"why-choose-grid\"><article class=\"why-choose-card anim-base anim-fade-up delay-100\"><i class=\"fas fa-award\"></i>\r\n<h3>Industry Experience</h3>\r\nMore than 15 years of hands-on experience in hospitality and hotel operations.\r\n\r\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-200\"><i class=\"fas fa-chart-line\"></i>\r\n<h3>Strategic Approach</h3>\r\nSolutions built around your specific business requirements and operational objectives.\r\n\r\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-300\"><i class=\"fas fa-layer-group\"></i>\r\n<h3>End-to-End Support</h3>\r\nComprehensive guidance across planning, development, design, and everyday operations.\r\n\r\n</article><article class=\"why-choose-card anim-base anim-fade-up delay-300\"><i class=\"fas fa-user-check\"></i>\r\n<h3>Guest-Centred Thinking</h3>\r\nDedicated focus on elevating guest satisfaction, food quality, and service standards.\r\n\r\n</article></div>\r\n</div>\r\n</section><!-- SECTION 5: CTA -->\r\n\r\n<section class=\"cta\">\r\n<div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n\r\n<span class=\"eyebrow\">Let\'s Work Together</span>\r\n<h2>Ready to Build or Elevate Your Hospitality Venture?</h2>\r\nConnect with our leadership and operations team to discuss kitchen planning, recruitment, or end-to-end hospitality consultancy.\r\n<div class=\"cta-btns\"><a class=\"btn btn-light\" href=\"artha-hospitality-contact-us.html\">Start a Conversation <span class=\"arrow\">↗</span></a>\r\n<a class=\"btn btn-outline-light\" href=\"tel:+918951511234\">Call Us Today</a></div>\r\n</div>\r\n</section>', 'About', '', 'inherit', 'closed', 'closed', '', '11-revision-v1', '', '', '2026-11-26 06:01:00', '2026-11-26 06:01:00', '', 11, 'http://localhost/artha-hospitality-management/?p=22', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(23, 1, '2026-11-26 08:54:50', '2026-11-26 08:54:50', '<body class=\"page-about-us\">\r\n\r\n<!-- TOP HIRING ANNOUNCEMENT STRIP -->\r\n<div class=\"hiring-strip\" role=\"region\" aria-label=\"Hiring announcement\">\r\n  <div class=\"hiring-strip-inner\">\r\n    <span class=\"hiring-badge\">WE ARE HIRING</span>\r\n    <span class=\"hiring-text\">— Hotel Jobs in Mangalore &amp; Karnataka | Chefs, Front Office, Housekeeping, F&amp;B Service |</span>\r\n    <a href=\"artha-hospitality-openings.html\" class=\"hiring-cta\">Apply Now &rarr;</a>\r\n  </div>\r\n</div>\r\n\r\n<!-- HEADER -->\r\n<header id=\"site-header\">\r\n  <div class=\"wrap nav\">\r\n    <a href=\"index.html\" class=\"logo\" aria-label=\"Artha Hospitality Management home\">\r\n      <figure class=\"cr-figure\">\r\n        <img src=\"images/artha-hospitality-management-logo.png\" alt=\"Artha Hospitality Management Logo\" class=\"brand-logo\">\r\n        <figcaption class=\"cr-only\">Artha Hospitality Management Logo</figcaption>\r\n      </figure>\r\n    </a>\r\n    <nav class=\"nav-links\" aria-label=\"Primary\">\r\n      <a href=\"index.html\">Home</a>\r\n      <a href=\"artha-hospitality-about-us.html\" class=\"active\">About</a>\r\n      \r\n      <!-- Dropdown for Services -->\r\n      <div class=\"nav-item-dropdown\">\r\n        <a href=\"index.html#services\">Services <i class=\"fas fa-chevron-down\"></i></a>\r\n        <div class=\"dropdown-menu\">\r\n          <a href=\"artha-hospitality-management-capital-investment-plan.html\"><i class=\"fas fa-chart-pie\"></i> Capital Investment Plan</a>\r\n          <a href=\"artha-hospitality-management-location-selection.html\"><i class=\"fas fa-map-marked-alt\"></i> Location Selection</a>\r\n          <a href=\"artha-hospitality-management-outlet-kitchen-design.html\"><i class=\"fas fa-utensils\"></i> Outlet &amp; Kitchen Design</a>\r\n          <a href=\"artha-hospitality-management-staffing-support.html\"><i class=\"fas fa-user-graduate\"></i> Staffing Support</a>\r\n          <a href=\"artha-hospitality-management-civil-work.html\"><i class=\"fas fa-hard-hat\"></i> Civil Work</a>\r\n          <a href=\"artha-hospitality-management-interior-work.html\"><i class=\"fas fa-layer-group\"></i> Interior Work</a>\r\n          <a href=\"artha-hospitality-management-marketing-service.html\"><i class=\"fas fa-bullseye\"></i> Marketing Service</a>\r\n          <a href=\"artha-hospitality-management-food-running-cost.html\"><i class=\"fas fa-file-invoice-dollar\"></i> Food &amp; Running Cost</a>\r\n          <a href=\"artha-hospitality-management-vendor-selection-purchase-advice.html\"><i class=\"fas fa-truck\"></i> Vendor Selection &amp; Purchase Advice</a>\r\n          <a href=\"artha-hospitality-management-food-service-quality.html\"><i class=\"fas fa-award\"></i> Food and Service Quality</a>\r\n        </div>\r\n      </div>\r\n\r\n      <a href=\"artha-hospitality-management-industries.html\">Industries</a>\r\n      <a href=\"artha-hospitality-openings.html\">Careers</a>\r\n      <a href=\"artha-hospitality-clients.html\">Clients</a>\r\n      <a href=\"artha-hospitality-contact-us.html\">Contact</a>\r\n      <a href=\"artha-hospitality-contact-us.html#contact-form-section\" class=\"nav-cta\">Get in Touch</a>\r\n    </nav>\r\n    \r\n    <button class=\"menu-toggle\" id=\"menuToggle\" aria-label=\"Toggle menu\" aria-expanded=\"false\" aria-controls=\"mobileMenu\">\r\n      <span></span><span></span><span></span>\r\n    </button>\r\n  </div>\r\n</header>\r\n\r\n<!-- MOBILE MENU -->\r\n<div class=\"mobile-menu\" id=\"mobileMenu\" role=\"dialog\" aria-label=\"Mobile navigation\">\r\n  <a href=\"index.html\">Home</a>\r\n  <a href=\"artha-hospitality-about-us.html\" class=\"active\">About</a>\r\n  \r\n  <!-- Mobile Dropdown for Services -->\r\n  <details class=\"mobile-dropdown\">\r\n    <summary>Services</summary>\r\n    <div class=\"mobile-sub-links\">\r\n      <a href=\"artha-hospitality-management-capital-investment-plan.html\"><i class=\"fas fa-chart-pie\"></i> Capital Investment Plan</a>\r\n      <a href=\"artha-hospitality-management-location-selection.html\"><i class=\"fas fa-map-marked-alt\"></i> Location Selection</a>\r\n      <a href=\"artha-hospitality-management-outlet-kitchen-design.html\"><i class=\"fas fa-utensils\"></i> Outlet &amp; Kitchen Design</a>\r\n      <a href=\"artha-hospitality-management-staffing-support.html\"><i class=\"fas fa-user-graduate\"></i> Staffing Support</a>\r\n      <a href=\"artha-hospitality-management-civil-work.html\"><i class=\"fas fa-hard-hat\"></i> Civil Work</a>\r\n      <a href=\"artha-hospitality-management-interior-work.html\"><i class=\"fas fa-layer-group\"></i> Interior Work</a>\r\n      <a href=\"artha-hospitality-management-marketing-service.html\"><i class=\"fas fa-bullseye\"></i> Marketing Service</a>\r\n      <a href=\"artha-hospitality-management-food-running-cost.html\"><i class=\"fas fa-file-invoice-dollar\"></i> Food &amp; Running Cost</a>\r\n      <a href=\"artha-hospitality-management-vendor-selection-purchase-advice.html\"><i class=\"fas fa-truck\"></i> Vendor Selection &amp; Purchase Advice</a>\r\n      <a href=\"artha-hospitality-management-food-service-quality.html\"><i class=\"fas fa-award\"></i> Food and Service Quality</a>\r\n    </div>\r\n  </details>\r\n\r\n  <a href=\"artha-hospitality-management-industries.html\">Industries</a>\r\n      <a href=\"artha-hospitality-openings.html\">Careers</a>\r\n      <a href=\"artha-hospitality-clients.html\">Clients</a>\r\n  <a href=\"artha-hospitality-contact-us.html\">Contact</a>\r\n  <a href=\"artha-hospitality-contact-us.html#contact-form-section\" class=\"btn btn-primary\">Get in Touch</a>\r\n</div>\r\n\r\n<!-- NEW 75VH ABOUT US HERO SECTION -->\r\n<section class=\"about-editorial-hero\" id=\"about-top\">\r\n  <div class=\"wrap hero-inner\">\r\n\r\n    <!-- Column 1: Editorial Copy & CTAs -->\r\n    <div class=\"hero-story-col anim-base anim-fade-right\">\r\n      <div class=\"hero-top-tags\">\r\n        <nav class=\"breadcrumb-pill\" aria-label=\"Breadcrumb\">\r\n          <a href=\"index.html\">Home</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <span class=\"current\">About Us</span>\r\n        </nav>\r\n        <span class=\"eyebrow\">Who We Are</span>\r\n      </div>\r\n\r\n      <h1>Shaping the Future of <em>Thoughtful Hospitality</em> From Concept to Table.</h1>\r\n      <p>At Artha Hospitality Management, we partner with visionary restaurateurs, hoteliers, and hospitality entrepreneurs to turn ambitious concepts into resilient, high-performing destinations.</p>\r\n\r\n      <div class=\"hero-cta-group\">\r\n        <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-primary\">Partner With Artha <span class=\"arrow\">↗</span></a>\r\n        <a href=\"index.html#services\" class=\"btn btn-ghost\">Our Capabilities</a>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Column 2: Single Image Sculptural Stage with Theme Shapes -->\r\n    <div class=\"hero-visual-stage anim-base anim-fade-left delay-100\">\r\n      <!-- Shape 1: Concentric Gold Contour Rings -->\r\n      <svg class=\"stage-shape-rings\" viewBox=\"0 0 240 240\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"120\" cy=\"120\" r=\"110\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"82\" opacity=\"0.65\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"54\" opacity=\"0.4\" />\r\n      </svg>\r\n\r\n      <!-- Shape 2: Deep Espresso Architectural Offset Slab -->\r\n      <div class=\"stage-shape-slab\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 3: Gold Offset Wireframe Arch -->\r\n      <div class=\"stage-shape-wireframe\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 4: Gold Dot Matrix Pattern -->\r\n      <div class=\"stage-shape-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 5: Floating Espresso & Gold Medallion Seal -->\r\n      <div class=\"stage-medallion\">\r\n        <span class=\"med-icon\" aria-hidden=\"true\"><i class=\"fas fa-award\"></i></span>\r\n        <div class=\"med-text\">\r\n          <strong>15+ Yrs</strong>\r\n          <span>Hospitality Mastery</span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Main Sculpted Arched Image Panel -->\r\n      <div class=\"hero-arch-panel\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"images/artha-hospitality-about-us-hero.jpg\" alt=\"Hospitality team collaborating in a professional kitchen\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Hospitality team collaborating in a professional kitchen</figcaption>\r\n        </figure>\r\n        <div class=\"arch-caption-bar\">\r\n          <div>\r\n            <span class=\"tag-sub\">Operational Craft</span>\r\n            <span class=\"tag-title\">Ground-Level Expertise</span>\r\n          </div>\r\n          <span class=\"tag-ic\" aria-hidden=\"true\"><i class=\"fas fa-compass\"></i></span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 1: ENGAGING ABOUT ARTHA HOSPITALITY -->\r\n<section class=\"about-artha-section\" id=\"about-artha\">\r\n  <div class=\"wrap\">\r\n    <div class=\"about-artha-grid\">\r\n\r\n      <!-- Story & Philosophy Copy -->\r\n      <div class=\"artha-story-copy anim-base anim-fade-right\">\r\n        <span class=\"eyebrow\">About Us</span>\r\n        <h2>Hospitality Begins With <em>Great Service.</em></h2>\r\n        <p class=\"lead-p\">At Artha, we believe that great hospitality begins with great service. Our mission is to help restaurant owners and hospitality businesses overcome their toughest service challenges, improve guest satisfaction, and grow sustainably.</p>\r\n        <p>With a deep understanding of the industry and a commitment to excellence, we provide tailor-made solutions that create lasting value for our partners.</p>\r\n\r\n        <div class=\"artha-values-list\">\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-hotel\"></i></span>\r\n            <div>\r\n              <h4>Industry Understanding</h4>\r\n              <p>Grounded in more than 15 years of hospitality and hotel operations experience.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-star\"></i></span>\r\n            <div>\r\n              <h4>Tailor-Made Solutions</h4>\r\n              <p>Approaches shaped around your business, your guests, and your operational goals.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-check-circle\"></i></span>\r\n            <div>\r\n              <h4>Commitment to Excellence</h4>\r\n              <p>A consistent focus on quality, service standards, and sustainable long-term growth.</p>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <a href=\"index.html#services\" class=\"btn btn-primary\">Discover What We Do <span class=\"arrow\">↗</span></a>\r\n      </div>\r\n\r\n      <!-- Layered Hospitality Collage -->\r\n      <div class=\"artha-story-visual anim-base anim-fade-left delay-100\">\r\n        <div class=\"artha-vis-tag\">\r\n          <span class=\"vt-ic\" aria-hidden=\"true\"><i class=\"fas fa-compass\"></i></span>\r\n          <div>\r\n            <span>15+ Years Experience</span>\r\n            <strong>Solutions That Work From Day One</strong>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"artha-vis-main\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"images/slide-img-2-lgr.jpg\" alt=\"Elegant hospitality reception and dining space\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Elegant hospitality reception and dining space</figcaption>\r\n          </figure>\r\n        </div>\r\n\r\n        <div class=\"artha-vis-sub\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"images/artha-hospitality-management-about-us-sml-img.jpg\" alt=\"Premium restaurant dining environment\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Premium restaurant dining environment</figcaption>\r\n          </figure>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 2: LEADERSHIP & VISION + CEO SPOTLIGHT (VIHANI ANIL) -->\r\n<section class=\"leader-spotlight bg-sand-light\" id=\"vihani-anil\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n      <h2>The Minds Driving Culinary, People &amp; Operational Excellence.</h2>\r\n      <p>Guided by visionary leadership, seasoned hospitality veterans, kitchen innovators, HR strategists, and operations leaders committed to building resilient, people-first hospitality ventures.</p>\r\n    </div>\r\n\r\n    <div class=\"spotlight-grid\">\r\n\r\n      <!-- Portrait Column -->\r\n      <div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n        <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-frame\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"images/vihani-anil.jpg\" alt=\"Vihani Anil - Future CEO, Artha Hospitality Management\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Vihani Anil - Future CEO | Artha Hospitality Management</figcaption>\r\n          </figure>\r\n        </div>\r\n        <div class=\"portrait-exp-badge\">\r\n          <strong>Future</strong>\r\n          <span>CEO · Artha<br>Hospitality</span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Biography & Vision Column -->\r\n      <div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n        <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n        <h2>Vihani Anil</h2>\r\n        <div class=\"role-pill\">\r\n          <i class=\"fas fa-crown\"></i>\r\n          <span>Future CEO | Artha Hospitality Management</span>\r\n        </div>\r\n\r\n        <div class=\"leader-bio\">\r\n          <p>Vihani Anil is the Future CEO of Artha Hospitality Management, representing the next generation of strategic leadership, brand vision, and client-first hospitality advisory across India.</p>\r\n          <p>Guided by the principle <em>Dream · Plan · Achieve</em>, she brings a forward-looking perspective to modern hospitality consulting—bridging creative concept development with disciplined business planning and sustainable growth.</p>\r\n          <p>Her leadership focus centres on empowering restaurant, café, hotel, cloud kitchen, and resort founders with clarity, structured execution, and long-term operational confidence from day one.</p>\r\n        </div>\r\n\r\n        <div class=\"leader-chips\">\r\n          <span>Future Leadership</span>\r\n          <span>Brand Strategy</span>\r\n          <span>Client Partnerships</span>\r\n          <span>Business Growth</span>\r\n          <span>Hospitality Innovation</span>\r\n          <span>Strategic Planning</span>\r\n        </div>\r\n\r\n        <div class=\"vision-callout\">\r\n          <div class=\"vc-head\">\r\n            <i class=\"fas fa-compass\"></i>\r\n            <span>Future Vision &amp; Leadership</span>\r\n          </div>\r\n          <p>As Future CEO, Vihani champions a culture of excellence, transparency, and purposeful execution—ensuring every hospitality venture partnered with Artha transforms ambitious ideas into thriving, guest-loved destinations.</p>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 3: FOUNDER & DIRECTOR SPOTLIGHT (ANIL KUMAR K) -->\r\n<section class=\"leader-spotlight bg-offwhite\" id=\"anil-kumar\">\r\n  <div class=\"wrap\">\r\n    <div class=\"spotlight-grid reverse\">\r\n\r\n      <!-- Biography & Vision Column -->\r\n      <div class=\"leader-copy anim-base anim-fade-right\">\r\n        <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n        <h2>Anil Kumar K</h2>\r\n        <div class=\"role-pill\">\r\n          <i class=\"fas fa-chess-king\"></i>\r\n          <span>Founder &amp; Director – Artha Hospitality</span>\r\n        </div>\r\n\r\n        <div class=\"leader-bio\">\r\n          <p>Chef Anil Kumar K is the Founder &amp; Director of Artha Hospitality, bringing over 25 years of experience in the hospitality industry.</p>\r\n          <p>With a professional background as a Chef, Anil has extensive hands-on experience in professional kitchens, restaurant operations, kitchen planning, commercial kitchen equipment, food production, and hospitality management.</p>\r\n          <p>His 25 years of industry experience provide him with a deep understanding of the practical requirements of hotels, restaurants, cafés, catering businesses, and commercial food-service operations.</p>\r\n        </div>\r\n\r\n        <div class=\"leader-chips\">\r\n          <span>Professional Kitchens</span>\r\n          <span>Restaurant Operations</span>\r\n          <span>Kitchen Planning</span>\r\n          <span>Commercial Kitchen Equipment</span>\r\n          <span>Food Production</span>\r\n          <span>Hospitality Management</span>\r\n        </div>\r\n\r\n        <div class=\"vision-callout\">\r\n          <div class=\"vc-head\">\r\n            <i class=\"fas fa-compass\"></i>\r\n            <span>Strategic Vision &amp; Leadership</span>\r\n          </div>\r\n          <p>As Founder &amp; Director of Artha Hospitality, Anil leads the company’s business strategy, kitchen solutions, operational planning, client relationships, and overall execution, with a vision to deliver reliable, efficient, and sustainable hospitality solutions.</p>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Portrait Column -->\r\n      <div class=\"leader-portrait-stage anim-base anim-fade-left delay-100\">\r\n        <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-frame\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"images/about-us-images/anil-kumar-k.jpg\" alt=\"Chef Anil Kumar K - Founder & Director of Artha Hospitality\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Chef Anil Kumar K - Founder &amp; Director – Artha Hospitality</figcaption>\r\n          </figure>\r\n        </div>\r\n        <div class=\"portrait-exp-badge\">\r\n          <strong>25+</strong>\r\n          <span>Years in<br>Hospitality</span>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: HR DIRECTOR SPOTLIGHT - SUSHMA AMIN -->\r\n<section class=\"leader-spotlight bg-sand-light\" id=\"sushma-amin\">\r\n  <div class=\"wrap spotlight-grid\">\r\n\r\n    <!-- Portrait Column -->\r\n    <div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n      <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n      <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n      <div class=\"portrait-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"images/about-us-images/sushma-amin.jpg\" alt=\"Sushma Amin - HR Director & Hospitality HR Professional\" loading=\"lazy\">\r\n          <figcaption class=\"cr-only\">Sushma Amin - HR Director &amp; Hospitality HR Professional</figcaption>\r\n        </figure>\r\n      </div>\r\n      <div class=\"portrait-exp-badge\">\r\n        <strong>20+</strong>\r\n        <span>Years in HR &amp;<br>Hospitality</span>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Biography & Vision Column -->\r\n    <div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n      <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n      <h2>Sushma Amin</h2>\r\n      <div class=\"role-pill\">\r\n        <i class=\"fas fa-balance-scale\"></i>\r\n        <span>HR Director &amp; Hospitality HR Professional</span>\r\n      </div>\r\n\r\n      <div class=\"leader-bio\">\r\n        <p>Sushma Amin is a seasoned Human Resources professional with over 20 years of experience in the HR and hospitality industry, bringing extensive expertise in people management, talent acquisition, employee relations, HR operations, and organizational development.</p>\r\n        <p>With a strong academic background in Bachelor of Arts (BA) and Bachelor of Laws (LLB), she combines professional knowledge with practical industry experience to build effective HR practices and people-centric workplaces.</p>\r\n        <p>Throughout her career, she has worked with leading hospitality establishments, gaining valuable experience in managing diverse workforces, developing HR systems, streamlining recruitment processes, and supporting business growth through effective human resource management.</p>\r\n      </div>\r\n\r\n      <div class=\"leader-chips\">\r\n        <span>People Management</span>\r\n        <span>Talent Acquisition</span>\r\n        <span>Employee Relations</span>\r\n        <span>HR Operations</span>\r\n        <span>Organizational Development</span>\r\n        <span>BA &amp; LLB</span>\r\n      </div>\r\n\r\n      <div class=\"vision-callout\">\r\n        <div class=\"vc-head\">\r\n          <i class=\"fas fa-bullseye\"></i>\r\n          <span>Professional Vision</span>\r\n        </div>\r\n        <p>Her professional vision is to connect the right talent with the right opportunities, empower people, strengthen organizations, and contribute to the growth of the hospitality industry through ethical, transparent, and result-oriented HR practices.</p>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: ARTHA EXECUTIVE MANAGEMENT (SNEHA M. & SANDEEP SHETTY) -->\r\n<section class=\"management-section\" id=\"executive-management\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Artha Hospitality Team</span>\r\n      <h2>Driving Recruitment, Sales &amp; Operational Excellence.</h2>\r\n      <p>Connecting talented hospitality professionals with leading organizations and delivering disciplined, guest-focused operational results every day.</p>\r\n    </div>\r\n\r\n    <!-- Profile 1: Sneha M. -->\r\n    <article class=\"exec-profile-block anim-base anim-fade-up\">\r\n      <div class=\"exec-top-grid\">\r\n        <div class=\"exec-photo-wrap\">\r\n          <div class=\"exec-photo-frame\">\r\n            <figure class=\"cr-figure\">\r\n              <img src=\"images/about-us-images/sneha-m.jpg\" alt=\"Sneha M. - HR Executive at Artha Hospitality\" loading=\"lazy\">\r\n              <figcaption class=\"cr-only\">Sneha M. - HR Executive | Artha Hospitality</figcaption>\r\n            </figure>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"exec-intro\">\r\n          <span class=\"eyebrow\">People &amp; Talent</span>\r\n          <h3>Sneha M.</h3>\r\n          <div class=\"exec-role\">\r\n            <i class=\"fas fa-id-badge\"></i>\r\n            <span>HR Executive | Artha Hospitality</span>\r\n          </div>\r\n          <p>As an HR Executive at Artha Hospitality, I am responsible for identifying, attracting and connecting the right talent with the right opportunities in the hospitality industry.</p>\r\n          <p>I believe that successful businesses are built by the right people. My focus is on understanding client requirements, building strong relationships with candidates and ensuring a smooth and effective recruitment process.</p>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"exec-pillars-grid\">\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-eye\"></i></span>\r\n            <h4>My Vision</h4>\r\n          </div>\r\n          <p>To connect talented individuals with the right opportunities and help hospitality businesses grow through quality recruitment, trust and strong professional relationships.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box dark\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-bullseye\"></i></span>\r\n            <h4>My Mission</h4>\r\n          </div>\r\n          <p>To make recruitment a meaningful experience by bringing together the right people and the right organizations.</p>\r\n        </div>\r\n      </div>\r\n    </article>\r\n\r\n    <!-- Profile 2: Sandeep Shetty -->\r\n    <article class=\"exec-profile-block reverse anim-base anim-fade-up\">\r\n      <div class=\"exec-top-grid\">\r\n        <div class=\"exec-intro\">\r\n          <span class=\"eyebrow\">Growth &amp; Operations</span>\r\n          <h3>Sandeep Shetty</h3>\r\n          <div class=\"exec-role\">\r\n            <i class=\"fas fa-briefcase\"></i>\r\n            <span>Sales &amp; Operations Manager | Artha Hospitality</span>\r\n          </div>\r\n          <p>As a Sales &amp; Operations Manager at Artha Hospitality, I am responsible for driving business growth, leading operations, and creating exceptional guest experiences in the hospitality industry.</p>\r\n          <p>I believe that successful hospitality businesses are built on strong leadership, consistent service, and the right people. My focus is on understanding client needs, building lasting business relationships, and ensuring smooth, result-driven operations.</p>\r\n        </div>\r\n\r\n        <div class=\"exec-photo-wrap\">\r\n          <div class=\"exec-photo-frame\">\r\n            <figure class=\"cr-figure\">\r\n              <img src=\"images/about-us-images/sandeep-shetty.jpg\" alt=\"Sandeep Shetty - Sales & Operations Manager at Artha Hospitality\" loading=\"lazy\">\r\n              <figcaption class=\"cr-only\">Sandeep Shetty - Sales &amp; Operations Manager | Artha Hospitality</figcaption>\r\n            </figure>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"exec-pillars-grid cols-3\">\r\n        <div class=\"pillar-box dark\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-chess-knight\"></i></span>\r\n            <h4>My Leadership</h4>\r\n          </div>\r\n          <p>I lead by example — with clarity, accountability, and a people-first approach. My leadership is focused on building high-performing teams, empowering individuals, and creating a culture of ownership, discipline, and excellence.</p>\r\n          <p>I believe a great leader doesn\'t just manage operations; they inspire people to deliver their best every single day.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-eye\"></i></span>\r\n            <h4>My Vision</h4>\r\n          </div>\r\n          <p>To lead Artha Hospitality towards sustainable growth by combining strong sales strategies, operational excellence, and meaningful human connections — and to make it a trusted name in the hospitality industry.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-rocket\"></i></span>\r\n            <h4>My Mission</h4>\r\n          </div>\r\n          <p>To drive sales with integrity, deliver operations with excellence, and create value for clients, guests, and the team — by bringing together the right strategy, the right people, and the right execution.</p>\r\n        </div>\r\n      </div>\r\n    </article>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- WHY CHOOSE US SECTION -->\r\n<section class=\"why-choose-section\" id=\"why-choose-us\">\r\n  <div class=\"wrap\">\r\n    <div class=\"why-choose-head anim-base anim-fade-up\">\r\n      <span class=\"eyebrow\">Why Choose Us?</span>\r\n      <h2>Experience That Turns Ideas Into Successful Operations.</h2>\r\n      <p>“Backed by over <em>15 years</em> of experience in hospitality and hotel operations, our team combines industry insight with proven strategies to deliver solutions that work from day one.”</p>\r\n    </div>\r\n\r\n    <div class=\"why-choose-grid\">\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-100\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-award\"></i></span>\r\n        <h3>Industry Experience</h3>\r\n        <p>More than 15 years of hands-on experience in hospitality and hotel operations.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-200\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-chart-line\"></i></span>\r\n        <h3>Strategic Approach</h3>\r\n        <p>Solutions built around your specific business requirements and operational objectives.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-layer-group\"></i></span>\r\n        <h3>End-to-End Support</h3>\r\n        <p>Comprehensive guidance across planning, development, design, and everyday operations.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-user-check\"></i></span>\r\n        <h3>Guest-Centred Thinking</h3>\r\n        <p>Dedicated focus on elevating guest satisfaction, food quality, and service standards.</p>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 5: CTA -->\r\n<section class=\"cta\">\r\n  <div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n    <span class=\"eyebrow\">Let\'s Work Together</span>\r\n    <h2>Ready to Build or Elevate Your Hospitality Venture?</h2>\r\n    <p>Connect with our leadership and operations team to discuss kitchen planning, recruitment, or end-to-end hospitality consultancy.</p>\r\n    <div class=\"cta-btns\">\r\n      <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-light\">Start a Conversation <span class=\"arrow\">↗</span></a>\r\n      <a href=\"tel:+918951511234\" class=\"btn btn-outline-light\">Call Us Today</a>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- NEW PREMIUM FOOTER -->\r\n<footer id=\"footer\">\r\n  <div class=\"footer-bg-circle\"></div>\r\n  <div class=\"footer-bg-circle-2\"></div>\r\n  \r\n  <div class=\"wrap\">\r\n    <div class=\"footer-grid\">\r\n      \r\n      <!-- Brand Column -->\r\n      <div class=\"footer-brand\">\r\n        <a href=\"index.html\" class=\"footer-logo\" aria-label=\"Artha Hospitality Management\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"images/artha-hospitality-management-footer-logo.png\" alt=\"Artha Hospitality Management Logo\">\r\n            <figcaption class=\"cr-only\">Artha Hospitality Management Logo</figcaption>\r\n          </figure>\r\n        </a>\r\n        \r\n        <div class=\"footer-tagline\">\r\n          <span class=\"white\">Strategic Hospitality.</span>\r\n          <span class=\"gold\">Exceptional Operations.</span>\r\n        </div>\r\n        \r\n        <p class=\"footer-desc\">\r\n          Helping hospitality businesses build stronger foundations, improve operations and create better guest experiences.\r\n        </p>\r\n        \r\n        <div class=\"footer-socials\">\r\n          <a href=\"#\" class=\"social-btn\" aria-label=\"LinkedIn\"><i class=\"fab fa-linkedin-in\"></i></a>\r\n          <a href=\"https://www.instagram.com/arthahospitalitymanagement?rpxt=MTg1bDd3eG9tMmhlMw==\" class=\"social-btn\" aria-label=\"Instagram\" target=\"_blank\" rel=\"noopener noreferrer\"><i class=\"fab fa-instagram\"></i></a>\r\n          <a href=\"https://www.facebook.com/profile.php?id=61596645240447\" class=\"social-btn\" aria-label=\"Facebook\" target=\"_blank\" rel=\"noopener noreferrer\"><i class=\"fab fa-facebook-f\"></i></a>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Links Column -->\r\n      <div class=\"footer-links-section\">\r\n        <div class=\"footer-header\">\r\n          <span class=\"title\">Explore</span>\r\n        </div>\r\n        \r\n        <div class=\"links-list\">\r\n          <a href=\"index.html\" class=\"link-item\">Home <i class=\"fas fa-arrow-right\"></i></a>\r\n          <a href=\"artha-hospitality-about-us.html\" class=\"link-item\">About us <i class=\"fas fa-arrow-right\"></i></a>\r\n          <a href=\"artha-hospitality-management-capital-investment-plan.html\" class=\"link-item\">Services <i class=\"fas fa-arrow-right\"></i></a>\r\n          <a href=\"artha-hospitality-management-industries.html\" class=\"link-item\">Industries<i class=\"fas fa-arrow-right\"></i></a>\r\n          <a href=\"artha-hospitality-clients.html\" class=\"link-item\">Clients <i class=\"fas fa-arrow-right\"></i></a>\r\n          <a href=\"artha-hospitality-contact-us.html\" class=\"link-item\">Contact <i class=\"fas fa-arrow-right\"></i></a>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Quick Links Column -->\r\n      <div class=\"footer-quick-links-section\">\r\n        <div class=\"footer-header\">\r\n          <span class=\"title\">Quick Links</span>\r\n        </div>\r\n\r\n        <div class=\"links-list\">\r\n          <a href=\"artha-hospitality-openings.html#job-opportunities\" class=\"ql-career-item\">\r\n            <span class=\"ql-career-top\">Careers <i class=\"fas fa-arrow-right\" aria-hidden=\"true\"></i></span>\r\n            <span class=\"ql-career-desc\">We Are Hiring — Apply Now</span>\r\n          </a>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Contact Column -->\r\n      <div class=\"footer-contact-section\">\r\n        <div class=\"footer-header\">\r\n          <span class=\"title\">Contact</span>\r\n        </div>\r\n        \r\n        <div class=\"contact-list\">\r\n          <!-- Address -->\r\n          <div class=\"contact-card\">\r\n            <div class=\"contact-icon\"><i class=\"fas fa-map-marker-alt\"></i></div>\r\n            <div class=\"contact-details\">\r\n              <span class=\"contact-label\">Visit Us</span>\r\n              <span class=\"contact-value\"><strong>Artha Hospitality</strong>T-14, 3rd Floor<br>Meridian Guru Plaza<br>Bijai, Mangalore – 575004</span>\r\n            </div>\r\n          </div>\r\n          \r\n          <!-- Phone -->\r\n          <div class=\"contact-card\">\r\n            <div class=\"contact-icon\"><i class=\"fas fa-phone-alt\"></i></div>\r\n            <div class=\"contact-details\">\r\n              <span class=\"contact-label\">Call Us</span>\r\n              <span class=\"contact-value\">\r\n                <a href=\"tel:+918951511234\">+91 89515 11234</a><br>\r\n                <a href=\"tel:+919980447824\">+91 99804 47824</a><br>\r\n                <a href=\"tel:+9108242148889\">+91  0824-214-8889</a>\r\n              </span>\r\n            </div>\r\n          </div>\r\n          \r\n          <!-- Email -->\r\n          <div class=\"contact-card\">\r\n            <div class=\"contact-icon\"><i class=\"fas fa-envelope\"></i></div>\r\n            <div class=\"contact-details\">\r\n              <span class=\"contact-label\">Email Us</span>\r\n              <span class=\"contact-value\">Artha.hm26@gmail.com</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n    \r\n    <!-- Footer Bottom -->\r\n    <div class=\"footer-bottom\">\r\n      <div class=\"fb-left\">\r\n        <span>© 2026 Artha Hospitality Management. All Rights Reserved.</span>\r\n      </div>\r\n      <div class=\"fb-right\">\r\n        <span>Powered by <a href=\"https://bluelinecomputers.com/\" target=\"_blank\" rel=\"noopener noreferrer\">Blueline Computers</a></span>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</footer>\r\n\r\n<script>\r\n/* ============ STICKY HEADER ============ */\r\nconst header = document.getElementById(\'site-header\');\r\nconst onScroll = () => header.classList.toggle(\'scrolled\', window.scrollY > 40);\r\nwindow.addEventListener(\'scroll\', onScroll, {passive:true});\r\nonScroll();\r\n\r\n/* ============ MOBILE MENU ============ */\r\nconst toggle = document.getElementById(\'menuToggle\');\r\nconst mobileMenu = document.getElementById(\'mobileMenu\');\r\nconst setMenu = (open) => {\r\n  toggle.classList.toggle(\'open\', open);\r\n  mobileMenu.classList.toggle(\'open\', open);\r\n  header.classList.toggle(\'menu-open\', open);\r\n  toggle.setAttribute(\'aria-expanded\', open);\r\n  document.body.style.overflow = open ? \'hidden\' : \'\';\r\n};\r\ntoggle.addEventListener(\'click\', () => setMenu(!mobileMenu.classList.contains(\'open\')));\r\n\r\nmobileMenu.querySelectorAll(\'a\').forEach(a => {\r\n  a.addEventListener(\'click\', () => setMenu(false));\r\n});\r\n\r\n/* ============ ROBUST SCROLL REVEAL ============ */\r\nconst animElements = document.querySelectorAll(\'.anim-base\');\r\nif (\'IntersectionObserver\' in window) {\r\n  const io = new IntersectionObserver((entries) => {\r\n    entries.forEach(e => {\r\n      if (e.isIntersecting) {\r\n        e.target.classList.add(\'anim-is-visible\');\r\n        io.unobserve(e.target);\r\n      }\r\n    });\r\n  }, {\r\n    threshold: 0.15,\r\n    rootMargin: \'0px 0px -50px 0px\'\r\n  });\r\n  animElements.forEach(el => io.observe(el));\r\n} else {\r\n  animElements.forEach(el => el.classList.add(\'anim-is-visible\'));\r\n}\r\n</script>\r\n<a href=\"https://wa.me/918951511234?text=Hello%20Artha%20Hospitality%2C%20I%20would%20like%20to%20enquire%20about%20your%20hospitality%20services%20or%20job%20openings.\" class=\"wa-float\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Chat with Artha Hospitality on WhatsApp\">\r\n  <i class=\"fab fa-whatsapp\" aria-hidden=\"true\"></i>\r\n</a>\r\n</body>', 'About', '', 'inherit', 'closed', 'closed', '', '11-revision-v1', '', '', '2026-11-26 08:54:50', '2026-11-26 08:54:50', '', 11, 'http://localhost/artha-hospitality-management/?p=23', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(24, 1, '2026-11-26 08:55:54', '2026-11-26 08:55:54', '\r\n\r\n<!-- NEW 75VH ABOUT US HERO SECTION -->\r\n<section class=\"about-editorial-hero\" id=\"about-top\">\r\n  <div class=\"wrap hero-inner\">\r\n\r\n    <!-- Column 1: Editorial Copy & CTAs -->\r\n    <div class=\"hero-story-col anim-base anim-fade-right\">\r\n      <div class=\"hero-top-tags\">\r\n        <nav class=\"breadcrumb-pill\" aria-label=\"Breadcrumb\">\r\n          <a href=\"index.html\">Home</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <span class=\"current\">About Us</span>\r\n        </nav>\r\n        <span class=\"eyebrow\">Who We Are</span>\r\n      </div>\r\n\r\n      <h1>Shaping the Future of <em>Thoughtful Hospitality</em> From Concept to Table.</h1>\r\n      <p>At Artha Hospitality Management, we partner with visionary restaurateurs, hoteliers, and hospitality entrepreneurs to turn ambitious concepts into resilient, high-performing destinations.</p>\r\n\r\n      <div class=\"hero-cta-group\">\r\n        <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-primary\">Partner With Artha <span class=\"arrow\">↗</span></a>\r\n        <a href=\"index.html#services\" class=\"btn btn-ghost\">Our Capabilities</a>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Column 2: Single Image Sculptural Stage with Theme Shapes -->\r\n    <div class=\"hero-visual-stage anim-base anim-fade-left delay-100\">\r\n      <!-- Shape 1: Concentric Gold Contour Rings -->\r\n      <svg class=\"stage-shape-rings\" viewBox=\"0 0 240 240\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"120\" cy=\"120\" r=\"110\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"82\" opacity=\"0.65\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"54\" opacity=\"0.4\" />\r\n      </svg>\r\n\r\n      <!-- Shape 2: Deep Espresso Architectural Offset Slab -->\r\n      <div class=\"stage-shape-slab\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 3: Gold Offset Wireframe Arch -->\r\n      <div class=\"stage-shape-wireframe\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 4: Gold Dot Matrix Pattern -->\r\n      <div class=\"stage-shape-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 5: Floating Espresso & Gold Medallion Seal -->\r\n      <div class=\"stage-medallion\">\r\n        <span class=\"med-icon\" aria-hidden=\"true\"><i class=\"fas fa-award\"></i></span>\r\n        <div class=\"med-text\">\r\n          <strong>15+ Yrs</strong>\r\n          <span>Hospitality Mastery</span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Main Sculpted Arched Image Panel -->\r\n      <div class=\"hero-arch-panel\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"images/artha-hospitality-about-us-hero.jpg\" alt=\"Hospitality team collaborating in a professional kitchen\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Hospitality team collaborating in a professional kitchen</figcaption>\r\n        </figure>\r\n        <div class=\"arch-caption-bar\">\r\n          <div>\r\n            <span class=\"tag-sub\">Operational Craft</span>\r\n            <span class=\"tag-title\">Ground-Level Expertise</span>\r\n          </div>\r\n          <span class=\"tag-ic\" aria-hidden=\"true\"><i class=\"fas fa-compass\"></i></span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 1: ENGAGING ABOUT ARTHA HOSPITALITY -->\r\n<section class=\"about-artha-section\" id=\"about-artha\">\r\n  <div class=\"wrap\">\r\n    <div class=\"about-artha-grid\">\r\n\r\n      <!-- Story & Philosophy Copy -->\r\n      <div class=\"artha-story-copy anim-base anim-fade-right\">\r\n        <span class=\"eyebrow\">About Us</span>\r\n        <h2>Hospitality Begins With <em>Great Service.</em></h2>\r\n        <p class=\"lead-p\">At Artha, we believe that great hospitality begins with great service. Our mission is to help restaurant owners and hospitality businesses overcome their toughest service challenges, improve guest satisfaction, and grow sustainably.</p>\r\n        <p>With a deep understanding of the industry and a commitment to excellence, we provide tailor-made solutions that create lasting value for our partners.</p>\r\n\r\n        <div class=\"artha-values-list\">\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-hotel\"></i></span>\r\n            <div>\r\n              <h4>Industry Understanding</h4>\r\n              <p>Grounded in more than 15 years of hospitality and hotel operations experience.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-star\"></i></span>\r\n            <div>\r\n              <h4>Tailor-Made Solutions</h4>\r\n              <p>Approaches shaped around your business, your guests, and your operational goals.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-check-circle\"></i></span>\r\n            <div>\r\n              <h4>Commitment to Excellence</h4>\r\n              <p>A consistent focus on quality, service standards, and sustainable long-term growth.</p>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <a href=\"index.html#services\" class=\"btn btn-primary\">Discover What We Do <span class=\"arrow\">↗</span></a>\r\n      </div>\r\n\r\n      <!-- Layered Hospitality Collage -->\r\n      <div class=\"artha-story-visual anim-base anim-fade-left delay-100\">\r\n        <div class=\"artha-vis-tag\">\r\n          <span class=\"vt-ic\" aria-hidden=\"true\"><i class=\"fas fa-compass\"></i></span>\r\n          <div>\r\n            <span>15+ Years Experience</span>\r\n            <strong>Solutions That Work From Day One</strong>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"artha-vis-main\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"images/slide-img-2-lgr.jpg\" alt=\"Elegant hospitality reception and dining space\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Elegant hospitality reception and dining space</figcaption>\r\n          </figure>\r\n        </div>\r\n\r\n        <div class=\"artha-vis-sub\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"images/artha-hospitality-management-about-us-sml-img.jpg\" alt=\"Premium restaurant dining environment\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Premium restaurant dining environment</figcaption>\r\n          </figure>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 2: LEADERSHIP & VISION + CEO SPOTLIGHT (VIHANI ANIL) -->\r\n<section class=\"leader-spotlight bg-sand-light\" id=\"vihani-anil\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n      <h2>The Minds Driving Culinary, People &amp; Operational Excellence.</h2>\r\n      <p>Guided by visionary leadership, seasoned hospitality veterans, kitchen innovators, HR strategists, and operations leaders committed to building resilient, people-first hospitality ventures.</p>\r\n    </div>\r\n\r\n    <div class=\"spotlight-grid\">\r\n\r\n      <!-- Portrait Column -->\r\n      <div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n        <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-frame\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"images/vihani-anil.jpg\" alt=\"Vihani Anil - Future CEO, Artha Hospitality Management\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Vihani Anil - Future CEO | Artha Hospitality Management</figcaption>\r\n          </figure>\r\n        </div>\r\n        <div class=\"portrait-exp-badge\">\r\n          <strong>Future</strong>\r\n          <span>CEO · Artha<br>Hospitality</span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Biography & Vision Column -->\r\n      <div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n        <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n        <h2>Vihani Anil</h2>\r\n        <div class=\"role-pill\">\r\n          <i class=\"fas fa-crown\"></i>\r\n          <span>Future CEO | Artha Hospitality Management</span>\r\n        </div>\r\n\r\n        <div class=\"leader-bio\">\r\n          <p>Vihani Anil is the Future CEO of Artha Hospitality Management, representing the next generation of strategic leadership, brand vision, and client-first hospitality advisory across India.</p>\r\n          <p>Guided by the principle <em>Dream · Plan · Achieve</em>, she brings a forward-looking perspective to modern hospitality consulting—bridging creative concept development with disciplined business planning and sustainable growth.</p>\r\n          <p>Her leadership focus centres on empowering restaurant, café, hotel, cloud kitchen, and resort founders with clarity, structured execution, and long-term operational confidence from day one.</p>\r\n        </div>\r\n\r\n        <div class=\"leader-chips\">\r\n          <span>Future Leadership</span>\r\n          <span>Brand Strategy</span>\r\n          <span>Client Partnerships</span>\r\n          <span>Business Growth</span>\r\n          <span>Hospitality Innovation</span>\r\n          <span>Strategic Planning</span>\r\n        </div>\r\n\r\n        <div class=\"vision-callout\">\r\n          <div class=\"vc-head\">\r\n            <i class=\"fas fa-compass\"></i>\r\n            <span>Future Vision &amp; Leadership</span>\r\n          </div>\r\n          <p>As Future CEO, Vihani champions a culture of excellence, transparency, and purposeful execution—ensuring every hospitality venture partnered with Artha transforms ambitious ideas into thriving, guest-loved destinations.</p>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 3: FOUNDER & DIRECTOR SPOTLIGHT (ANIL KUMAR K) -->\r\n<section class=\"leader-spotlight bg-offwhite\" id=\"anil-kumar\">\r\n  <div class=\"wrap\">\r\n    <div class=\"spotlight-grid reverse\">\r\n\r\n      <!-- Biography & Vision Column -->\r\n      <div class=\"leader-copy anim-base anim-fade-right\">\r\n        <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n        <h2>Anil Kumar K</h2>\r\n        <div class=\"role-pill\">\r\n          <i class=\"fas fa-chess-king\"></i>\r\n          <span>Founder &amp; Director – Artha Hospitality</span>\r\n        </div>\r\n\r\n        <div class=\"leader-bio\">\r\n          <p>Chef Anil Kumar K is the Founder &amp; Director of Artha Hospitality, bringing over 25 years of experience in the hospitality industry.</p>\r\n          <p>With a professional background as a Chef, Anil has extensive hands-on experience in professional kitchens, restaurant operations, kitchen planning, commercial kitchen equipment, food production, and hospitality management.</p>\r\n          <p>His 25 years of industry experience provide him with a deep understanding of the practical requirements of hotels, restaurants, cafés, catering businesses, and commercial food-service operations.</p>\r\n        </div>\r\n\r\n        <div class=\"leader-chips\">\r\n          <span>Professional Kitchens</span>\r\n          <span>Restaurant Operations</span>\r\n          <span>Kitchen Planning</span>\r\n          <span>Commercial Kitchen Equipment</span>\r\n          <span>Food Production</span>\r\n          <span>Hospitality Management</span>\r\n        </div>\r\n\r\n        <div class=\"vision-callout\">\r\n          <div class=\"vc-head\">\r\n            <i class=\"fas fa-compass\"></i>\r\n            <span>Strategic Vision &amp; Leadership</span>\r\n          </div>\r\n          <p>As Founder &amp; Director of Artha Hospitality, Anil leads the company’s business strategy, kitchen solutions, operational planning, client relationships, and overall execution, with a vision to deliver reliable, efficient, and sustainable hospitality solutions.</p>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Portrait Column -->\r\n      <div class=\"leader-portrait-stage anim-base anim-fade-left delay-100\">\r\n        <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-frame\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"images/about-us-images/anil-kumar-k.jpg\" alt=\"Chef Anil Kumar K - Founder & Director of Artha Hospitality\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Chef Anil Kumar K - Founder &amp; Director – Artha Hospitality</figcaption>\r\n          </figure>\r\n        </div>\r\n        <div class=\"portrait-exp-badge\">\r\n          <strong>25+</strong>\r\n          <span>Years in<br>Hospitality</span>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: HR DIRECTOR SPOTLIGHT - SUSHMA AMIN -->\r\n<section class=\"leader-spotlight bg-sand-light\" id=\"sushma-amin\">\r\n  <div class=\"wrap spotlight-grid\">\r\n\r\n    <!-- Portrait Column -->\r\n    <div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n      <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n      <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n      <div class=\"portrait-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"images/about-us-images/sushma-amin.jpg\" alt=\"Sushma Amin - HR Director & Hospitality HR Professional\" loading=\"lazy\">\r\n          <figcaption class=\"cr-only\">Sushma Amin - HR Director &amp; Hospitality HR Professional</figcaption>\r\n        </figure>\r\n      </div>\r\n      <div class=\"portrait-exp-badge\">\r\n        <strong>20+</strong>\r\n        <span>Years in HR &amp;<br>Hospitality</span>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Biography & Vision Column -->\r\n    <div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n      <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n      <h2>Sushma Amin</h2>\r\n      <div class=\"role-pill\">\r\n        <i class=\"fas fa-balance-scale\"></i>\r\n        <span>HR Director &amp; Hospitality HR Professional</span>\r\n      </div>\r\n\r\n      <div class=\"leader-bio\">\r\n        <p>Sushma Amin is a seasoned Human Resources professional with over 20 years of experience in the HR and hospitality industry, bringing extensive expertise in people management, talent acquisition, employee relations, HR operations, and organizational development.</p>\r\n        <p>With a strong academic background in Bachelor of Arts (BA) and Bachelor of Laws (LLB), she combines professional knowledge with practical industry experience to build effective HR practices and people-centric workplaces.</p>\r\n        <p>Throughout her career, she has worked with leading hospitality establishments, gaining valuable experience in managing diverse workforces, developing HR systems, streamlining recruitment processes, and supporting business growth through effective human resource management.</p>\r\n      </div>\r\n\r\n      <div class=\"leader-chips\">\r\n        <span>People Management</span>\r\n        <span>Talent Acquisition</span>\r\n        <span>Employee Relations</span>\r\n        <span>HR Operations</span>\r\n        <span>Organizational Development</span>\r\n        <span>BA &amp; LLB</span>\r\n      </div>\r\n\r\n      <div class=\"vision-callout\">\r\n        <div class=\"vc-head\">\r\n          <i class=\"fas fa-bullseye\"></i>\r\n          <span>Professional Vision</span>\r\n        </div>\r\n        <p>Her professional vision is to connect the right talent with the right opportunities, empower people, strengthen organizations, and contribute to the growth of the hospitality industry through ethical, transparent, and result-oriented HR practices.</p>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: ARTHA EXECUTIVE MANAGEMENT (SNEHA M. & SANDEEP SHETTY) -->\r\n<section class=\"management-section\" id=\"executive-management\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Artha Hospitality Team</span>\r\n      <h2>Driving Recruitment, Sales &amp; Operational Excellence.</h2>\r\n      <p>Connecting talented hospitality professionals with leading organizations and delivering disciplined, guest-focused operational results every day.</p>\r\n    </div>\r\n\r\n    <!-- Profile 1: Sneha M. -->\r\n    <article class=\"exec-profile-block anim-base anim-fade-up\">\r\n      <div class=\"exec-top-grid\">\r\n        <div class=\"exec-photo-wrap\">\r\n          <div class=\"exec-photo-frame\">\r\n            <figure class=\"cr-figure\">\r\n              <img src=\"images/about-us-images/sneha-m.jpg\" alt=\"Sneha M. - HR Executive at Artha Hospitality\" loading=\"lazy\">\r\n              <figcaption class=\"cr-only\">Sneha M. - HR Executive | Artha Hospitality</figcaption>\r\n            </figure>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"exec-intro\">\r\n          <span class=\"eyebrow\">People &amp; Talent</span>\r\n          <h3>Sneha M.</h3>\r\n          <div class=\"exec-role\">\r\n            <i class=\"fas fa-id-badge\"></i>\r\n            <span>HR Executive | Artha Hospitality</span>\r\n          </div>\r\n          <p>As an HR Executive at Artha Hospitality, I am responsible for identifying, attracting and connecting the right talent with the right opportunities in the hospitality industry.</p>\r\n          <p>I believe that successful businesses are built by the right people. My focus is on understanding client requirements, building strong relationships with candidates and ensuring a smooth and effective recruitment process.</p>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"exec-pillars-grid\">\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-eye\"></i></span>\r\n            <h4>My Vision</h4>\r\n          </div>\r\n          <p>To connect talented individuals with the right opportunities and help hospitality businesses grow through quality recruitment, trust and strong professional relationships.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box dark\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-bullseye\"></i></span>\r\n            <h4>My Mission</h4>\r\n          </div>\r\n          <p>To make recruitment a meaningful experience by bringing together the right people and the right organizations.</p>\r\n        </div>\r\n      </div>\r\n    </article>\r\n\r\n    <!-- Profile 2: Sandeep Shetty -->\r\n    <article class=\"exec-profile-block reverse anim-base anim-fade-up\">\r\n      <div class=\"exec-top-grid\">\r\n        <div class=\"exec-intro\">\r\n          <span class=\"eyebrow\">Growth &amp; Operations</span>\r\n          <h3>Sandeep Shetty</h3>\r\n          <div class=\"exec-role\">\r\n            <i class=\"fas fa-briefcase\"></i>\r\n            <span>Sales &amp; Operations Manager | Artha Hospitality</span>\r\n          </div>\r\n          <p>As a Sales &amp; Operations Manager at Artha Hospitality, I am responsible for driving business growth, leading operations, and creating exceptional guest experiences in the hospitality industry.</p>\r\n          <p>I believe that successful hospitality businesses are built on strong leadership, consistent service, and the right people. My focus is on understanding client needs, building lasting business relationships, and ensuring smooth, result-driven operations.</p>\r\n        </div>\r\n\r\n        <div class=\"exec-photo-wrap\">\r\n          <div class=\"exec-photo-frame\">\r\n            <figure class=\"cr-figure\">\r\n              <img src=\"images/about-us-images/sandeep-shetty.jpg\" alt=\"Sandeep Shetty - Sales & Operations Manager at Artha Hospitality\" loading=\"lazy\">\r\n              <figcaption class=\"cr-only\">Sandeep Shetty - Sales &amp; Operations Manager | Artha Hospitality</figcaption>\r\n            </figure>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"exec-pillars-grid cols-3\">\r\n        <div class=\"pillar-box dark\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-chess-knight\"></i></span>\r\n            <h4>My Leadership</h4>\r\n          </div>\r\n          <p>I lead by example — with clarity, accountability, and a people-first approach. My leadership is focused on building high-performing teams, empowering individuals, and creating a culture of ownership, discipline, and excellence.</p>\r\n          <p>I believe a great leader doesn\'t just manage operations; they inspire people to deliver their best every single day.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-eye\"></i></span>\r\n            <h4>My Vision</h4>\r\n          </div>\r\n          <p>To lead Artha Hospitality towards sustainable growth by combining strong sales strategies, operational excellence, and meaningful human connections — and to make it a trusted name in the hospitality industry.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-rocket\"></i></span>\r\n            <h4>My Mission</h4>\r\n          </div>\r\n          <p>To drive sales with integrity, deliver operations with excellence, and create value for clients, guests, and the team — by bringing together the right strategy, the right people, and the right execution.</p>\r\n        </div>\r\n      </div>\r\n    </article>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- WHY CHOOSE US SECTION -->\r\n<section class=\"why-choose-section\" id=\"why-choose-us\">\r\n  <div class=\"wrap\">\r\n    <div class=\"why-choose-head anim-base anim-fade-up\">\r\n      <span class=\"eyebrow\">Why Choose Us?</span>\r\n      <h2>Experience That Turns Ideas Into Successful Operations.</h2>\r\n      <p>“Backed by over <em>15 years</em> of experience in hospitality and hotel operations, our team combines industry insight with proven strategies to deliver solutions that work from day one.”</p>\r\n    </div>\r\n\r\n    <div class=\"why-choose-grid\">\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-100\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-award\"></i></span>\r\n        <h3>Industry Experience</h3>\r\n        <p>More than 15 years of hands-on experience in hospitality and hotel operations.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-200\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-chart-line\"></i></span>\r\n        <h3>Strategic Approach</h3>\r\n        <p>Solutions built around your specific business requirements and operational objectives.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-layer-group\"></i></span>\r\n        <h3>End-to-End Support</h3>\r\n        <p>Comprehensive guidance across planning, development, design, and everyday operations.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-user-check\"></i></span>\r\n        <h3>Guest-Centred Thinking</h3>\r\n        <p>Dedicated focus on elevating guest satisfaction, food quality, and service standards.</p>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 5: CTA -->\r\n<section class=\"cta\">\r\n  <div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n    <span class=\"eyebrow\">Let\'s Work Together</span>\r\n    <h2>Ready to Build or Elevate Your Hospitality Venture?</h2>\r\n    <p>Connect with our leadership and operations team to discuss kitchen planning, recruitment, or end-to-end hospitality consultancy.</p>\r\n    <div class=\"cta-btns\">\r\n      <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-light\">Start a Conversation <span class=\"arrow\">↗</span></a>\r\n      <a href=\"tel:+918951511234\" class=\"btn btn-outline-light\">Call Us Today</a>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- NEW PREMIUM FOOTER -->\r\n<footer id=\"footer\">\r\n  <div class=\"footer-bg-circle\"></div>\r\n  <div class=\"footer-bg-circle-2\"></div>\r\n  \r\n  <div class=\"wrap\">\r\n    <div class=\"footer-grid\">\r\n      \r\n      <!-- Brand Column -->\r\n      <div class=\"footer-brand\">\r\n        <a href=\"index.html\" class=\"footer-logo\" aria-label=\"Artha Hospitality Management\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"images/artha-hospitality-management-footer-logo.png\" alt=\"Artha Hospitality Management Logo\">\r\n            <figcaption class=\"cr-only\">Artha Hospitality Management Logo</figcaption>\r\n          </figure>\r\n        </a>\r\n        \r\n        <div class=\"footer-tagline\">\r\n          <span class=\"white\">Strategic Hospitality.</span>\r\n          <span class=\"gold\">Exceptional Operations.</span>\r\n        </div>\r\n        \r\n        <p class=\"footer-desc\">\r\n          Helping hospitality businesses build stronger foundations, improve operations and create better guest experiences.\r\n        </p>\r\n        \r\n        <div class=\"footer-socials\">\r\n          <a href=\"#\" class=\"social-btn\" aria-label=\"LinkedIn\"><i class=\"fab fa-linkedin-in\"></i></a>\r\n          <a href=\"https://www.instagram.com/arthahospitalitymanagement?rpxt=MTg1bDd3eG9tMmhlMw==\" class=\"social-btn\" aria-label=\"Instagram\" target=\"_blank\" rel=\"noopener noreferrer\"><i class=\"fab fa-instagram\"></i></a>\r\n          <a href=\"https://www.facebook.com/profile.php?id=61596645240447\" class=\"social-btn\" aria-label=\"Facebook\" target=\"_blank\" rel=\"noopener noreferrer\"><i class=\"fab fa-facebook-f\"></i></a>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Links Column -->\r\n      <div class=\"footer-links-section\">\r\n        <div class=\"footer-header\">\r\n          <span class=\"title\">Explore</span>\r\n        </div>\r\n        \r\n        <div class=\"links-list\">\r\n          <a href=\"index.html\" class=\"link-item\">Home <i class=\"fas fa-arrow-right\"></i></a>\r\n          <a href=\"artha-hospitality-about-us.html\" class=\"link-item\">About us <i class=\"fas fa-arrow-right\"></i></a>\r\n          <a href=\"artha-hospitality-management-capital-investment-plan.html\" class=\"link-item\">Services <i class=\"fas fa-arrow-right\"></i></a>\r\n          <a href=\"artha-hospitality-management-industries.html\" class=\"link-item\">Industries<i class=\"fas fa-arrow-right\"></i></a>\r\n          <a href=\"artha-hospitality-clients.html\" class=\"link-item\">Clients <i class=\"fas fa-arrow-right\"></i></a>\r\n          <a href=\"artha-hospitality-contact-us.html\" class=\"link-item\">Contact <i class=\"fas fa-arrow-right\"></i></a>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Quick Links Column -->\r\n      <div class=\"footer-quick-links-section\">\r\n        <div class=\"footer-header\">\r\n          <span class=\"title\">Quick Links</span>\r\n        </div>\r\n\r\n        <div class=\"links-list\">\r\n          <a href=\"artha-hospitality-openings.html#job-opportunities\" class=\"ql-career-item\">\r\n            <span class=\"ql-career-top\">Careers <i class=\"fas fa-arrow-right\" aria-hidden=\"true\"></i></span>\r\n            <span class=\"ql-career-desc\">We Are Hiring — Apply Now</span>\r\n          </a>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Contact Column -->\r\n      <div class=\"footer-contact-section\">\r\n        <div class=\"footer-header\">\r\n          <span class=\"title\">Contact</span>\r\n        </div>\r\n        \r\n        <div class=\"contact-list\">\r\n          <!-- Address -->\r\n          <div class=\"contact-card\">\r\n            <div class=\"contact-icon\"><i class=\"fas fa-map-marker-alt\"></i></div>\r\n            <div class=\"contact-details\">\r\n              <span class=\"contact-label\">Visit Us</span>\r\n              <span class=\"contact-value\"><strong>Artha Hospitality</strong>T-14, 3rd Floor<br>Meridian Guru Plaza<br>Bijai, Mangalore – 575004</span>\r\n            </div>\r\n          </div>\r\n          \r\n          <!-- Phone -->\r\n          <div class=\"contact-card\">\r\n            <div class=\"contact-icon\"><i class=\"fas fa-phone-alt\"></i></div>\r\n            <div class=\"contact-details\">\r\n              <span class=\"contact-label\">Call Us</span>\r\n              <span class=\"contact-value\">\r\n                <a href=\"tel:+918951511234\">+91 89515 11234</a><br>\r\n                <a href=\"tel:+919980447824\">+91 99804 47824</a><br>\r\n                <a href=\"tel:+9108242148889\">+91  0824-214-8889</a>\r\n              </span>\r\n            </div>\r\n          </div>\r\n          \r\n          <!-- Email -->\r\n          <div class=\"contact-card\">\r\n            <div class=\"contact-icon\"><i class=\"fas fa-envelope\"></i></div>\r\n            <div class=\"contact-details\">\r\n              <span class=\"contact-label\">Email Us</span>\r\n              <span class=\"contact-value\">Artha.hm26@gmail.com</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n    \r\n    <!-- Footer Bottom -->\r\n    <div class=\"footer-bottom\">\r\n      <div class=\"fb-left\">\r\n        <span>© 2026 Artha Hospitality Management. All Rights Reserved.</span>\r\n      </div>\r\n      <div class=\"fb-right\">\r\n        <span>Powered by <a href=\"https://bluelinecomputers.com/\" target=\"_blank\" rel=\"noopener noreferrer\">Blueline Computers</a></span>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</footer>\r\n\r\n<script>\r\n/* ============ STICKY HEADER ============ */\r\nconst header = document.getElementById(\'site-header\');\r\nconst onScroll = () => header.classList.toggle(\'scrolled\', window.scrollY > 40);\r\nwindow.addEventListener(\'scroll\', onScroll, {passive:true});\r\nonScroll();\r\n\r\n/* ============ MOBILE MENU ============ */\r\nconst toggle = document.getElementById(\'menuToggle\');\r\nconst mobileMenu = document.getElementById(\'mobileMenu\');\r\nconst setMenu = (open) => {\r\n  toggle.classList.toggle(\'open\', open);\r\n  mobileMenu.classList.toggle(\'open\', open);\r\n  header.classList.toggle(\'menu-open\', open);\r\n  toggle.setAttribute(\'aria-expanded\', open);\r\n  document.body.style.overflow = open ? \'hidden\' : \'\';\r\n};\r\ntoggle.addEventListener(\'click\', () => setMenu(!mobileMenu.classList.contains(\'open\')));\r\n\r\nmobileMenu.querySelectorAll(\'a\').forEach(a => {\r\n  a.addEventListener(\'click\', () => setMenu(false));\r\n});\r\n\r\n/* ============ ROBUST SCROLL REVEAL ============ */\r\nconst animElements = document.querySelectorAll(\'.anim-base\');\r\nif (\'IntersectionObserver\' in window) {\r\n  const io = new IntersectionObserver((entries) => {\r\n    entries.forEach(e => {\r\n      if (e.isIntersecting) {\r\n        e.target.classList.add(\'anim-is-visible\');\r\n        io.unobserve(e.target);\r\n      }\r\n    });\r\n  }, {\r\n    threshold: 0.15,\r\n    rootMargin: \'0px 0px -50px 0px\'\r\n  });\r\n  animElements.forEach(el => io.observe(el));\r\n} else {\r\n  animElements.forEach(el => el.classList.add(\'anim-is-visible\'));\r\n}\r\n</script>\r\n<a href=\"https://wa.me/918951511234?text=Hello%20Artha%20Hospitality%2C%20I%20would%20like%20to%20enquire%20about%20your%20hospitality%20services%20or%20job%20openings.\" class=\"wa-float\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Chat with Artha Hospitality on WhatsApp\">\r\n  <i class=\"fab fa-whatsapp\" aria-hidden=\"true\"></i>\r\n</a>\r\n', 'About', '', 'inherit', 'closed', 'closed', '', '11-revision-v1', '', '', '2026-11-26 08:55:54', '2026-11-26 08:55:54', '', 11, 'http://localhost/artha-hospitality-management/?p=24', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(25, 1, '2026-11-26 08:56:39', '2026-11-26 08:56:39', '<!-- NEW 75VH ABOUT US HERO SECTION -->\r\n<section class=\"about-editorial-hero\" id=\"about-top\">\r\n  <div class=\"wrap hero-inner\">\r\n\r\n    <!-- Column 1: Editorial Copy & CTAs -->\r\n    <div class=\"hero-story-col anim-base anim-fade-right\">\r\n      <div class=\"hero-top-tags\">\r\n        <nav class=\"breadcrumb-pill\" aria-label=\"Breadcrumb\">\r\n          <a href=\"index.html\">Home</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <span class=\"current\">About Us</span>\r\n        </nav>\r\n        <span class=\"eyebrow\">Who We Are</span>\r\n      </div>\r\n\r\n      <h1>Shaping the Future of <em>Thoughtful Hospitality</em> From Concept to Table.</h1>\r\n      <p>At Artha Hospitality Management, we partner with visionary restaurateurs, hoteliers, and hospitality entrepreneurs to turn ambitious concepts into resilient, high-performing destinations.</p>\r\n\r\n      <div class=\"hero-cta-group\">\r\n        <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-primary\">Partner With Artha <span class=\"arrow\">↗</span></a>\r\n        <a href=\"index.html#services\" class=\"btn btn-ghost\">Our Capabilities</a>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Column 2: Single Image Sculptural Stage with Theme Shapes -->\r\n    <div class=\"hero-visual-stage anim-base anim-fade-left delay-100\">\r\n      <!-- Shape 1: Concentric Gold Contour Rings -->\r\n      <svg class=\"stage-shape-rings\" viewBox=\"0 0 240 240\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"120\" cy=\"120\" r=\"110\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"82\" opacity=\"0.65\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"54\" opacity=\"0.4\" />\r\n      </svg>\r\n\r\n      <!-- Shape 2: Deep Espresso Architectural Offset Slab -->\r\n      <div class=\"stage-shape-slab\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 3: Gold Offset Wireframe Arch -->\r\n      <div class=\"stage-shape-wireframe\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 4: Gold Dot Matrix Pattern -->\r\n      <div class=\"stage-shape-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 5: Floating Espresso & Gold Medallion Seal -->\r\n      <div class=\"stage-medallion\">\r\n        <span class=\"med-icon\" aria-hidden=\"true\"><i class=\"fas fa-award\"></i></span>\r\n        <div class=\"med-text\">\r\n          <strong>15+ Yrs</strong>\r\n          <span>Hospitality Mastery</span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Main Sculpted Arched Image Panel -->\r\n      <div class=\"hero-arch-panel\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"images/artha-hospitality-about-us-hero.jpg\" alt=\"Hospitality team collaborating in a professional kitchen\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Hospitality team collaborating in a professional kitchen</figcaption>\r\n        </figure>\r\n        <div class=\"arch-caption-bar\">\r\n          <div>\r\n            <span class=\"tag-sub\">Operational Craft</span>\r\n            <span class=\"tag-title\">Ground-Level Expertise</span>\r\n          </div>\r\n          <span class=\"tag-ic\" aria-hidden=\"true\"><i class=\"fas fa-compass\"></i></span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 1: ENGAGING ABOUT ARTHA HOSPITALITY -->\r\n<section class=\"about-artha-section\" id=\"about-artha\">\r\n  <div class=\"wrap\">\r\n    <div class=\"about-artha-grid\">\r\n\r\n      <!-- Story & Philosophy Copy -->\r\n      <div class=\"artha-story-copy anim-base anim-fade-right\">\r\n        <span class=\"eyebrow\">About Us</span>\r\n        <h2>Hospitality Begins With <em>Great Service.</em></h2>\r\n        <p class=\"lead-p\">At Artha, we believe that great hospitality begins with great service. Our mission is to help restaurant owners and hospitality businesses overcome their toughest service challenges, improve guest satisfaction, and grow sustainably.</p>\r\n        <p>With a deep understanding of the industry and a commitment to excellence, we provide tailor-made solutions that create lasting value for our partners.</p>\r\n\r\n        <div class=\"artha-values-list\">\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-hotel\"></i></span>\r\n            <div>\r\n              <h4>Industry Understanding</h4>\r\n              <p>Grounded in more than 15 years of hospitality and hotel operations experience.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-star\"></i></span>\r\n            <div>\r\n              <h4>Tailor-Made Solutions</h4>\r\n              <p>Approaches shaped around your business, your guests, and your operational goals.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-check-circle\"></i></span>\r\n            <div>\r\n              <h4>Commitment to Excellence</h4>\r\n              <p>A consistent focus on quality, service standards, and sustainable long-term growth.</p>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <a href=\"index.html#services\" class=\"btn btn-primary\">Discover What We Do <span class=\"arrow\">↗</span></a>\r\n      </div>\r\n\r\n      <!-- Layered Hospitality Collage -->\r\n      <div class=\"artha-story-visual anim-base anim-fade-left delay-100\">\r\n        <div class=\"artha-vis-tag\">\r\n          <span class=\"vt-ic\" aria-hidden=\"true\"><i class=\"fas fa-compass\"></i></span>\r\n          <div>\r\n            <span>15+ Years Experience</span>\r\n            <strong>Solutions That Work From Day One</strong>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"artha-vis-main\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"images/slide-img-2-lgr.jpg\" alt=\"Elegant hospitality reception and dining space\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Elegant hospitality reception and dining space</figcaption>\r\n          </figure>\r\n        </div>\r\n\r\n        <div class=\"artha-vis-sub\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"images/artha-hospitality-management-about-us-sml-img.jpg\" alt=\"Premium restaurant dining environment\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Premium restaurant dining environment</figcaption>\r\n          </figure>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 2: LEADERSHIP & VISION + CEO SPOTLIGHT (VIHANI ANIL) -->\r\n<section class=\"leader-spotlight bg-sand-light\" id=\"vihani-anil\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n      <h2>The Minds Driving Culinary, People &amp; Operational Excellence.</h2>\r\n      <p>Guided by visionary leadership, seasoned hospitality veterans, kitchen innovators, HR strategists, and operations leaders committed to building resilient, people-first hospitality ventures.</p>\r\n    </div>\r\n\r\n    <div class=\"spotlight-grid\">\r\n\r\n      <!-- Portrait Column -->\r\n      <div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n        <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-frame\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"images/vihani-anil.jpg\" alt=\"Vihani Anil - Future CEO, Artha Hospitality Management\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Vihani Anil - Future CEO | Artha Hospitality Management</figcaption>\r\n          </figure>\r\n        </div>\r\n        <div class=\"portrait-exp-badge\">\r\n          <strong>Future</strong>\r\n          <span>CEO · Artha<br>Hospitality</span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Biography & Vision Column -->\r\n      <div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n        <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n        <h2>Vihani Anil</h2>\r\n        <div class=\"role-pill\">\r\n          <i class=\"fas fa-crown\"></i>\r\n          <span>Future CEO | Artha Hospitality Management</span>\r\n        </div>\r\n\r\n        <div class=\"leader-bio\">\r\n          <p>Vihani Anil is the Future CEO of Artha Hospitality Management, representing the next generation of strategic leadership, brand vision, and client-first hospitality advisory across India.</p>\r\n          <p>Guided by the principle <em>Dream · Plan · Achieve</em>, she brings a forward-looking perspective to modern hospitality consulting—bridging creative concept development with disciplined business planning and sustainable growth.</p>\r\n          <p>Her leadership focus centres on empowering restaurant, café, hotel, cloud kitchen, and resort founders with clarity, structured execution, and long-term operational confidence from day one.</p>\r\n        </div>\r\n\r\n        <div class=\"leader-chips\">\r\n          <span>Future Leadership</span>\r\n          <span>Brand Strategy</span>\r\n          <span>Client Partnerships</span>\r\n          <span>Business Growth</span>\r\n          <span>Hospitality Innovation</span>\r\n          <span>Strategic Planning</span>\r\n        </div>\r\n\r\n        <div class=\"vision-callout\">\r\n          <div class=\"vc-head\">\r\n            <i class=\"fas fa-compass\"></i>\r\n            <span>Future Vision &amp; Leadership</span>\r\n          </div>\r\n          <p>As Future CEO, Vihani champions a culture of excellence, transparency, and purposeful execution—ensuring every hospitality venture partnered with Artha transforms ambitious ideas into thriving, guest-loved destinations.</p>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 3: FOUNDER & DIRECTOR SPOTLIGHT (ANIL KUMAR K) -->\r\n<section class=\"leader-spotlight bg-offwhite\" id=\"anil-kumar\">\r\n  <div class=\"wrap\">\r\n    <div class=\"spotlight-grid reverse\">\r\n\r\n      <!-- Biography & Vision Column -->\r\n      <div class=\"leader-copy anim-base anim-fade-right\">\r\n        <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n        <h2>Anil Kumar K</h2>\r\n        <div class=\"role-pill\">\r\n          <i class=\"fas fa-chess-king\"></i>\r\n          <span>Founder &amp; Director – Artha Hospitality</span>\r\n        </div>\r\n\r\n        <div class=\"leader-bio\">\r\n          <p>Chef Anil Kumar K is the Founder &amp; Director of Artha Hospitality, bringing over 25 years of experience in the hospitality industry.</p>\r\n          <p>With a professional background as a Chef, Anil has extensive hands-on experience in professional kitchens, restaurant operations, kitchen planning, commercial kitchen equipment, food production, and hospitality management.</p>\r\n          <p>His 25 years of industry experience provide him with a deep understanding of the practical requirements of hotels, restaurants, cafés, catering businesses, and commercial food-service operations.</p>\r\n        </div>\r\n\r\n        <div class=\"leader-chips\">\r\n          <span>Professional Kitchens</span>\r\n          <span>Restaurant Operations</span>\r\n          <span>Kitchen Planning</span>\r\n          <span>Commercial Kitchen Equipment</span>\r\n          <span>Food Production</span>\r\n          <span>Hospitality Management</span>\r\n        </div>\r\n\r\n        <div class=\"vision-callout\">\r\n          <div class=\"vc-head\">\r\n            <i class=\"fas fa-compass\"></i>\r\n            <span>Strategic Vision &amp; Leadership</span>\r\n          </div>\r\n          <p>As Founder &amp; Director of Artha Hospitality, Anil leads the company’s business strategy, kitchen solutions, operational planning, client relationships, and overall execution, with a vision to deliver reliable, efficient, and sustainable hospitality solutions.</p>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Portrait Column -->\r\n      <div class=\"leader-portrait-stage anim-base anim-fade-left delay-100\">\r\n        <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-frame\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"images/about-us-images/anil-kumar-k.jpg\" alt=\"Chef Anil Kumar K - Founder & Director of Artha Hospitality\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Chef Anil Kumar K - Founder &amp; Director – Artha Hospitality</figcaption>\r\n          </figure>\r\n        </div>\r\n        <div class=\"portrait-exp-badge\">\r\n          <strong>25+</strong>\r\n          <span>Years in<br>Hospitality</span>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: HR DIRECTOR SPOTLIGHT - SUSHMA AMIN -->\r\n<section class=\"leader-spotlight bg-sand-light\" id=\"sushma-amin\">\r\n  <div class=\"wrap spotlight-grid\">\r\n\r\n    <!-- Portrait Column -->\r\n    <div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n      <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n      <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n      <div class=\"portrait-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"images/about-us-images/sushma-amin.jpg\" alt=\"Sushma Amin - HR Director & Hospitality HR Professional\" loading=\"lazy\">\r\n          <figcaption class=\"cr-only\">Sushma Amin - HR Director &amp; Hospitality HR Professional</figcaption>\r\n        </figure>\r\n      </div>\r\n      <div class=\"portrait-exp-badge\">\r\n        <strong>20+</strong>\r\n        <span>Years in HR &amp;<br>Hospitality</span>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Biography & Vision Column -->\r\n    <div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n      <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n      <h2>Sushma Amin</h2>\r\n      <div class=\"role-pill\">\r\n        <i class=\"fas fa-balance-scale\"></i>\r\n        <span>HR Director &amp; Hospitality HR Professional</span>\r\n      </div>\r\n\r\n      <div class=\"leader-bio\">\r\n        <p>Sushma Amin is a seasoned Human Resources professional with over 20 years of experience in the HR and hospitality industry, bringing extensive expertise in people management, talent acquisition, employee relations, HR operations, and organizational development.</p>\r\n        <p>With a strong academic background in Bachelor of Arts (BA) and Bachelor of Laws (LLB), she combines professional knowledge with practical industry experience to build effective HR practices and people-centric workplaces.</p>\r\n        <p>Throughout her career, she has worked with leading hospitality establishments, gaining valuable experience in managing diverse workforces, developing HR systems, streamlining recruitment processes, and supporting business growth through effective human resource management.</p>\r\n      </div>\r\n\r\n      <div class=\"leader-chips\">\r\n        <span>People Management</span>\r\n        <span>Talent Acquisition</span>\r\n        <span>Employee Relations</span>\r\n        <span>HR Operations</span>\r\n        <span>Organizational Development</span>\r\n        <span>BA &amp; LLB</span>\r\n      </div>\r\n\r\n      <div class=\"vision-callout\">\r\n        <div class=\"vc-head\">\r\n          <i class=\"fas fa-bullseye\"></i>\r\n          <span>Professional Vision</span>\r\n        </div>\r\n        <p>Her professional vision is to connect the right talent with the right opportunities, empower people, strengthen organizations, and contribute to the growth of the hospitality industry through ethical, transparent, and result-oriented HR practices.</p>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: ARTHA EXECUTIVE MANAGEMENT (SNEHA M. & SANDEEP SHETTY) -->\r\n<section class=\"management-section\" id=\"executive-management\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Artha Hospitality Team</span>\r\n      <h2>Driving Recruitment, Sales &amp; Operational Excellence.</h2>\r\n      <p>Connecting talented hospitality professionals with leading organizations and delivering disciplined, guest-focused operational results every day.</p>\r\n    </div>\r\n\r\n    <!-- Profile 1: Sneha M. -->\r\n    <article class=\"exec-profile-block anim-base anim-fade-up\">\r\n      <div class=\"exec-top-grid\">\r\n        <div class=\"exec-photo-wrap\">\r\n          <div class=\"exec-photo-frame\">\r\n            <figure class=\"cr-figure\">\r\n              <img src=\"images/about-us-images/sneha-m.jpg\" alt=\"Sneha M. - HR Executive at Artha Hospitality\" loading=\"lazy\">\r\n              <figcaption class=\"cr-only\">Sneha M. - HR Executive | Artha Hospitality</figcaption>\r\n            </figure>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"exec-intro\">\r\n          <span class=\"eyebrow\">People &amp; Talent</span>\r\n          <h3>Sneha M.</h3>\r\n          <div class=\"exec-role\">\r\n            <i class=\"fas fa-id-badge\"></i>\r\n            <span>HR Executive | Artha Hospitality</span>\r\n          </div>\r\n          <p>As an HR Executive at Artha Hospitality, I am responsible for identifying, attracting and connecting the right talent with the right opportunities in the hospitality industry.</p>\r\n          <p>I believe that successful businesses are built by the right people. My focus is on understanding client requirements, building strong relationships with candidates and ensuring a smooth and effective recruitment process.</p>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"exec-pillars-grid\">\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-eye\"></i></span>\r\n            <h4>My Vision</h4>\r\n          </div>\r\n          <p>To connect talented individuals with the right opportunities and help hospitality businesses grow through quality recruitment, trust and strong professional relationships.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box dark\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-bullseye\"></i></span>\r\n            <h4>My Mission</h4>\r\n          </div>\r\n          <p>To make recruitment a meaningful experience by bringing together the right people and the right organizations.</p>\r\n        </div>\r\n      </div>\r\n    </article>\r\n\r\n    <!-- Profile 2: Sandeep Shetty -->\r\n    <article class=\"exec-profile-block reverse anim-base anim-fade-up\">\r\n      <div class=\"exec-top-grid\">\r\n        <div class=\"exec-intro\">\r\n          <span class=\"eyebrow\">Growth &amp; Operations</span>\r\n          <h3>Sandeep Shetty</h3>\r\n          <div class=\"exec-role\">\r\n            <i class=\"fas fa-briefcase\"></i>\r\n            <span>Sales &amp; Operations Manager | Artha Hospitality</span>\r\n          </div>\r\n          <p>As a Sales &amp; Operations Manager at Artha Hospitality, I am responsible for driving business growth, leading operations, and creating exceptional guest experiences in the hospitality industry.</p>\r\n          <p>I believe that successful hospitality businesses are built on strong leadership, consistent service, and the right people. My focus is on understanding client needs, building lasting business relationships, and ensuring smooth, result-driven operations.</p>\r\n        </div>\r\n\r\n        <div class=\"exec-photo-wrap\">\r\n          <div class=\"exec-photo-frame\">\r\n            <figure class=\"cr-figure\">\r\n              <img src=\"images/about-us-images/sandeep-shetty.jpg\" alt=\"Sandeep Shetty - Sales & Operations Manager at Artha Hospitality\" loading=\"lazy\">\r\n              <figcaption class=\"cr-only\">Sandeep Shetty - Sales &amp; Operations Manager | Artha Hospitality</figcaption>\r\n            </figure>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"exec-pillars-grid cols-3\">\r\n        <div class=\"pillar-box dark\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-chess-knight\"></i></span>\r\n            <h4>My Leadership</h4>\r\n          </div>\r\n          <p>I lead by example — with clarity, accountability, and a people-first approach. My leadership is focused on building high-performing teams, empowering individuals, and creating a culture of ownership, discipline, and excellence.</p>\r\n          <p>I believe a great leader doesn\'t just manage operations; they inspire people to deliver their best every single day.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-eye\"></i></span>\r\n            <h4>My Vision</h4>\r\n          </div>\r\n          <p>To lead Artha Hospitality towards sustainable growth by combining strong sales strategies, operational excellence, and meaningful human connections — and to make it a trusted name in the hospitality industry.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-rocket\"></i></span>\r\n            <h4>My Mission</h4>\r\n          </div>\r\n          <p>To drive sales with integrity, deliver operations with excellence, and create value for clients, guests, and the team — by bringing together the right strategy, the right people, and the right execution.</p>\r\n        </div>\r\n      </div>\r\n    </article>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- WHY CHOOSE US SECTION -->\r\n<section class=\"why-choose-section\" id=\"why-choose-us\">\r\n  <div class=\"wrap\">\r\n    <div class=\"why-choose-head anim-base anim-fade-up\">\r\n      <span class=\"eyebrow\">Why Choose Us?</span>\r\n      <h2>Experience That Turns Ideas Into Successful Operations.</h2>\r\n      <p>“Backed by over <em>15 years</em> of experience in hospitality and hotel operations, our team combines industry insight with proven strategies to deliver solutions that work from day one.”</p>\r\n    </div>\r\n\r\n    <div class=\"why-choose-grid\">\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-100\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-award\"></i></span>\r\n        <h3>Industry Experience</h3>\r\n        <p>More than 15 years of hands-on experience in hospitality and hotel operations.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-200\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-chart-line\"></i></span>\r\n        <h3>Strategic Approach</h3>\r\n        <p>Solutions built around your specific business requirements and operational objectives.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-layer-group\"></i></span>\r\n        <h3>End-to-End Support</h3>\r\n        <p>Comprehensive guidance across planning, development, design, and everyday operations.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-user-check\"></i></span>\r\n        <h3>Guest-Centred Thinking</h3>\r\n        <p>Dedicated focus on elevating guest satisfaction, food quality, and service standards.</p>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 5: CTA -->\r\n<section class=\"cta\">\r\n  <div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n    <span class=\"eyebrow\">Let\'s Work Together</span>\r\n    <h2>Ready to Build or Elevate Your Hospitality Venture?</h2>\r\n    <p>Connect with our leadership and operations team to discuss kitchen planning, recruitment, or end-to-end hospitality consultancy.</p>\r\n    <div class=\"cta-btns\">\r\n      <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-light\">Start a Conversation <span class=\"arrow\">↗</span></a>\r\n      <a href=\"tel:+918951511234\" class=\"btn btn-outline-light\">Call Us Today</a>\r\n    </div>\r\n  </div>\r\n</section>', 'About', '', 'inherit', 'closed', 'closed', '', '11-revision-v1', '', '', '2026-11-26 08:56:39', '2026-11-26 08:56:39', '', 11, 'http://localhost/artha-hospitality-management/?p=25', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(26, 1, '2026-11-26 09:02:29', '2026-11-26 09:02:29', '<!-- NEW 75VH ABOUT US HERO SECTION -->\r\n<section class=\"about-editorial-hero\" id=\"about-top\">\r\n  <div class=\"wrap hero-inner\">\r\n\r\n    <!-- Column 1: Editorial Copy & CTAs -->\r\n    <div class=\"hero-story-col anim-base anim-fade-right\">\r\n      <div class=\"hero-top-tags\">\r\n        <nav class=\"breadcrumb-pill\" aria-label=\"Breadcrumb\">\r\n          <a href=\"index.html\">Home</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <span class=\"current\">About Us</span>\r\n        </nav>\r\n        <span class=\"eyebrow\">Who We Are</span>\r\n      </div>\r\n\r\n      <h1>Shaping the Future of <em>Thoughtful Hospitality</em> From Concept to Table.</h1>\r\n      <p>At Artha Hospitality Management, we partner with visionary restaurateurs, hoteliers, and hospitality entrepreneurs to turn ambitious concepts into resilient, high-performing destinations.</p>\r\n\r\n      <div class=\"hero-cta-group\">\r\n        <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-primary\">Partner With Artha <span class=\"arrow\">↗</span></a>\r\n        <a href=\"index.html#services\" class=\"btn btn-ghost\">Our Capabilities</a>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Column 2: Single Image Sculptural Stage with Theme Shapes -->\r\n    <div class=\"hero-visual-stage anim-base anim-fade-left delay-100\">\r\n      <!-- Shape 1: Concentric Gold Contour Rings -->\r\n      <svg class=\"stage-shape-rings\" viewBox=\"0 0 240 240\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"120\" cy=\"120\" r=\"110\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"82\" opacity=\"0.65\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"54\" opacity=\"0.4\" />\r\n      </svg>\r\n\r\n      <!-- Shape 2: Deep Espresso Architectural Offset Slab -->\r\n      <div class=\"stage-shape-slab\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 3: Gold Offset Wireframe Arch -->\r\n      <div class=\"stage-shape-wireframe\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 4: Gold Dot Matrix Pattern -->\r\n      <div class=\"stage-shape-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 5: Floating Espresso & Gold Medallion Seal -->\r\n      <div class=\"stage-medallion\">\r\n        <span class=\"med-icon\" aria-hidden=\"true\"><i class=\"fas fa-award\"></i></span>\r\n        <div class=\"med-text\">\r\n          <strong>15+ Yrs</strong>\r\n          <span>Hospitality Mastery</span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Main Sculpted Arched Image Panel -->\r\n      <div class=\"hero-arch-panel\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-about-us-hero.jpg\" alt=\"Hospitality team collaborating in a professional kitchen\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Hospitality team collaborating in a professional kitchen</figcaption>\r\n        </figure>\r\n        <div class=\"arch-caption-bar\">\r\n          <div>\r\n            <span class=\"tag-sub\">Operational Craft</span>\r\n            <span class=\"tag-title\">Ground-Level Expertise</span>\r\n          </div>\r\n          <span class=\"tag-ic\" aria-hidden=\"true\"><i class=\"fas fa-compass\"></i></span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 1: ENGAGING ABOUT ARTHA HOSPITALITY -->\r\n<section class=\"about-artha-section\" id=\"about-artha\">\r\n  <div class=\"wrap\">\r\n    <div class=\"about-artha-grid\">\r\n\r\n      <!-- Story & Philosophy Copy -->\r\n      <div class=\"artha-story-copy anim-base anim-fade-right\">\r\n        <span class=\"eyebrow\">About Us</span>\r\n        <h2>Hospitality Begins With <em>Great Service.</em></h2>\r\n        <p class=\"lead-p\">At Artha, we believe that great hospitality begins with great service. Our mission is to help restaurant owners and hospitality businesses overcome their toughest service challenges, improve guest satisfaction, and grow sustainably.</p>\r\n        <p>With a deep understanding of the industry and a commitment to excellence, we provide tailor-made solutions that create lasting value for our partners.</p>\r\n\r\n        <div class=\"artha-values-list\">\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-hotel\"></i></span>\r\n            <div>\r\n              <h4>Industry Understanding</h4>\r\n              <p>Grounded in more than 15 years of hospitality and hotel operations experience.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-star\"></i></span>\r\n            <div>\r\n              <h4>Tailor-Made Solutions</h4>\r\n              <p>Approaches shaped around your business, your guests, and your operational goals.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-check-circle\"></i></span>\r\n            <div>\r\n              <h4>Commitment to Excellence</h4>\r\n              <p>A consistent focus on quality, service standards, and sustainable long-term growth.</p>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <a href=\"index.html#services\" class=\"btn btn-primary\">Discover What We Do <span class=\"arrow\">↗</span></a>\r\n      </div>\r\n\r\n      <!-- Layered Hospitality Collage -->\r\n      <div class=\"artha-story-visual anim-base anim-fade-left delay-100\">\r\n        <div class=\"artha-vis-tag\">\r\n          <span class=\"vt-ic\" aria-hidden=\"true\"><i class=\"fas fa-compass\"></i></span>\r\n          <div>\r\n            <span>15+ Years Experience</span>\r\n            <strong>Solutions That Work From Day One</strong>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"artha-vis-main\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/slide-img-2-lgr.jpg\" alt=\"Elegant hospitality reception and dining space\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Elegant hospitality reception and dining space</figcaption>\r\n          </figure>\r\n        </div>\r\n\r\n        <div class=\"artha-vis-sub\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-management-about-us-sml-img.jpg\" alt=\"Premium restaurant dining environment\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Premium restaurant dining environment</figcaption>\r\n          </figure>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 2: LEADERSHIP & VISION + CEO SPOTLIGHT (VIHANI ANIL) -->\r\n<section class=\"leader-spotlight bg-sand-light\" id=\"vihani-anil\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n      <h2>The Minds Driving Culinary, People &amp; Operational Excellence.</h2>\r\n      <p>Guided by visionary leadership, seasoned hospitality veterans, kitchen innovators, HR strategists, and operations leaders committed to building resilient, people-first hospitality ventures.</p>\r\n    </div>\r\n\r\n    <div class=\"spotlight-grid\">\r\n\r\n      <!-- Portrait Column -->\r\n      <div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n        <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-frame\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/vihani-anil.jpg\" alt=\"Vihani Anil - Future CEO, Artha Hospitality Management\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Vihani Anil - Future CEO | Artha Hospitality Management</figcaption>\r\n          </figure>\r\n        </div>\r\n        <div class=\"portrait-exp-badge\">\r\n          <strong>Future</strong>\r\n          <span>CEO · Artha<br>Hospitality</span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Biography & Vision Column -->\r\n      <div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n        <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n        <h2>Vihani Anil</h2>\r\n        <div class=\"role-pill\">\r\n          <i class=\"fas fa-crown\"></i>\r\n          <span>Future CEO | Artha Hospitality Management</span>\r\n        </div>\r\n\r\n        <div class=\"leader-bio\">\r\n          <p>Vihani Anil is the Future CEO of Artha Hospitality Management, representing the next generation of strategic leadership, brand vision, and client-first hospitality advisory across India.</p>\r\n          <p>Guided by the principle <em>Dream · Plan · Achieve</em>, she brings a forward-looking perspective to modern hospitality consulting—bridging creative concept development with disciplined business planning and sustainable growth.</p>\r\n          <p>Her leadership focus centres on empowering restaurant, café, hotel, cloud kitchen, and resort founders with clarity, structured execution, and long-term operational confidence from day one.</p>\r\n        </div>\r\n\r\n        <div class=\"leader-chips\">\r\n          <span>Future Leadership</span>\r\n          <span>Brand Strategy</span>\r\n          <span>Client Partnerships</span>\r\n          <span>Business Growth</span>\r\n          <span>Hospitality Innovation</span>\r\n          <span>Strategic Planning</span>\r\n        </div>\r\n\r\n        <div class=\"vision-callout\">\r\n          <div class=\"vc-head\">\r\n            <i class=\"fas fa-compass\"></i>\r\n            <span>Future Vision &amp; Leadership</span>\r\n          </div>\r\n          <p>As Future CEO, Vihani champions a culture of excellence, transparency, and purposeful execution—ensuring every hospitality venture partnered with Artha transforms ambitious ideas into thriving, guest-loved destinations.</p>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 3: FOUNDER & DIRECTOR SPOTLIGHT (ANIL KUMAR K) -->\r\n<section class=\"leader-spotlight bg-offwhite\" id=\"anil-kumar\">\r\n  <div class=\"wrap\">\r\n    <div class=\"spotlight-grid reverse\">\r\n\r\n      <!-- Biography & Vision Column -->\r\n      <div class=\"leader-copy anim-base anim-fade-right\">\r\n        <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n        <h2>Anil Kumar K</h2>\r\n        <div class=\"role-pill\">\r\n          <i class=\"fas fa-chess-king\"></i>\r\n          <span>Founder &amp; Director – Artha Hospitality</span>\r\n        </div>\r\n\r\n        <div class=\"leader-bio\">\r\n          <p>Chef Anil Kumar K is the Founder &amp; Director of Artha Hospitality, bringing over 25 years of experience in the hospitality industry.</p>\r\n          <p>With a professional background as a Chef, Anil has extensive hands-on experience in professional kitchens, restaurant operations, kitchen planning, commercial kitchen equipment, food production, and hospitality management.</p>\r\n          <p>His 25 years of industry experience provide him with a deep understanding of the practical requirements of hotels, restaurants, cafés, catering businesses, and commercial food-service operations.</p>\r\n        </div>\r\n\r\n        <div class=\"leader-chips\">\r\n          <span>Professional Kitchens</span>\r\n          <span>Restaurant Operations</span>\r\n          <span>Kitchen Planning</span>\r\n          <span>Commercial Kitchen Equipment</span>\r\n          <span>Food Production</span>\r\n          <span>Hospitality Management</span>\r\n        </div>\r\n\r\n        <div class=\"vision-callout\">\r\n          <div class=\"vc-head\">\r\n            <i class=\"fas fa-compass\"></i>\r\n            <span>Strategic Vision &amp; Leadership</span>\r\n          </div>\r\n          <p>As Founder &amp; Director of Artha Hospitality, Anil leads the company’s business strategy, kitchen solutions, operational planning, client relationships, and overall execution, with a vision to deliver reliable, efficient, and sustainable hospitality solutions.</p>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Portrait Column -->\r\n      <div class=\"leader-portrait-stage anim-base anim-fade-left delay-100\">\r\n        <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-frame\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/anil-kumar-k.jpg\" alt=\"Chef Anil Kumar K - Founder & Director of Artha Hospitality\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Chef Anil Kumar K - Founder &amp; Director – Artha Hospitality</figcaption>\r\n          </figure>\r\n        </div>\r\n        <div class=\"portrait-exp-badge\">\r\n          <strong>25+</strong>\r\n          <span>Years in<br>Hospitality</span>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: HR DIRECTOR SPOTLIGHT - SUSHMA AMIN -->\r\n<section class=\"leader-spotlight bg-sand-light\" id=\"sushma-amin\">\r\n  <div class=\"wrap spotlight-grid\">\r\n\r\n    <!-- Portrait Column -->\r\n    <div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n      <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n      <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n      <div class=\"portrait-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/sushma-amin.jpg\" alt=\"Sushma Amin - HR Director & Hospitality HR Professional\" loading=\"lazy\">\r\n          <figcaption class=\"cr-only\">Sushma Amin - HR Director &amp; Hospitality HR Professional</figcaption>\r\n        </figure>\r\n      </div>\r\n      <div class=\"portrait-exp-badge\">\r\n        <strong>20+</strong>\r\n        <span>Years in HR &amp;<br>Hospitality</span>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Biography & Vision Column -->\r\n    <div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n      <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n      <h2>Sushma Amin</h2>\r\n      <div class=\"role-pill\">\r\n        <i class=\"fas fa-balance-scale\"></i>\r\n        <span>HR Director &amp; Hospitality HR Professional</span>\r\n      </div>\r\n\r\n      <div class=\"leader-bio\">\r\n        <p>Sushma Amin is a seasoned Human Resources professional with over 20 years of experience in the HR and hospitality industry, bringing extensive expertise in people management, talent acquisition, employee relations, HR operations, and organizational development.</p>\r\n        <p>With a strong academic background in Bachelor of Arts (BA) and Bachelor of Laws (LLB), she combines professional knowledge with practical industry experience to build effective HR practices and people-centric workplaces.</p>\r\n        <p>Throughout her career, she has worked with leading hospitality establishments, gaining valuable experience in managing diverse workforces, developing HR systems, streamlining recruitment processes, and supporting business growth through effective human resource management.</p>\r\n      </div>\r\n\r\n      <div class=\"leader-chips\">\r\n        <span>People Management</span>\r\n        <span>Talent Acquisition</span>\r\n        <span>Employee Relations</span>\r\n        <span>HR Operations</span>\r\n        <span>Organizational Development</span>\r\n        <span>BA &amp; LLB</span>\r\n      </div>\r\n\r\n      <div class=\"vision-callout\">\r\n        <div class=\"vc-head\">\r\n          <i class=\"fas fa-bullseye\"></i>\r\n          <span>Professional Vision</span>\r\n        </div>\r\n        <p>Her professional vision is to connect the right talent with the right opportunities, empower people, strengthen organizations, and contribute to the growth of the hospitality industry through ethical, transparent, and result-oriented HR practices.</p>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: ARTHA EXECUTIVE MANAGEMENT (SNEHA M. & SANDEEP SHETTY) -->\r\n<section class=\"management-section\" id=\"executive-management\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Artha Hospitality Team</span>\r\n      <h2>Driving Recruitment, Sales &amp; Operational Excellence.</h2>\r\n      <p>Connecting talented hospitality professionals with leading organizations and delivering disciplined, guest-focused operational results every day.</p>\r\n    </div>\r\n\r\n    <!-- Profile 1: Sneha M. -->\r\n    <article class=\"exec-profile-block anim-base anim-fade-up\">\r\n      <div class=\"exec-top-grid\">\r\n        <div class=\"exec-photo-wrap\">\r\n          <div class=\"exec-photo-frame\">\r\n            <figure class=\"cr-figure\">\r\n              <img src=http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/sneha-m.jpg\" alt=\"Sneha M. - HR Executive at Artha Hospitality\" loading=\"lazy\">\r\n              <figcaption class=\"cr-only\">Sneha M. - HR Executive | Artha Hospitality</figcaption>\r\n            </figure>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"exec-intro\">\r\n          <span class=\"eyebrow\">People &amp; Talent</span>\r\n          <h3>Sneha M.</h3>\r\n          <div class=\"exec-role\">\r\n            <i class=\"fas fa-id-badge\"></i>\r\n            <span>HR Executive | Artha Hospitality</span>\r\n          </div>\r\n          <p>As an HR Executive at Artha Hospitality, I am responsible for identifying, attracting and connecting the right talent with the right opportunities in the hospitality industry.</p>\r\n          <p>I believe that successful businesses are built by the right people. My focus is on understanding client requirements, building strong relationships with candidates and ensuring a smooth and effective recruitment process.</p>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"exec-pillars-grid\">\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-eye\"></i></span>\r\n            <h4>My Vision</h4>\r\n          </div>\r\n          <p>To connect talented individuals with the right opportunities and help hospitality businesses grow through quality recruitment, trust and strong professional relationships.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box dark\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-bullseye\"></i></span>\r\n            <h4>My Mission</h4>\r\n          </div>\r\n          <p>To make recruitment a meaningful experience by bringing together the right people and the right organizations.</p>\r\n        </div>\r\n      </div>\r\n    </article>\r\n\r\n    <!-- Profile 2: Sandeep Shetty -->\r\n    <article class=\"exec-profile-block reverse anim-base anim-fade-up\">\r\n      <div class=\"exec-top-grid\">\r\n        <div class=\"exec-intro\">\r\n          <span class=\"eyebrow\">Growth &amp; Operations</span>\r\n          <h3>Sandeep Shetty</h3>\r\n          <div class=\"exec-role\">\r\n            <i class=\"fas fa-briefcase\"></i>\r\n            <span>Sales &amp; Operations Manager | Artha Hospitality</span>\r\n          </div>\r\n          <p>As a Sales &amp; Operations Manager at Artha Hospitality, I am responsible for driving business growth, leading operations, and creating exceptional guest experiences in the hospitality industry.</p>\r\n          <p>I believe that successful hospitality businesses are built on strong leadership, consistent service, and the right people. My focus is on understanding client needs, building lasting business relationships, and ensuring smooth, result-driven operations.</p>\r\n        </div>\r\n\r\n        <div class=\"exec-photo-wrap\">\r\n          <div class=\"exec-photo-frame\">\r\n            <figure class=\"cr-figure\">\r\n              <img src=http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/sandeep-shetty.jpg\" alt=\"Sandeep Shetty - Sales & Operations Manager at Artha Hospitality\" loading=\"lazy\">\r\n              <figcaption class=\"cr-only\">Sandeep Shetty - Sales &amp; Operations Manager | Artha Hospitality</figcaption>\r\n            </figure>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"exec-pillars-grid cols-3\">\r\n        <div class=\"pillar-box dark\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-chess-knight\"></i></span>\r\n            <h4>My Leadership</h4>\r\n          </div>\r\n          <p>I lead by example — with clarity, accountability, and a people-first approach. My leadership is focused on building high-performing teams, empowering individuals, and creating a culture of ownership, discipline, and excellence.</p>\r\n          <p>I believe a great leader doesn\'t just manage operations; they inspire people to deliver their best every single day.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-eye\"></i></span>\r\n            <h4>My Vision</h4>\r\n          </div>\r\n          <p>To lead Artha Hospitality towards sustainable growth by combining strong sales strategies, operational excellence, and meaningful human connections — and to make it a trusted name in the hospitality industry.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-rocket\"></i></span>\r\n            <h4>My Mission</h4>\r\n          </div>\r\n          <p>To drive sales with integrity, deliver operations with excellence, and create value for clients, guests, and the team — by bringing together the right strategy, the right people, and the right execution.</p>\r\n        </div>\r\n      </div>\r\n    </article>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- WHY CHOOSE US SECTION -->\r\n<section class=\"why-choose-section\" id=\"why-choose-us\">\r\n  <div class=\"wrap\">\r\n    <div class=\"why-choose-head anim-base anim-fade-up\">\r\n      <span class=\"eyebrow\">Why Choose Us?</span>\r\n      <h2>Experience That Turns Ideas Into Successful Operations.</h2>\r\n      <p>“Backed by over <em>15 years</em> of experience in hospitality and hotel operations, our team combines industry insight with proven strategies to deliver solutions that work from day one.”</p>\r\n    </div>\r\n\r\n    <div class=\"why-choose-grid\">\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-100\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-award\"></i></span>\r\n        <h3>Industry Experience</h3>\r\n        <p>More than 15 years of hands-on experience in hospitality and hotel operations.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-200\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-chart-line\"></i></span>\r\n        <h3>Strategic Approach</h3>\r\n        <p>Solutions built around your specific business requirements and operational objectives.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-layer-group\"></i></span>\r\n        <h3>End-to-End Support</h3>\r\n        <p>Comprehensive guidance across planning, development, design, and everyday operations.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-user-check\"></i></span>\r\n        <h3>Guest-Centred Thinking</h3>\r\n        <p>Dedicated focus on elevating guest satisfaction, food quality, and service standards.</p>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 5: CTA -->\r\n<section class=\"cta\">\r\n  <div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n    <span class=\"eyebrow\">Let\'s Work Together</span>\r\n    <h2>Ready to Build or Elevate Your Hospitality Venture?</h2>\r\n    <p>Connect with our leadership and operations team to discuss kitchen planning, recruitment, or end-to-end hospitality consultancy.</p>\r\n    <div class=\"cta-btns\">\r\n      <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-light\">Start a Conversation <span class=\"arrow\">↗</span></a>\r\n      <a href=\"tel:+918951511234\" class=\"btn btn-outline-light\">Call Us Today</a>\r\n    </div>\r\n  </div>\r\n</section>', 'About', '', 'inherit', 'closed', 'closed', '', '11-revision-v1', '', '', '2026-11-26 09:02:29', '2026-11-26 09:02:29', '', 11, 'http://localhost/artha-hospitality-management/?p=26', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(27, 1, '2026-11-26 09:03:38', '2026-11-26 09:03:38', '<!-- NEW 75VH ABOUT US HERO SECTION -->\r\n<section class=\"about-editorial-hero\" id=\"about-top\">\r\n  <div class=\"wrap hero-inner\">\r\n\r\n    <!-- Column 1: Editorial Copy & CTAs -->\r\n    <div class=\"hero-story-col anim-base anim-fade-right\">\r\n      <div class=\"hero-top-tags\">\r\n        <nav class=\"breadcrumb-pill\" aria-label=\"Breadcrumb\">\r\n          <a href=\"index.html\">Home</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <span class=\"current\">About Us</span>\r\n        </nav>\r\n        <span class=\"eyebrow\">Who We Are</span>\r\n      </div>\r\n\r\n      <h1>Shaping the Future of <em>Thoughtful Hospitality</em> From Concept to Table.</h1>\r\n      <p>At Artha Hospitality Management, we partner with visionary restaurateurs, hoteliers, and hospitality entrepreneurs to turn ambitious concepts into resilient, high-performing destinations.</p>\r\n\r\n      <div class=\"hero-cta-group\">\r\n        <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-primary\">Partner With Artha <span class=\"arrow\">↗</span></a>\r\n        <a href=\"index.html#services\" class=\"btn btn-ghost\">Our Capabilities</a>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Column 2: Single Image Sculptural Stage with Theme Shapes -->\r\n    <div class=\"hero-visual-stage anim-base anim-fade-left delay-100\">\r\n      <!-- Shape 1: Concentric Gold Contour Rings -->\r\n      <svg class=\"stage-shape-rings\" viewBox=\"0 0 240 240\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"120\" cy=\"120\" r=\"110\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"82\" opacity=\"0.65\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"54\" opacity=\"0.4\" />\r\n      </svg>\r\n\r\n      <!-- Shape 2: Deep Espresso Architectural Offset Slab -->\r\n      <div class=\"stage-shape-slab\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 3: Gold Offset Wireframe Arch -->\r\n      <div class=\"stage-shape-wireframe\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 4: Gold Dot Matrix Pattern -->\r\n      <div class=\"stage-shape-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 5: Floating Espresso & Gold Medallion Seal -->\r\n      <div class=\"stage-medallion\">\r\n        <span class=\"med-icon\" aria-hidden=\"true\"><i class=\"fas fa-award\"></i></span>\r\n        <div class=\"med-text\">\r\n          <strong>15+ Yrs</strong>\r\n          <span>Hospitality Mastery</span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Main Sculpted Arched Image Panel -->\r\n      <div class=\"hero-arch-panel\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-about-us-hero.jpg\" alt=\"Hospitality team collaborating in a professional kitchen\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Hospitality team collaborating in a professional kitchen</figcaption>\r\n        </figure>\r\n        <div class=\"arch-caption-bar\">\r\n          <div>\r\n            <span class=\"tag-sub\">Operational Craft</span>\r\n            <span class=\"tag-title\">Ground-Level Expertise</span>\r\n          </div>\r\n          <span class=\"tag-ic\" aria-hidden=\"true\"><i class=\"fas fa-compass\"></i></span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 1: ENGAGING ABOUT ARTHA HOSPITALITY -->\r\n<section class=\"about-artha-section\" id=\"about-artha\">\r\n  <div class=\"wrap\">\r\n    <div class=\"about-artha-grid\">\r\n\r\n      <!-- Story & Philosophy Copy -->\r\n      <div class=\"artha-story-copy anim-base anim-fade-right\">\r\n        <span class=\"eyebrow\">About Us</span>\r\n        <h2>Hospitality Begins With <em>Great Service.</em></h2>\r\n        <p class=\"lead-p\">At Artha, we believe that great hospitality begins with great service. Our mission is to help restaurant owners and hospitality businesses overcome their toughest service challenges, improve guest satisfaction, and grow sustainably.</p>\r\n        <p>With a deep understanding of the industry and a commitment to excellence, we provide tailor-made solutions that create lasting value for our partners.</p>\r\n\r\n        <div class=\"artha-values-list\">\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-hotel\"></i></span>\r\n            <div>\r\n              <h4>Industry Understanding</h4>\r\n              <p>Grounded in more than 15 years of hospitality and hotel operations experience.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-star\"></i></span>\r\n            <div>\r\n              <h4>Tailor-Made Solutions</h4>\r\n              <p>Approaches shaped around your business, your guests, and your operational goals.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"artha-value-item\">\r\n            <span class=\"av-ic\" aria-hidden=\"true\"><i class=\"fas fa-check-circle\"></i></span>\r\n            <div>\r\n              <h4>Commitment to Excellence</h4>\r\n              <p>A consistent focus on quality, service standards, and sustainable long-term growth.</p>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <a href=\"index.html#services\" class=\"btn btn-primary\">Discover What We Do <span class=\"arrow\">↗</span></a>\r\n      </div>\r\n\r\n      <!-- Layered Hospitality Collage -->\r\n      <div class=\"artha-story-visual anim-base anim-fade-left delay-100\">\r\n        <div class=\"artha-vis-tag\">\r\n          <span class=\"vt-ic\" aria-hidden=\"true\"><i class=\"fas fa-compass\"></i></span>\r\n          <div>\r\n            <span>15+ Years Experience</span>\r\n            <strong>Solutions That Work From Day One</strong>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"artha-vis-main\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/slide-img-2-lgr.jpg\" alt=\"Elegant hospitality reception and dining space\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Elegant hospitality reception and dining space</figcaption>\r\n          </figure>\r\n        </div>\r\n\r\n        <div class=\"artha-vis-sub\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-management-about-us-sml-img.jpg\" alt=\"Premium restaurant dining environment\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Premium restaurant dining environment</figcaption>\r\n          </figure>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 2: LEADERSHIP & VISION + CEO SPOTLIGHT (VIHANI ANIL) -->\r\n<section class=\"leader-spotlight bg-sand-light\" id=\"vihani-anil\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n      <h2>The Minds Driving Culinary, People &amp; Operational Excellence.</h2>\r\n      <p>Guided by visionary leadership, seasoned hospitality veterans, kitchen innovators, HR strategists, and operations leaders committed to building resilient, people-first hospitality ventures.</p>\r\n    </div>\r\n\r\n    <div class=\"spotlight-grid\">\r\n\r\n      <!-- Portrait Column -->\r\n      <div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n        <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-frame\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/vihani-anil.jpg\" alt=\"Vihani Anil - Future CEO, Artha Hospitality Management\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Vihani Anil - Future CEO | Artha Hospitality Management</figcaption>\r\n          </figure>\r\n        </div>\r\n        <div class=\"portrait-exp-badge\">\r\n          <strong>Future</strong>\r\n          <span>CEO · Artha<br>Hospitality</span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Biography & Vision Column -->\r\n      <div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n        <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n        <h2>Vihani Anil</h2>\r\n        <div class=\"role-pill\">\r\n          <i class=\"fas fa-crown\"></i>\r\n          <span>Future CEO | Artha Hospitality Management</span>\r\n        </div>\r\n\r\n        <div class=\"leader-bio\">\r\n          <p>Vihani Anil is the Future CEO of Artha Hospitality Management, representing the next generation of strategic leadership, brand vision, and client-first hospitality advisory across India.</p>\r\n          <p>Guided by the principle <em>Dream · Plan · Achieve</em>, she brings a forward-looking perspective to modern hospitality consulting—bridging creative concept development with disciplined business planning and sustainable growth.</p>\r\n          <p>Her leadership focus centres on empowering restaurant, café, hotel, cloud kitchen, and resort founders with clarity, structured execution, and long-term operational confidence from day one.</p>\r\n        </div>\r\n\r\n        <div class=\"leader-chips\">\r\n          <span>Future Leadership</span>\r\n          <span>Brand Strategy</span>\r\n          <span>Client Partnerships</span>\r\n          <span>Business Growth</span>\r\n          <span>Hospitality Innovation</span>\r\n          <span>Strategic Planning</span>\r\n        </div>\r\n\r\n        <div class=\"vision-callout\">\r\n          <div class=\"vc-head\">\r\n            <i class=\"fas fa-compass\"></i>\r\n            <span>Future Vision &amp; Leadership</span>\r\n          </div>\r\n          <p>As Future CEO, Vihani champions a culture of excellence, transparency, and purposeful execution—ensuring every hospitality venture partnered with Artha transforms ambitious ideas into thriving, guest-loved destinations.</p>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 3: FOUNDER & DIRECTOR SPOTLIGHT (ANIL KUMAR K) -->\r\n<section class=\"leader-spotlight bg-offwhite\" id=\"anil-kumar\">\r\n  <div class=\"wrap\">\r\n    <div class=\"spotlight-grid reverse\">\r\n\r\n      <!-- Biography & Vision Column -->\r\n      <div class=\"leader-copy anim-base anim-fade-right\">\r\n        <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n        <h2>Anil Kumar K</h2>\r\n        <div class=\"role-pill\">\r\n          <i class=\"fas fa-chess-king\"></i>\r\n          <span>Founder &amp; Director – Artha Hospitality</span>\r\n        </div>\r\n\r\n        <div class=\"leader-bio\">\r\n          <p>Chef Anil Kumar K is the Founder &amp; Director of Artha Hospitality, bringing over 25 years of experience in the hospitality industry.</p>\r\n          <p>With a professional background as a Chef, Anil has extensive hands-on experience in professional kitchens, restaurant operations, kitchen planning, commercial kitchen equipment, food production, and hospitality management.</p>\r\n          <p>His 25 years of industry experience provide him with a deep understanding of the practical requirements of hotels, restaurants, cafés, catering businesses, and commercial food-service operations.</p>\r\n        </div>\r\n\r\n        <div class=\"leader-chips\">\r\n          <span>Professional Kitchens</span>\r\n          <span>Restaurant Operations</span>\r\n          <span>Kitchen Planning</span>\r\n          <span>Commercial Kitchen Equipment</span>\r\n          <span>Food Production</span>\r\n          <span>Hospitality Management</span>\r\n        </div>\r\n\r\n        <div class=\"vision-callout\">\r\n          <div class=\"vc-head\">\r\n            <i class=\"fas fa-compass\"></i>\r\n            <span>Strategic Vision &amp; Leadership</span>\r\n          </div>\r\n          <p>As Founder &amp; Director of Artha Hospitality, Anil leads the company’s business strategy, kitchen solutions, operational planning, client relationships, and overall execution, with a vision to deliver reliable, efficient, and sustainable hospitality solutions.</p>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Portrait Column -->\r\n      <div class=\"leader-portrait-stage anim-base anim-fade-left delay-100\">\r\n        <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n        <div class=\"portrait-frame\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/anil-kumar-k.jpg\" alt=\"Chef Anil Kumar K - Founder & Director of Artha Hospitality\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Chef Anil Kumar K - Founder &amp; Director – Artha Hospitality</figcaption>\r\n          </figure>\r\n        </div>\r\n        <div class=\"portrait-exp-badge\">\r\n          <strong>25+</strong>\r\n          <span>Years in<br>Hospitality</span>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: HR DIRECTOR SPOTLIGHT - SUSHMA AMIN -->\r\n<section class=\"leader-spotlight bg-sand-light\" id=\"sushma-amin\">\r\n  <div class=\"wrap spotlight-grid\">\r\n\r\n    <!-- Portrait Column -->\r\n    <div class=\"leader-portrait-stage anim-base anim-fade-right\">\r\n      <div class=\"portrait-backing\" aria-hidden=\"true\"></div>\r\n      <div class=\"portrait-wireframe\" aria-hidden=\"true\"></div>\r\n      <div class=\"portrait-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/sushma-amin.jpg\" alt=\"Sushma Amin - HR Director & Hospitality HR Professional\" loading=\"lazy\">\r\n          <figcaption class=\"cr-only\">Sushma Amin - HR Director &amp; Hospitality HR Professional</figcaption>\r\n        </figure>\r\n      </div>\r\n      <div class=\"portrait-exp-badge\">\r\n        <strong>20+</strong>\r\n        <span>Years in HR &amp;<br>Hospitality</span>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Biography & Vision Column -->\r\n    <div class=\"leader-copy anim-base anim-fade-left delay-100\">\r\n      <span class=\"eyebrow\">Leadership &amp; Vision</span>\r\n      <h2>Sushma Amin</h2>\r\n      <div class=\"role-pill\">\r\n        <i class=\"fas fa-balance-scale\"></i>\r\n        <span>HR Director &amp; Hospitality HR Professional</span>\r\n      </div>\r\n\r\n      <div class=\"leader-bio\">\r\n        <p>Sushma Amin is a seasoned Human Resources professional with over 20 years of experience in the HR and hospitality industry, bringing extensive expertise in people management, talent acquisition, employee relations, HR operations, and organizational development.</p>\r\n        <p>With a strong academic background in Bachelor of Arts (BA) and Bachelor of Laws (LLB), she combines professional knowledge with practical industry experience to build effective HR practices and people-centric workplaces.</p>\r\n        <p>Throughout her career, she has worked with leading hospitality establishments, gaining valuable experience in managing diverse workforces, developing HR systems, streamlining recruitment processes, and supporting business growth through effective human resource management.</p>\r\n      </div>\r\n\r\n      <div class=\"leader-chips\">\r\n        <span>People Management</span>\r\n        <span>Talent Acquisition</span>\r\n        <span>Employee Relations</span>\r\n        <span>HR Operations</span>\r\n        <span>Organizational Development</span>\r\n        <span>BA &amp; LLB</span>\r\n      </div>\r\n\r\n      <div class=\"vision-callout\">\r\n        <div class=\"vc-head\">\r\n          <i class=\"fas fa-bullseye\"></i>\r\n          <span>Professional Vision</span>\r\n        </div>\r\n        <p>Her professional vision is to connect the right talent with the right opportunities, empower people, strengthen organizations, and contribute to the growth of the hospitality industry through ethical, transparent, and result-oriented HR practices.</p>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: ARTHA EXECUTIVE MANAGEMENT (SNEHA M. & SANDEEP SHETTY) -->\r\n<section class=\"management-section\" id=\"executive-management\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Artha Hospitality Team</span>\r\n      <h2>Driving Recruitment, Sales &amp; Operational Excellence.</h2>\r\n      <p>Connecting talented hospitality professionals with leading organizations and delivering disciplined, guest-focused operational results every day.</p>\r\n    </div>\r\n\r\n    <!-- Profile 1: Sneha M. -->\r\n    <article class=\"exec-profile-block anim-base anim-fade-up\">\r\n      <div class=\"exec-top-grid\">\r\n        <div class=\"exec-photo-wrap\">\r\n          <div class=\"exec-photo-frame\">\r\n            <figure class=\"cr-figure\">\r\n              <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/sneha-m.jpg\" alt=\"Sneha M. - HR Executive at Artha Hospitality\" loading=\"lazy\">\r\n              <figcaption class=\"cr-only\">Sneha M. - HR Executive | Artha Hospitality</figcaption>\r\n            </figure>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"exec-intro\">\r\n          <span class=\"eyebrow\">People &amp; Talent</span>\r\n          <h3>Sneha M.</h3>\r\n          <div class=\"exec-role\">\r\n            <i class=\"fas fa-id-badge\"></i>\r\n            <span>HR Executive | Artha Hospitality</span>\r\n          </div>\r\n          <p>As an HR Executive at Artha Hospitality, I am responsible for identifying, attracting and connecting the right talent with the right opportunities in the hospitality industry.</p>\r\n          <p>I believe that successful businesses are built by the right people. My focus is on understanding client requirements, building strong relationships with candidates and ensuring a smooth and effective recruitment process.</p>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"exec-pillars-grid\">\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-eye\"></i></span>\r\n            <h4>My Vision</h4>\r\n          </div>\r\n          <p>To connect talented individuals with the right opportunities and help hospitality businesses grow through quality recruitment, trust and strong professional relationships.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box dark\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-bullseye\"></i></span>\r\n            <h4>My Mission</h4>\r\n          </div>\r\n          <p>To make recruitment a meaningful experience by bringing together the right people and the right organizations.</p>\r\n        </div>\r\n      </div>\r\n    </article>\r\n\r\n    <!-- Profile 2: Sandeep Shetty -->\r\n    <article class=\"exec-profile-block reverse anim-base anim-fade-up\">\r\n      <div class=\"exec-top-grid\">\r\n        <div class=\"exec-intro\">\r\n          <span class=\"eyebrow\">Growth &amp; Operations</span>\r\n          <h3>Sandeep Shetty</h3>\r\n          <div class=\"exec-role\">\r\n            <i class=\"fas fa-briefcase\"></i>\r\n            <span>Sales &amp; Operations Manager | Artha Hospitality</span>\r\n          </div>\r\n          <p>As a Sales &amp; Operations Manager at Artha Hospitality, I am responsible for driving business growth, leading operations, and creating exceptional guest experiences in the hospitality industry.</p>\r\n          <p>I believe that successful hospitality businesses are built on strong leadership, consistent service, and the right people. My focus is on understanding client needs, building lasting business relationships, and ensuring smooth, result-driven operations.</p>\r\n        </div>\r\n\r\n        <div class=\"exec-photo-wrap\">\r\n          <div class=\"exec-photo-frame\">\r\n            <figure class=\"cr-figure\">\r\n              <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/about-us-images/sandeep-shetty.jpg\" alt=\"Sandeep Shetty - Sales & Operations Manager at Artha Hospitality\" loading=\"lazy\">\r\n              <figcaption class=\"cr-only\">Sandeep Shetty - Sales &amp; Operations Manager | Artha Hospitality</figcaption>\r\n            </figure>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"exec-pillars-grid cols-3\">\r\n        <div class=\"pillar-box dark\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-chess-knight\"></i></span>\r\n            <h4>My Leadership</h4>\r\n          </div>\r\n          <p>I lead by example — with clarity, accountability, and a people-first approach. My leadership is focused on building high-performing teams, empowering individuals, and creating a culture of ownership, discipline, and excellence.</p>\r\n          <p>I believe a great leader doesn\'t just manage operations; they inspire people to deliver their best every single day.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-eye\"></i></span>\r\n            <h4>My Vision</h4>\r\n          </div>\r\n          <p>To lead Artha Hospitality towards sustainable growth by combining strong sales strategies, operational excellence, and meaningful human connections — and to make it a trusted name in the hospitality industry.</p>\r\n        </div>\r\n\r\n        <div class=\"pillar-box\">\r\n          <div class=\"pb-head\">\r\n            <span class=\"pb-ic\" aria-hidden=\"true\"><i class=\"fas fa-rocket\"></i></span>\r\n            <h4>My Mission</h4>\r\n          </div>\r\n          <p>To drive sales with integrity, deliver operations with excellence, and create value for clients, guests, and the team — by bringing together the right strategy, the right people, and the right execution.</p>\r\n        </div>\r\n      </div>\r\n    </article>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- WHY CHOOSE US SECTION -->\r\n<section class=\"why-choose-section\" id=\"why-choose-us\">\r\n  <div class=\"wrap\">\r\n    <div class=\"why-choose-head anim-base anim-fade-up\">\r\n      <span class=\"eyebrow\">Why Choose Us?</span>\r\n      <h2>Experience That Turns Ideas Into Successful Operations.</h2>\r\n      <p>“Backed by over <em>15 years</em> of experience in hospitality and hotel operations, our team combines industry insight with proven strategies to deliver solutions that work from day one.”</p>\r\n    </div>\r\n\r\n    <div class=\"why-choose-grid\">\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-100\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-award\"></i></span>\r\n        <h3>Industry Experience</h3>\r\n        <p>More than 15 years of hands-on experience in hospitality and hotel operations.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-200\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-chart-line\"></i></span>\r\n        <h3>Strategic Approach</h3>\r\n        <p>Solutions built around your specific business requirements and operational objectives.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-layer-group\"></i></span>\r\n        <h3>End-to-End Support</h3>\r\n        <p>Comprehensive guidance across planning, development, design, and everyday operations.</p>\r\n      </article>\r\n\r\n      <article class=\"why-choose-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"wc-ic\" aria-hidden=\"true\"><i class=\"fas fa-user-check\"></i></span>\r\n        <h3>Guest-Centred Thinking</h3>\r\n        <p>Dedicated focus on elevating guest satisfaction, food quality, and service standards.</p>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 5: CTA -->\r\n<section class=\"cta\">\r\n  <div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n    <span class=\"eyebrow\">Let\'s Work Together</span>\r\n    <h2>Ready to Build or Elevate Your Hospitality Venture?</h2>\r\n    <p>Connect with our leadership and operations team to discuss kitchen planning, recruitment, or end-to-end hospitality consultancy.</p>\r\n    <div class=\"cta-btns\">\r\n      <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-light\">Start a Conversation <span class=\"arrow\">↗</span></a>\r\n      <a href=\"tel:+918951511234\" class=\"btn btn-outline-light\">Call Us Today</a>\r\n    </div>\r\n  </div>\r\n</section>', 'About', '', 'inherit', 'closed', 'closed', '', '11-revision-v1', '', '', '2026-11-26 09:03:38', '2026-11-26 09:03:38', '', 11, 'http://localhost/artha-hospitality-management/?p=27', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(28, 1, '2026-11-26 09:27:59', '2026-11-26 09:27:59', '<article>\r\n<!-- NEW 75VH SCULPTED LEAF-ARCH & GEOMETRIC HERO SECTION -->\r\n<section class=\"capex-hero\" id=\"capex-top\">\r\n  <div class=\"wrap capex-hero-grid\">\r\n\r\n    <!-- Left Column: Editorial Copy & CTAs -->\r\n    <div class=\"capex-hero-copy anim-base anim-fade-right\">\r\n      <div class=\"service-meta-row\">\r\n        <nav class=\"crumb-badge\" aria-label=\"Breadcrumb\">\r\n          <a href=\"http://localhost/artha-hospitality-management/\">Home</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <a href=\"#\">Services</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <span class=\"curr\">Capital Investment Plan</span>\r\n        </nav>\r\n        <span class=\"eyebrow\">Financial Advisory</span>\r\n      </div>\r\n\r\n      <h1>A Clear Capital Roadmap for <em>Future Hospitality Profits.</em></h1>\r\n      <p class=\"hero-definition\">A roadmap that outlines the long-term spending on property, equipment, and infrastructure to build, expand, or upgrade the business for future profits.</p>\r\n\r\n      <div class=\"capex-hero-actions\">\r\n        <a href=\"http://localhost/artha-hospitality-management/contact-us\" class=\"btn btn-primary\">Start Your Investment Plan <span class=\"arrow\">↗</span></a>\r\n        <a href=\"#spending-scope\" class=\"btn btn-ghost\">Explore Spending Scope</a>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Right Column: Single Image Leaf-Arch Stage with Geometric Shapes -->\r\n    <div class=\"capex-visual-stage anim-base anim-fade-left delay-100\">\r\n      <!-- Shape 1: Espresso Quarter-Arch Slab -->\r\n      <div class=\"hero-shape-navy-arch\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 2: Gold Offset Wireframe -->\r\n      <div class=\"hero-shape-gold-wire\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 3: Concentric Gold Contour Rings -->\r\n      <svg class=\"hero-shape-rings\" viewBox=\"0 0 240 240\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"120\" cy=\"120\" r=\"108\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"80\" opacity=\"0.65\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"52\" opacity=\"0.4\" />\r\n      </svg>\r\n\r\n      <!-- Shape 4: Gold Dot Matrix -->\r\n      <div class=\"hero-shape-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Main Single Image Frames -->\r\n      <div class=\"hero-leaf-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-mangement-capital-investment-hero.jpg\" alt=\"Premium hospitality space planned for long-term profitability\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Premium hospitality space planned for long-term profitability</figcaption>\r\n        </figure>\r\n      </div>\r\n\r\n      <!-- Floating Light CapEx Pill -->\r\n      <div class=\"hero-floating-pill\">\r\n        <span class=\"fp-ic\" aria-hidden=\"true\"><i class=\"fas fa-chart-pie\"></i></span>\r\n        <div class=\"fp-txt\">\r\n          <strong>Strategic CapEx Roadmap</strong>\r\n          <span>Property · Equipment · Infrastructure</span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 1: STRATEGIC OVERVIEW & ALLOCATION BLUEPRINT (OFFWHITE - NO CARDS) -->\r\n<section class=\"capex-overview-sec\" id=\"overview\">\r\n  <div class=\"wrap overview-split\">\r\n\r\n    <div class=\"overview-copy anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Capital Investment Plan</span>\r\n      <h2>Investing Where It Matters Most for <em>Long-Term Returns.</em></h2>\r\n      <p>In hospitality, the financial decisions made before opening day—or ahead of an expansion—shape your cash flow and operating margins for years. Overspending on non-essential finishes while underinvesting in kitchen production capacity or core utility loads is one of the most common causes of delayed break-even.</p>\r\n      <p>Artha Hospitality Management works alongside founders and investors to structure a practical, transparent <strong>Capital Investment Plan</strong>. We align every rupee allocated to property, commercial equipment, and infrastructure with your projected guest volume and target profitability.</p>\r\n\r\n      <div class=\"charter-quote-strip\">\r\n        <span>The Core Charter</span>\r\n        <p>“A roadmap that outlines the long-term spending on property, equipment, and infrastructure to build, expand, or upgrade the business for future profits.”</p>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Right Column: Sculpted Single Image with Geometric Shapes (No Text) -->\r\n    <div class=\"overview-arch-stage anim-base anim-fade-left delay-100\">\r\n      <svg class=\"oas-rings-svg\" viewBox=\"0 0 220 220\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"110\" cy=\"110\" r=\"98\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"110\" cy=\"110\" r=\"70\" opacity=\"0.65\" />\r\n      </svg>\r\n      <div class=\"oas-navy-slab\" aria-hidden=\"true\"></div>\r\n      <div class=\"oas-wireframe\" aria-hidden=\"true\"></div>\r\n      <div class=\"oas-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <div class=\"oas-backdrop-img\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-capital-inverstments-content-1.jpg\" alt=\"Hospitality capital investment planning across property, equipment, and interior architecture\" loading=\"lazy\">\r\n          <figcaption class=\"cr-only\">Hospitality capital investment planning across property, equipment, and interior architecture</figcaption>\r\n        </figure>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 2: OPEN ARCHITECTURAL BLUEPRINT MATRIX (#F4EFE6 - NEW DESIGN, NO CARDS) -->\r\n<section class=\"capex-scope-sec\" id=\"spending-scope\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-split anim-base anim-fade-right\">\r\n      <div class=\"head-split-title\">\r\n        <span class=\"eyebrow\">What Our Roadmap Covers</span>\r\n        <h2>Comprehensive Capital Planning Across Every Asset Class.</h2>\r\n      </div>\r\n      <p>We itemize and validate every major capital expenditure category so your hospitality project stays on budget from blueprint to launch.</p>\r\n    </div>\r\n\r\n    <div class=\"blueprint-matrix anim-base anim-fade-up delay-100\">\r\n      <!-- Cell 1 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Property Focus</span>\r\n            <i class=\"fas fa-map-marked-alt bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Property &amp; Lease Economics</h3>\r\n            <p>Evaluating property acquisition costs, security deposits, lock-in periods, and space-to-seating ratios to protect long-term fixed overheads.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Deposit Modeling</span>\r\n          <span><i class=\"fas fa-check\"></i> Seating-to-Area Ratio</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 2 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Culinary Asset</span>\r\n            <i class=\"fas fa-utensils bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Commercial Kitchen Machinery</h3>\r\n            <p>Right-sizing your investment in heavy-duty cooking equipment, prep stations, cold storage, and dishwashing lines for peak-hour speed.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Production Line BOQ</span>\r\n          <span><i class=\"fas fa-check\"></i> Cold-Chain Setup</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 3 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Structural Core</span>\r\n            <i class=\"fas fa-hard-hat bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Civil &amp; Structural Modifications</h3>\r\n            <p>Budgeting for masonry, flooring, drainage slopes, waterproofing, and structural partitioning required for compliant food-service operations.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Civil Works Costing</span>\r\n          <span><i class=\"fas fa-check\"></i> Kitchen Drainage &amp; Flooring</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 4 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Guest Experience</span>\r\n            <i class=\"fas fa-couch bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Interior Ambience &amp; Seating Flow</h3>\r\n            <p>Allocating capital across dining furniture, custom millwork, acoustic treatments, and architectural lighting that elevate guest dwell time.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Furniture &amp; Millwork</span>\r\n          <span><i class=\"fas fa-check\"></i> Lighting &amp; Acoustics</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 5 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Utility Backbone</span>\r\n            <i class=\"fas fa-bolt bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>MEP, HVAC &amp; Utility Infrastructure</h3>\r\n            <p>Planning electrical load upgrades, fresh-air and exhaust ducting, gas banks, and water filtration systems to prevent operational bottlenecks.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Exhaust &amp; Fresh Air</span>\r\n          <span><i class=\"fas fa-check\"></i> Electrical &amp; Gas Banks</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 6 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Financial Cushion</span>\r\n            <i class=\"fas fa-coins bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Pre-Opening &amp; Contingency Reserves</h3>\r\n            <p>Structuring working capital buffers, initial inventory outlays, licensing fees, and contingency reserves for a stress-free launch phase.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Working Capital Buffer</span>\r\n          <span><i class=\"fas fa-check\"></i> Statutory &amp; Launch Reserve</span>\r\n        </div>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 3: BUILD, EXPAND, OR UPGRADE (OFFWHITE - VISUAL + EDITORIAL ROWS, NO CARDS) -->\r\n<section class=\"lifecycle-sec\" id=\"growth-horizons\">\r\n  <div class=\"wrap lifecycle-split\">\r\n\r\n    <div class=\"lifecycle-visual-col anim-base anim-fade-right\">\r\n      <div class=\"lc-wireframe\" aria-hidden=\"true\"></div>\r\n      <div class=\"lc-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-mangement-hotels-img.jpg\" alt=\"Hospitality property planned for long-term growth\" loading=\"lazy\">\r\n          <figcaption class=\"cr-only\">Hospitality property planned for long-term growth</figcaption>\r\n        </figure>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"lifecycle-stages-col anim-base anim-fade-left delay-100\">\r\n      <span class=\"eyebrow\">Tailored to Your Business Stage</span>\r\n      <h2>Built to Build, Expand, or Upgrade for Future Profits.</h2>\r\n      <p>Every stage of a hospitality venture requires a distinct capital strategy. We tailor your spending roadmap to match your immediate operational goals and long-term profit horizon.</p>\r\n\r\n      <div class=\"stage-rows\">\r\n        <div class=\"stage-item\">\r\n          <span class=\"si-ic\" aria-hidden=\"true\"><i class=\"fas fa-seedling\"></i></span>\r\n          <div>\r\n            <h3>Build a New Hospitality Venture</h3>\r\n            <p>Turnkey capital planning for new restaurants, hotels, cafés, and resto-bars—mapping out every pre-opening expense from raw shell to grand opening.</p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"stage-item\">\r\n          <span class=\"si-ic\" aria-hidden=\"true\"><i class=\"fas fa-expand-arrows-alt\"></i></span>\r\n          <div>\r\n            <h3>Expand Your Brand Footprint</h3>\r\n            <p>Standardized unit-level CapEx models and central kitchen investment strategies that allow growing brands to scale across new locations with predictable ROI.</p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"stage-item\">\r\n          <span class=\"si-ic\" aria-hidden=\"true\"><i class=\"fas fa-sync-alt\"></i></span>\r\n          <div>\r\n            <h3>Upgrade Existing Assets</h3>\r\n            <p>Targeted capital reinvestment to modernize aging kitchen lines, refresh dining interiors, expand seating capacity, and lower utility overheads.</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: OUR METHODOLOGY (CREAM - THE ONLY CARD SECTION, NO NUMBERS) -->\r\n<section class=\"process-sec\" id=\"planning-process\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Our Methodology</span>\r\n      <h2>How We Build Your Capital Investment Roadmap.</h2>\r\n      <p>A structured process that connects every capital expenditure decision directly to operational capacity and long-term profitability.</p>\r\n    </div>\r\n\r\n    <div class=\"process-grid\">\r\n      <div class=\"process-card anim-base anim-fade-up delay-100\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-search-dollar\"></i></span>\r\n        <h3>Concept &amp; Capacity Audit</h3>\r\n        <p>We define your target covers, menu complexity, and space requirements to establish realistic capital boundaries.</p>\r\n      </div>\r\n\r\n      <div class=\"process-card anim-base anim-fade-up delay-200\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-clipboard-list\"></i></span>\r\n        <h3>Asset &amp; BOQ Costing</h3>\r\n        <p>Detailed itemization of property, civil, interior, and commercial kitchen equipment costs with vetted vendor estimates.</p>\r\n      </div>\r\n\r\n      <div class=\"process-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-calendar-check\"></i></span>\r\n        <h3>Phased Spend Schedule</h3>\r\n        <p>Milestone-based capital deployment timeline aligned with civil progress, equipment delivery, and pre-opening readiness.</p>\r\n      </div>\r\n\r\n      <div class=\"process-card anim-base anim-fade-up delay-400\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-chart-line\"></i></span>\r\n        <h3>ROI &amp; Profit Projection</h3>\r\n        <p>Comprehensive revenue, operating margin, and payback period modeling to safeguard long-term investor returns.</p>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 5: CTA (CHAMPAGNE #F5EBDD) -->\r\n<section class=\"cta\">\r\n  <div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n    <span class=\"eyebrow\">Start With a Clear Roadmap</span>\r\n    <h2>Ready to Plan Your Hospitality Capital Investment?</h2>\r\n    <p>Partner with Artha Hospitality Management to structure your property, equipment, and infrastructure spending for sustainable future profits.</p>\r\n    <div class=\"cta-btns\">\r\n      <a href=\"http://localhost/artha-hospitality-management/contact-us\" class=\"btn btn-light\">Schedule a Consultation <span class=\"arrow\">↗</span></a>\r\n      <a href=\"tel:+918951511234\" class=\"btn btn-outline-light\">Call Us Today</a>\r\n    </div>\r\n  </div>\r\n</section>\r\n</article>\r\n', 'Capital Investment Plan', '', 'publish', 'closed', 'closed', '', 'capital-investment-plan', '', '', '2026-11-26 09:37:25', '2026-11-26 09:37:25', '', 0, 'http://localhost/artha-hospitality-management/?page_id=28', 0, 'page', '', 0);
INSERT INTO `wp_posts` VALUES(29, 1, '2026-11-26 09:27:59', '2026-11-26 09:27:59', '<article>\r\n<!-- NEW 75VH SCULPTED LEAF-ARCH & GEOMETRIC HERO SECTION -->\r\n<section class=\"capex-hero\" id=\"capex-top\">\r\n  <div class=\"wrap capex-hero-grid\">\r\n\r\n    <!-- Left Column: Editorial Copy & CTAs -->\r\n    <div class=\"capex-hero-copy anim-base anim-fade-right\">\r\n      <div class=\"service-meta-row\">\r\n        <nav class=\"crumb-badge\" aria-label=\"Breadcrumb\">\r\n          <a href=\"index.html\">Home</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <a href=\"index.html#services\">Services</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <span class=\"curr\">Capital Investment Plan</span>\r\n        </nav>\r\n        <span class=\"eyebrow\">Financial Advisory</span>\r\n      </div>\r\n\r\n      <h1>A Clear Capital Roadmap for <em>Future Hospitality Profits.</em></h1>\r\n      <p class=\"hero-definition\">A roadmap that outlines the long-term spending on property, equipment, and infrastructure to build, expand, or upgrade the business for future profits.</p>\r\n\r\n      <div class=\"capex-hero-actions\">\r\n        <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-primary\">Start Your Investment Plan <span class=\"arrow\">↗</span></a>\r\n        <a href=\"#spending-scope\" class=\"btn btn-ghost\">Explore Spending Scope</a>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Right Column: Single Image Leaf-Arch Stage with Geometric Shapes -->\r\n    <div class=\"capex-visual-stage anim-base anim-fade-left delay-100\">\r\n      <!-- Shape 1: Espresso Quarter-Arch Slab -->\r\n      <div class=\"hero-shape-navy-arch\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 2: Gold Offset Wireframe -->\r\n      <div class=\"hero-shape-gold-wire\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 3: Concentric Gold Contour Rings -->\r\n      <svg class=\"hero-shape-rings\" viewBox=\"0 0 240 240\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"120\" cy=\"120\" r=\"108\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"80\" opacity=\"0.65\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"52\" opacity=\"0.4\" />\r\n      </svg>\r\n\r\n      <!-- Shape 4: Gold Dot Matrix -->\r\n      <div class=\"hero-shape-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Main Single Image Frames -->\r\n      <div class=\"hero-leaf-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"images/artha-hospitality-mangement-capital-investment-hero.jpg\" alt=\"Premium hospitality space planned for long-term profitability\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Premium hospitality space planned for long-term profitability</figcaption>\r\n        </figure>\r\n      </div>\r\n\r\n      <!-- Floating Light CapEx Pill -->\r\n      <div class=\"hero-floating-pill\">\r\n        <span class=\"fp-ic\" aria-hidden=\"true\"><i class=\"fas fa-chart-pie\"></i></span>\r\n        <div class=\"fp-txt\">\r\n          <strong>Strategic CapEx Roadmap</strong>\r\n          <span>Property · Equipment · Infrastructure</span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 1: STRATEGIC OVERVIEW & ALLOCATION BLUEPRINT (OFFWHITE - NO CARDS) -->\r\n<section class=\"capex-overview-sec\" id=\"overview\">\r\n  <div class=\"wrap overview-split\">\r\n\r\n    <div class=\"overview-copy anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Capital Investment Plan</span>\r\n      <h2>Investing Where It Matters Most for <em>Long-Term Returns.</em></h2>\r\n      <p>In hospitality, the financial decisions made before opening day—or ahead of an expansion—shape your cash flow and operating margins for years. Overspending on non-essential finishes while underinvesting in kitchen production capacity or core utility loads is one of the most common causes of delayed break-even.</p>\r\n      <p>Artha Hospitality Management works alongside founders and investors to structure a practical, transparent <strong>Capital Investment Plan</strong>. We align every rupee allocated to property, commercial equipment, and infrastructure with your projected guest volume and target profitability.</p>\r\n\r\n      <div class=\"charter-quote-strip\">\r\n        <span>The Core Charter</span>\r\n        <p>“A roadmap that outlines the long-term spending on property, equipment, and infrastructure to build, expand, or upgrade the business for future profits.”</p>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Right Column: Sculpted Single Image with Geometric Shapes (No Text) -->\r\n    <div class=\"overview-arch-stage anim-base anim-fade-left delay-100\">\r\n      <svg class=\"oas-rings-svg\" viewBox=\"0 0 220 220\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"110\" cy=\"110\" r=\"98\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"110\" cy=\"110\" r=\"70\" opacity=\"0.65\" />\r\n      </svg>\r\n      <div class=\"oas-navy-slab\" aria-hidden=\"true\"></div>\r\n      <div class=\"oas-wireframe\" aria-hidden=\"true\"></div>\r\n      <div class=\"oas-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <div class=\"oas-backdrop-img\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"images/artha-hospitality-capital-inverstments-content-1.jpg\" alt=\"Hospitality capital investment planning across property, equipment, and interior architecture\" loading=\"lazy\">\r\n          <figcaption class=\"cr-only\">Hospitality capital investment planning across property, equipment, and interior architecture</figcaption>\r\n        </figure>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 2: OPEN ARCHITECTURAL BLUEPRINT MATRIX (#F4EFE6 - NEW DESIGN, NO CARDS) -->\r\n<section class=\"capex-scope-sec\" id=\"spending-scope\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-split anim-base anim-fade-right\">\r\n      <div class=\"head-split-title\">\r\n        <span class=\"eyebrow\">What Our Roadmap Covers</span>\r\n        <h2>Comprehensive Capital Planning Across Every Asset Class.</h2>\r\n      </div>\r\n      <p>We itemize and validate every major capital expenditure category so your hospitality project stays on budget from blueprint to launch.</p>\r\n    </div>\r\n\r\n    <div class=\"blueprint-matrix anim-base anim-fade-up delay-100\">\r\n      <!-- Cell 1 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Property Focus</span>\r\n            <i class=\"fas fa-map-marked-alt bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Property &amp; Lease Economics</h3>\r\n            <p>Evaluating property acquisition costs, security deposits, lock-in periods, and space-to-seating ratios to protect long-term fixed overheads.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Deposit Modeling</span>\r\n          <span><i class=\"fas fa-check\"></i> Seating-to-Area Ratio</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 2 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Culinary Asset</span>\r\n            <i class=\"fas fa-utensils bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Commercial Kitchen Machinery</h3>\r\n            <p>Right-sizing your investment in heavy-duty cooking equipment, prep stations, cold storage, and dishwashing lines for peak-hour speed.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Production Line BOQ</span>\r\n          <span><i class=\"fas fa-check\"></i> Cold-Chain Setup</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 3 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Structural Core</span>\r\n            <i class=\"fas fa-hard-hat bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Civil &amp; Structural Modifications</h3>\r\n            <p>Budgeting for masonry, flooring, drainage slopes, waterproofing, and structural partitioning required for compliant food-service operations.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Civil Works Costing</span>\r\n          <span><i class=\"fas fa-check\"></i> Kitchen Drainage &amp; Flooring</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 4 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Guest Experience</span>\r\n            <i class=\"fas fa-couch bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Interior Ambience &amp; Seating Flow</h3>\r\n            <p>Allocating capital across dining furniture, custom millwork, acoustic treatments, and architectural lighting that elevate guest dwell time.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Furniture &amp; Millwork</span>\r\n          <span><i class=\"fas fa-check\"></i> Lighting &amp; Acoustics</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 5 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Utility Backbone</span>\r\n            <i class=\"fas fa-bolt bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>MEP, HVAC &amp; Utility Infrastructure</h3>\r\n            <p>Planning electrical load upgrades, fresh-air and exhaust ducting, gas banks, and water filtration systems to prevent operational bottlenecks.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Exhaust &amp; Fresh Air</span>\r\n          <span><i class=\"fas fa-check\"></i> Electrical &amp; Gas Banks</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 6 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Financial Cushion</span>\r\n            <i class=\"fas fa-coins bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Pre-Opening &amp; Contingency Reserves</h3>\r\n            <p>Structuring working capital buffers, initial inventory outlays, licensing fees, and contingency reserves for a stress-free launch phase.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Working Capital Buffer</span>\r\n          <span><i class=\"fas fa-check\"></i> Statutory &amp; Launch Reserve</span>\r\n        </div>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 3: BUILD, EXPAND, OR UPGRADE (OFFWHITE - VISUAL + EDITORIAL ROWS, NO CARDS) -->\r\n<section class=\"lifecycle-sec\" id=\"growth-horizons\">\r\n  <div class=\"wrap lifecycle-split\">\r\n\r\n    <div class=\"lifecycle-visual-col anim-base anim-fade-right\">\r\n      <div class=\"lc-wireframe\" aria-hidden=\"true\"></div>\r\n      <div class=\"lc-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"images/artha-hospitality-mangement-hotels-img.jpg\" alt=\"Hospitality property planned for long-term growth\" loading=\"lazy\">\r\n          <figcaption class=\"cr-only\">Hospitality property planned for long-term growth</figcaption>\r\n        </figure>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"lifecycle-stages-col anim-base anim-fade-left delay-100\">\r\n      <span class=\"eyebrow\">Tailored to Your Business Stage</span>\r\n      <h2>Built to Build, Expand, or Upgrade for Future Profits.</h2>\r\n      <p>Every stage of a hospitality venture requires a distinct capital strategy. We tailor your spending roadmap to match your immediate operational goals and long-term profit horizon.</p>\r\n\r\n      <div class=\"stage-rows\">\r\n        <div class=\"stage-item\">\r\n          <span class=\"si-ic\" aria-hidden=\"true\"><i class=\"fas fa-seedling\"></i></span>\r\n          <div>\r\n            <h3>Build a New Hospitality Venture</h3>\r\n            <p>Turnkey capital planning for new restaurants, hotels, cafés, and resto-bars—mapping out every pre-opening expense from raw shell to grand opening.</p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"stage-item\">\r\n          <span class=\"si-ic\" aria-hidden=\"true\"><i class=\"fas fa-expand-arrows-alt\"></i></span>\r\n          <div>\r\n            <h3>Expand Your Brand Footprint</h3>\r\n            <p>Standardized unit-level CapEx models and central kitchen investment strategies that allow growing brands to scale across new locations with predictable ROI.</p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"stage-item\">\r\n          <span class=\"si-ic\" aria-hidden=\"true\"><i class=\"fas fa-sync-alt\"></i></span>\r\n          <div>\r\n            <h3>Upgrade Existing Assets</h3>\r\n            <p>Targeted capital reinvestment to modernize aging kitchen lines, refresh dining interiors, expand seating capacity, and lower utility overheads.</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: OUR METHODOLOGY (CREAM - THE ONLY CARD SECTION, NO NUMBERS) -->\r\n<section class=\"process-sec\" id=\"planning-process\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Our Methodology</span>\r\n      <h2>How We Build Your Capital Investment Roadmap.</h2>\r\n      <p>A structured process that connects every capital expenditure decision directly to operational capacity and long-term profitability.</p>\r\n    </div>\r\n\r\n    <div class=\"process-grid\">\r\n      <div class=\"process-card anim-base anim-fade-up delay-100\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-search-dollar\"></i></span>\r\n        <h3>Concept &amp; Capacity Audit</h3>\r\n        <p>We define your target covers, menu complexity, and space requirements to establish realistic capital boundaries.</p>\r\n      </div>\r\n\r\n      <div class=\"process-card anim-base anim-fade-up delay-200\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-clipboard-list\"></i></span>\r\n        <h3>Asset &amp; BOQ Costing</h3>\r\n        <p>Detailed itemization of property, civil, interior, and commercial kitchen equipment costs with vetted vendor estimates.</p>\r\n      </div>\r\n\r\n      <div class=\"process-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-calendar-check\"></i></span>\r\n        <h3>Phased Spend Schedule</h3>\r\n        <p>Milestone-based capital deployment timeline aligned with civil progress, equipment delivery, and pre-opening readiness.</p>\r\n      </div>\r\n\r\n      <div class=\"process-card anim-base anim-fade-up delay-400\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-chart-line\"></i></span>\r\n        <h3>ROI &amp; Profit Projection</h3>\r\n        <p>Comprehensive revenue, operating margin, and payback period modeling to safeguard long-term investor returns.</p>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 5: CTA (CHAMPAGNE #F5EBDD) -->\r\n<section class=\"cta\">\r\n  <div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n    <span class=\"eyebrow\">Start With a Clear Roadmap</span>\r\n    <h2>Ready to Plan Your Hospitality Capital Investment?</h2>\r\n    <p>Partner with Artha Hospitality Management to structure your property, equipment, and infrastructure spending for sustainable future profits.</p>\r\n    <div class=\"cta-btns\">\r\n      <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-light\">Schedule a Consultation <span class=\"arrow\">↗</span></a>\r\n      <a href=\"tel:+918951511234\" class=\"btn btn-outline-light\">Call Us Today</a>\r\n    </div>\r\n  </div>\r\n</section>\r\n</article>\r\n', 'Capital Investment Plan', '', 'inherit', 'closed', 'closed', '', '28-revision-v1', '', '', '2026-11-26 09:27:59', '2026-11-26 09:27:59', '', 28, 'http://localhost/artha-hospitality-management/?p=29', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(31, 1, '2026-11-27 09:22:29', '2026-11-26 09:28:52', '', 'Services', '', 'publish', 'closed', 'closed', '', 'services', '', '', '2026-11-27 09:22:29', '2026-11-27 09:22:29', '', 0, 'http://localhost/artha-hospitality-management/?p=31', 3, 'nav_menu_item', '', 0);
INSERT INTO `wp_posts` VALUES(32, 1, '2026-11-26 09:34:33', '2026-11-26 09:34:33', '<article>\r\n<!-- NEW 75VH SCULPTED LEAF-ARCH & GEOMETRIC HERO SECTION -->\r\n<section class=\"capex-hero\" id=\"capex-top\">\r\n  <div class=\"wrap capex-hero-grid\">\r\n\r\n    <!-- Left Column: Editorial Copy & CTAs -->\r\n    <div class=\"capex-hero-copy anim-base anim-fade-right\">\r\n      <div class=\"service-meta-row\">\r\n        <nav class=\"crumb-badge\" aria-label=\"Breadcrumb\">\r\n          <a href=\"index.html\">Home</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <a href=\"index.html#services\">Services</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <span class=\"curr\">Capital Investment Plan</span>\r\n        </nav>\r\n        <span class=\"eyebrow\">Financial Advisory</span>\r\n      </div>\r\n\r\n      <h1>A Clear Capital Roadmap for <em>Future Hospitality Profits.</em></h1>\r\n      <p class=\"hero-definition\">A roadmap that outlines the long-term spending on property, equipment, and infrastructure to build, expand, or upgrade the business for future profits.</p>\r\n\r\n      <div class=\"capex-hero-actions\">\r\n        <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-primary\">Start Your Investment Plan <span class=\"arrow\">↗</span></a>\r\n        <a href=\"#spending-scope\" class=\"btn btn-ghost\">Explore Spending Scope</a>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Right Column: Single Image Leaf-Arch Stage with Geometric Shapes -->\r\n    <div class=\"capex-visual-stage anim-base anim-fade-left delay-100\">\r\n      <!-- Shape 1: Espresso Quarter-Arch Slab -->\r\n      <div class=\"hero-shape-navy-arch\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 2: Gold Offset Wireframe -->\r\n      <div class=\"hero-shape-gold-wire\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 3: Concentric Gold Contour Rings -->\r\n      <svg class=\"hero-shape-rings\" viewBox=\"0 0 240 240\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"120\" cy=\"120\" r=\"108\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"80\" opacity=\"0.65\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"52\" opacity=\"0.4\" />\r\n      </svg>\r\n\r\n      <!-- Shape 4: Gold Dot Matrix -->\r\n      <div class=\"hero-shape-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Main Single Image Frames -->\r\n      <div class=\"hero-leaf-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-mangement-capital-investment-hero.jpg\" alt=\"Premium hospitality space planned for long-term profitability\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Premium hospitality space planned for long-term profitability</figcaption>\r\n        </figure>\r\n      </div>\r\n\r\n      <!-- Floating Light CapEx Pill -->\r\n      <div class=\"hero-floating-pill\">\r\n        <span class=\"fp-ic\" aria-hidden=\"true\"><i class=\"fas fa-chart-pie\"></i></span>\r\n        <div class=\"fp-txt\">\r\n          <strong>Strategic CapEx Roadmap</strong>\r\n          <span>Property · Equipment · Infrastructure</span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 1: STRATEGIC OVERVIEW & ALLOCATION BLUEPRINT (OFFWHITE - NO CARDS) -->\r\n<section class=\"capex-overview-sec\" id=\"overview\">\r\n  <div class=\"wrap overview-split\">\r\n\r\n    <div class=\"overview-copy anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Capital Investment Plan</span>\r\n      <h2>Investing Where It Matters Most for <em>Long-Term Returns.</em></h2>\r\n      <p>In hospitality, the financial decisions made before opening day—or ahead of an expansion—shape your cash flow and operating margins for years. Overspending on non-essential finishes while underinvesting in kitchen production capacity or core utility loads is one of the most common causes of delayed break-even.</p>\r\n      <p>Artha Hospitality Management works alongside founders and investors to structure a practical, transparent <strong>Capital Investment Plan</strong>. We align every rupee allocated to property, commercial equipment, and infrastructure with your projected guest volume and target profitability.</p>\r\n\r\n      <div class=\"charter-quote-strip\">\r\n        <span>The Core Charter</span>\r\n        <p>“A roadmap that outlines the long-term spending on property, equipment, and infrastructure to build, expand, or upgrade the business for future profits.”</p>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Right Column: Sculpted Single Image with Geometric Shapes (No Text) -->\r\n    <div class=\"overview-arch-stage anim-base anim-fade-left delay-100\">\r\n      <svg class=\"oas-rings-svg\" viewBox=\"0 0 220 220\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"110\" cy=\"110\" r=\"98\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"110\" cy=\"110\" r=\"70\" opacity=\"0.65\" />\r\n      </svg>\r\n      <div class=\"oas-navy-slab\" aria-hidden=\"true\"></div>\r\n      <div class=\"oas-wireframe\" aria-hidden=\"true\"></div>\r\n      <div class=\"oas-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <div class=\"oas-backdrop-img\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-capital-inverstments-content-1.jpg\" alt=\"Hospitality capital investment planning across property, equipment, and interior architecture\" loading=\"lazy\">\r\n          <figcaption class=\"cr-only\">Hospitality capital investment planning across property, equipment, and interior architecture</figcaption>\r\n        </figure>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 2: OPEN ARCHITECTURAL BLUEPRINT MATRIX (#F4EFE6 - NEW DESIGN, NO CARDS) -->\r\n<section class=\"capex-scope-sec\" id=\"spending-scope\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-split anim-base anim-fade-right\">\r\n      <div class=\"head-split-title\">\r\n        <span class=\"eyebrow\">What Our Roadmap Covers</span>\r\n        <h2>Comprehensive Capital Planning Across Every Asset Class.</h2>\r\n      </div>\r\n      <p>We itemize and validate every major capital expenditure category so your hospitality project stays on budget from blueprint to launch.</p>\r\n    </div>\r\n\r\n    <div class=\"blueprint-matrix anim-base anim-fade-up delay-100\">\r\n      <!-- Cell 1 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Property Focus</span>\r\n            <i class=\"fas fa-map-marked-alt bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Property &amp; Lease Economics</h3>\r\n            <p>Evaluating property acquisition costs, security deposits, lock-in periods, and space-to-seating ratios to protect long-term fixed overheads.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Deposit Modeling</span>\r\n          <span><i class=\"fas fa-check\"></i> Seating-to-Area Ratio</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 2 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Culinary Asset</span>\r\n            <i class=\"fas fa-utensils bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Commercial Kitchen Machinery</h3>\r\n            <p>Right-sizing your investment in heavy-duty cooking equipment, prep stations, cold storage, and dishwashing lines for peak-hour speed.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Production Line BOQ</span>\r\n          <span><i class=\"fas fa-check\"></i> Cold-Chain Setup</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 3 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Structural Core</span>\r\n            <i class=\"fas fa-hard-hat bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Civil &amp; Structural Modifications</h3>\r\n            <p>Budgeting for masonry, flooring, drainage slopes, waterproofing, and structural partitioning required for compliant food-service operations.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Civil Works Costing</span>\r\n          <span><i class=\"fas fa-check\"></i> Kitchen Drainage &amp; Flooring</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 4 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Guest Experience</span>\r\n            <i class=\"fas fa-couch bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Interior Ambience &amp; Seating Flow</h3>\r\n            <p>Allocating capital across dining furniture, custom millwork, acoustic treatments, and architectural lighting that elevate guest dwell time.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Furniture &amp; Millwork</span>\r\n          <span><i class=\"fas fa-check\"></i> Lighting &amp; Acoustics</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 5 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Utility Backbone</span>\r\n            <i class=\"fas fa-bolt bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>MEP, HVAC &amp; Utility Infrastructure</h3>\r\n            <p>Planning electrical load upgrades, fresh-air and exhaust ducting, gas banks, and water filtration systems to prevent operational bottlenecks.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Exhaust &amp; Fresh Air</span>\r\n          <span><i class=\"fas fa-check\"></i> Electrical &amp; Gas Banks</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 6 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Financial Cushion</span>\r\n            <i class=\"fas fa-coins bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Pre-Opening &amp; Contingency Reserves</h3>\r\n            <p>Structuring working capital buffers, initial inventory outlays, licensing fees, and contingency reserves for a stress-free launch phase.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Working Capital Buffer</span>\r\n          <span><i class=\"fas fa-check\"></i> Statutory &amp; Launch Reserve</span>\r\n        </div>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 3: BUILD, EXPAND, OR UPGRADE (OFFWHITE - VISUAL + EDITORIAL ROWS, NO CARDS) -->\r\n<section class=\"lifecycle-sec\" id=\"growth-horizons\">\r\n  <div class=\"wrap lifecycle-split\">\r\n\r\n    <div class=\"lifecycle-visual-col anim-base anim-fade-right\">\r\n      <div class=\"lc-wireframe\" aria-hidden=\"true\"></div>\r\n      <div class=\"lc-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-mangement-hotels-img.jpg\" alt=\"Hospitality property planned for long-term growth\" loading=\"lazy\">\r\n          <figcaption class=\"cr-only\">Hospitality property planned for long-term growth</figcaption>\r\n        </figure>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"lifecycle-stages-col anim-base anim-fade-left delay-100\">\r\n      <span class=\"eyebrow\">Tailored to Your Business Stage</span>\r\n      <h2>Built to Build, Expand, or Upgrade for Future Profits.</h2>\r\n      <p>Every stage of a hospitality venture requires a distinct capital strategy. We tailor your spending roadmap to match your immediate operational goals and long-term profit horizon.</p>\r\n\r\n      <div class=\"stage-rows\">\r\n        <div class=\"stage-item\">\r\n          <span class=\"si-ic\" aria-hidden=\"true\"><i class=\"fas fa-seedling\"></i></span>\r\n          <div>\r\n            <h3>Build a New Hospitality Venture</h3>\r\n            <p>Turnkey capital planning for new restaurants, hotels, cafés, and resto-bars—mapping out every pre-opening expense from raw shell to grand opening.</p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"stage-item\">\r\n          <span class=\"si-ic\" aria-hidden=\"true\"><i class=\"fas fa-expand-arrows-alt\"></i></span>\r\n          <div>\r\n            <h3>Expand Your Brand Footprint</h3>\r\n            <p>Standardized unit-level CapEx models and central kitchen investment strategies that allow growing brands to scale across new locations with predictable ROI.</p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"stage-item\">\r\n          <span class=\"si-ic\" aria-hidden=\"true\"><i class=\"fas fa-sync-alt\"></i></span>\r\n          <div>\r\n            <h3>Upgrade Existing Assets</h3>\r\n            <p>Targeted capital reinvestment to modernize aging kitchen lines, refresh dining interiors, expand seating capacity, and lower utility overheads.</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: OUR METHODOLOGY (CREAM - THE ONLY CARD SECTION, NO NUMBERS) -->\r\n<section class=\"process-sec\" id=\"planning-process\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Our Methodology</span>\r\n      <h2>How We Build Your Capital Investment Roadmap.</h2>\r\n      <p>A structured process that connects every capital expenditure decision directly to operational capacity and long-term profitability.</p>\r\n    </div>\r\n\r\n    <div class=\"process-grid\">\r\n      <div class=\"process-card anim-base anim-fade-up delay-100\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-search-dollar\"></i></span>\r\n        <h3>Concept &amp; Capacity Audit</h3>\r\n        <p>We define your target covers, menu complexity, and space requirements to establish realistic capital boundaries.</p>\r\n      </div>\r\n\r\n      <div class=\"process-card anim-base anim-fade-up delay-200\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-clipboard-list\"></i></span>\r\n        <h3>Asset &amp; BOQ Costing</h3>\r\n        <p>Detailed itemization of property, civil, interior, and commercial kitchen equipment costs with vetted vendor estimates.</p>\r\n      </div>\r\n\r\n      <div class=\"process-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-calendar-check\"></i></span>\r\n        <h3>Phased Spend Schedule</h3>\r\n        <p>Milestone-based capital deployment timeline aligned with civil progress, equipment delivery, and pre-opening readiness.</p>\r\n      </div>\r\n\r\n      <div class=\"process-card anim-base anim-fade-up delay-400\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-chart-line\"></i></span>\r\n        <h3>ROI &amp; Profit Projection</h3>\r\n        <p>Comprehensive revenue, operating margin, and payback period modeling to safeguard long-term investor returns.</p>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 5: CTA (CHAMPAGNE #F5EBDD) -->\r\n<section class=\"cta\">\r\n  <div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n    <span class=\"eyebrow\">Start With a Clear Roadmap</span>\r\n    <h2>Ready to Plan Your Hospitality Capital Investment?</h2>\r\n    <p>Partner with Artha Hospitality Management to structure your property, equipment, and infrastructure spending for sustainable future profits.</p>\r\n    <div class=\"cta-btns\">\r\n      <a href=\"artha-hospitality-contact-us.html\" class=\"btn btn-light\">Schedule a Consultation <span class=\"arrow\">↗</span></a>\r\n      <a href=\"tel:+918951511234\" class=\"btn btn-outline-light\">Call Us Today</a>\r\n    </div>\r\n  </div>\r\n</section>\r\n</article>\r\n', 'Capital Investment Plan', '', 'inherit', 'closed', 'closed', '', '28-revision-v1', '', '', '2026-11-26 09:34:33', '2026-11-26 09:34:33', '', 28, 'http://localhost/artha-hospitality-management/?p=32', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(33, 1, '2026-11-26 09:37:25', '2026-11-26 09:37:25', '<article>\r\n<!-- NEW 75VH SCULPTED LEAF-ARCH & GEOMETRIC HERO SECTION -->\r\n<section class=\"capex-hero\" id=\"capex-top\">\r\n  <div class=\"wrap capex-hero-grid\">\r\n\r\n    <!-- Left Column: Editorial Copy & CTAs -->\r\n    <div class=\"capex-hero-copy anim-base anim-fade-right\">\r\n      <div class=\"service-meta-row\">\r\n        <nav class=\"crumb-badge\" aria-label=\"Breadcrumb\">\r\n          <a href=\"http://localhost/artha-hospitality-management/\">Home</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <a href=\"#\">Services</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <span class=\"curr\">Capital Investment Plan</span>\r\n        </nav>\r\n        <span class=\"eyebrow\">Financial Advisory</span>\r\n      </div>\r\n\r\n      <h1>A Clear Capital Roadmap for <em>Future Hospitality Profits.</em></h1>\r\n      <p class=\"hero-definition\">A roadmap that outlines the long-term spending on property, equipment, and infrastructure to build, expand, or upgrade the business for future profits.</p>\r\n\r\n      <div class=\"capex-hero-actions\">\r\n        <a href=\"http://localhost/artha-hospitality-management/contact-us\" class=\"btn btn-primary\">Start Your Investment Plan <span class=\"arrow\">↗</span></a>\r\n        <a href=\"#spending-scope\" class=\"btn btn-ghost\">Explore Spending Scope</a>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Right Column: Single Image Leaf-Arch Stage with Geometric Shapes -->\r\n    <div class=\"capex-visual-stage anim-base anim-fade-left delay-100\">\r\n      <!-- Shape 1: Espresso Quarter-Arch Slab -->\r\n      <div class=\"hero-shape-navy-arch\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 2: Gold Offset Wireframe -->\r\n      <div class=\"hero-shape-gold-wire\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Shape 3: Concentric Gold Contour Rings -->\r\n      <svg class=\"hero-shape-rings\" viewBox=\"0 0 240 240\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"120\" cy=\"120\" r=\"108\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"80\" opacity=\"0.65\" />\r\n        <circle cx=\"120\" cy=\"120\" r=\"52\" opacity=\"0.4\" />\r\n      </svg>\r\n\r\n      <!-- Shape 4: Gold Dot Matrix -->\r\n      <div class=\"hero-shape-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <!-- Main Single Image Frames -->\r\n      <div class=\"hero-leaf-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-mangement-capital-investment-hero.jpg\" alt=\"Premium hospitality space planned for long-term profitability\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Premium hospitality space planned for long-term profitability</figcaption>\r\n        </figure>\r\n      </div>\r\n\r\n      <!-- Floating Light CapEx Pill -->\r\n      <div class=\"hero-floating-pill\">\r\n        <span class=\"fp-ic\" aria-hidden=\"true\"><i class=\"fas fa-chart-pie\"></i></span>\r\n        <div class=\"fp-txt\">\r\n          <strong>Strategic CapEx Roadmap</strong>\r\n          <span>Property · Equipment · Infrastructure</span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 1: STRATEGIC OVERVIEW & ALLOCATION BLUEPRINT (OFFWHITE - NO CARDS) -->\r\n<section class=\"capex-overview-sec\" id=\"overview\">\r\n  <div class=\"wrap overview-split\">\r\n\r\n    <div class=\"overview-copy anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Capital Investment Plan</span>\r\n      <h2>Investing Where It Matters Most for <em>Long-Term Returns.</em></h2>\r\n      <p>In hospitality, the financial decisions made before opening day—or ahead of an expansion—shape your cash flow and operating margins for years. Overspending on non-essential finishes while underinvesting in kitchen production capacity or core utility loads is one of the most common causes of delayed break-even.</p>\r\n      <p>Artha Hospitality Management works alongside founders and investors to structure a practical, transparent <strong>Capital Investment Plan</strong>. We align every rupee allocated to property, commercial equipment, and infrastructure with your projected guest volume and target profitability.</p>\r\n\r\n      <div class=\"charter-quote-strip\">\r\n        <span>The Core Charter</span>\r\n        <p>“A roadmap that outlines the long-term spending on property, equipment, and infrastructure to build, expand, or upgrade the business for future profits.”</p>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Right Column: Sculpted Single Image with Geometric Shapes (No Text) -->\r\n    <div class=\"overview-arch-stage anim-base anim-fade-left delay-100\">\r\n      <svg class=\"oas-rings-svg\" viewBox=\"0 0 220 220\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"110\" cy=\"110\" r=\"98\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"110\" cy=\"110\" r=\"70\" opacity=\"0.65\" />\r\n      </svg>\r\n      <div class=\"oas-navy-slab\" aria-hidden=\"true\"></div>\r\n      <div class=\"oas-wireframe\" aria-hidden=\"true\"></div>\r\n      <div class=\"oas-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <div class=\"oas-backdrop-img\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-capital-inverstments-content-1.jpg\" alt=\"Hospitality capital investment planning across property, equipment, and interior architecture\" loading=\"lazy\">\r\n          <figcaption class=\"cr-only\">Hospitality capital investment planning across property, equipment, and interior architecture</figcaption>\r\n        </figure>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 2: OPEN ARCHITECTURAL BLUEPRINT MATRIX (#F4EFE6 - NEW DESIGN, NO CARDS) -->\r\n<section class=\"capex-scope-sec\" id=\"spending-scope\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-split anim-base anim-fade-right\">\r\n      <div class=\"head-split-title\">\r\n        <span class=\"eyebrow\">What Our Roadmap Covers</span>\r\n        <h2>Comprehensive Capital Planning Across Every Asset Class.</h2>\r\n      </div>\r\n      <p>We itemize and validate every major capital expenditure category so your hospitality project stays on budget from blueprint to launch.</p>\r\n    </div>\r\n\r\n    <div class=\"blueprint-matrix anim-base anim-fade-up delay-100\">\r\n      <!-- Cell 1 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Property Focus</span>\r\n            <i class=\"fas fa-map-marked-alt bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Property &amp; Lease Economics</h3>\r\n            <p>Evaluating property acquisition costs, security deposits, lock-in periods, and space-to-seating ratios to protect long-term fixed overheads.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Deposit Modeling</span>\r\n          <span><i class=\"fas fa-check\"></i> Seating-to-Area Ratio</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 2 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Culinary Asset</span>\r\n            <i class=\"fas fa-utensils bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Commercial Kitchen Machinery</h3>\r\n            <p>Right-sizing your investment in heavy-duty cooking equipment, prep stations, cold storage, and dishwashing lines for peak-hour speed.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Production Line BOQ</span>\r\n          <span><i class=\"fas fa-check\"></i> Cold-Chain Setup</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 3 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Structural Core</span>\r\n            <i class=\"fas fa-hard-hat bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Civil &amp; Structural Modifications</h3>\r\n            <p>Budgeting for masonry, flooring, drainage slopes, waterproofing, and structural partitioning required for compliant food-service operations.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Civil Works Costing</span>\r\n          <span><i class=\"fas fa-check\"></i> Kitchen Drainage &amp; Flooring</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 4 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Guest Experience</span>\r\n            <i class=\"fas fa-couch bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Interior Ambience &amp; Seating Flow</h3>\r\n            <p>Allocating capital across dining furniture, custom millwork, acoustic treatments, and architectural lighting that elevate guest dwell time.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Furniture &amp; Millwork</span>\r\n          <span><i class=\"fas fa-check\"></i> Lighting &amp; Acoustics</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 5 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Utility Backbone</span>\r\n            <i class=\"fas fa-bolt bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>MEP, HVAC &amp; Utility Infrastructure</h3>\r\n            <p>Planning electrical load upgrades, fresh-air and exhaust ducting, gas banks, and water filtration systems to prevent operational bottlenecks.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Exhaust &amp; Fresh Air</span>\r\n          <span><i class=\"fas fa-check\"></i> Electrical &amp; Gas Banks</span>\r\n        </div>\r\n      </article>\r\n\r\n      <!-- Cell 6 -->\r\n      <article class=\"bm-cell\">\r\n        <div>\r\n          <div class=\"bm-top\">\r\n            <span class=\"bm-domain-pill\">Financial Cushion</span>\r\n            <i class=\"fas fa-coins bm-icon\" aria-hidden=\"true\"></i>\r\n          </div>\r\n          <div class=\"bm-body\">\r\n            <h3>Pre-Opening &amp; Contingency Reserves</h3>\r\n            <p>Structuring working capital buffers, initial inventory outlays, licensing fees, and contingency reserves for a stress-free launch phase.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"bm-tags\">\r\n          <span><i class=\"fas fa-check\"></i> Working Capital Buffer</span>\r\n          <span><i class=\"fas fa-check\"></i> Statutory &amp; Launch Reserve</span>\r\n        </div>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 3: BUILD, EXPAND, OR UPGRADE (OFFWHITE - VISUAL + EDITORIAL ROWS, NO CARDS) -->\r\n<section class=\"lifecycle-sec\" id=\"growth-horizons\">\r\n  <div class=\"wrap lifecycle-split\">\r\n\r\n    <div class=\"lifecycle-visual-col anim-base anim-fade-right\">\r\n      <div class=\"lc-wireframe\" aria-hidden=\"true\"></div>\r\n      <div class=\"lc-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-mangement-hotels-img.jpg\" alt=\"Hospitality property planned for long-term growth\" loading=\"lazy\">\r\n          <figcaption class=\"cr-only\">Hospitality property planned for long-term growth</figcaption>\r\n        </figure>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"lifecycle-stages-col anim-base anim-fade-left delay-100\">\r\n      <span class=\"eyebrow\">Tailored to Your Business Stage</span>\r\n      <h2>Built to Build, Expand, or Upgrade for Future Profits.</h2>\r\n      <p>Every stage of a hospitality venture requires a distinct capital strategy. We tailor your spending roadmap to match your immediate operational goals and long-term profit horizon.</p>\r\n\r\n      <div class=\"stage-rows\">\r\n        <div class=\"stage-item\">\r\n          <span class=\"si-ic\" aria-hidden=\"true\"><i class=\"fas fa-seedling\"></i></span>\r\n          <div>\r\n            <h3>Build a New Hospitality Venture</h3>\r\n            <p>Turnkey capital planning for new restaurants, hotels, cafés, and resto-bars—mapping out every pre-opening expense from raw shell to grand opening.</p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"stage-item\">\r\n          <span class=\"si-ic\" aria-hidden=\"true\"><i class=\"fas fa-expand-arrows-alt\"></i></span>\r\n          <div>\r\n            <h3>Expand Your Brand Footprint</h3>\r\n            <p>Standardized unit-level CapEx models and central kitchen investment strategies that allow growing brands to scale across new locations with predictable ROI.</p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"stage-item\">\r\n          <span class=\"si-ic\" aria-hidden=\"true\"><i class=\"fas fa-sync-alt\"></i></span>\r\n          <div>\r\n            <h3>Upgrade Existing Assets</h3>\r\n            <p>Targeted capital reinvestment to modernize aging kitchen lines, refresh dining interiors, expand seating capacity, and lower utility overheads.</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: OUR METHODOLOGY (CREAM - THE ONLY CARD SECTION, NO NUMBERS) -->\r\n<section class=\"process-sec\" id=\"planning-process\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Our Methodology</span>\r\n      <h2>How We Build Your Capital Investment Roadmap.</h2>\r\n      <p>A structured process that connects every capital expenditure decision directly to operational capacity and long-term profitability.</p>\r\n    </div>\r\n\r\n    <div class=\"process-grid\">\r\n      <div class=\"process-card anim-base anim-fade-up delay-100\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-search-dollar\"></i></span>\r\n        <h3>Concept &amp; Capacity Audit</h3>\r\n        <p>We define your target covers, menu complexity, and space requirements to establish realistic capital boundaries.</p>\r\n      </div>\r\n\r\n      <div class=\"process-card anim-base anim-fade-up delay-200\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-clipboard-list\"></i></span>\r\n        <h3>Asset &amp; BOQ Costing</h3>\r\n        <p>Detailed itemization of property, civil, interior, and commercial kitchen equipment costs with vetted vendor estimates.</p>\r\n      </div>\r\n\r\n      <div class=\"process-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-calendar-check\"></i></span>\r\n        <h3>Phased Spend Schedule</h3>\r\n        <p>Milestone-based capital deployment timeline aligned with civil progress, equipment delivery, and pre-opening readiness.</p>\r\n      </div>\r\n\r\n      <div class=\"process-card anim-base anim-fade-up delay-400\">\r\n        <span class=\"pc-icon\" aria-hidden=\"true\"><i class=\"fas fa-chart-line\"></i></span>\r\n        <h3>ROI &amp; Profit Projection</h3>\r\n        <p>Comprehensive revenue, operating margin, and payback period modeling to safeguard long-term investor returns.</p>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 5: CTA (CHAMPAGNE #F5EBDD) -->\r\n<section class=\"cta\">\r\n  <div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n    <span class=\"eyebrow\">Start With a Clear Roadmap</span>\r\n    <h2>Ready to Plan Your Hospitality Capital Investment?</h2>\r\n    <p>Partner with Artha Hospitality Management to structure your property, equipment, and infrastructure spending for sustainable future profits.</p>\r\n    <div class=\"cta-btns\">\r\n      <a href=\"http://localhost/artha-hospitality-management/contact-us\" class=\"btn btn-light\">Schedule a Consultation <span class=\"arrow\">↗</span></a>\r\n      <a href=\"tel:+918951511234\" class=\"btn btn-outline-light\">Call Us Today</a>\r\n    </div>\r\n  </div>\r\n</section>\r\n</article>\r\n', 'Capital Investment Plan', '', 'inherit', 'closed', 'closed', '', '28-revision-v1', '', '', '2026-11-26 09:37:25', '2026-11-26 09:37:25', '', 28, 'http://localhost/artha-hospitality-management/?p=33', 0, 'revision', '', 0);
INSERT INTO `wp_posts` VALUES(34, 1, '2026-11-26 09:41:15', '2026-11-26 09:41:15', '<article>\r\n<!-- NEW 75VH STEPPED MONOLITH & CANTILEVER FOUNDATION HERO SECTION -->\r\n<section class=\"civil-hero\" id=\"civil-top\">\r\n  <div class=\"wrap civil-hero-grid\">\r\n\r\n    <!-- Left Column: Editorial Copy & CTAs -->\r\n    <div class=\"civil-hero-copy anim-base anim-fade-right\">\r\n      <div class=\"service-meta-row\">\r\n        <nav class=\"crumb-badge\" aria-label=\"Breadcrumb\">\r\n          <a href=\"http://localhost/artha-hospitality-management/\">Home</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <a href=\"#\">Services</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <span class=\"curr\">Civil Work</span>\r\n        </nav>\r\n        <span class=\"eyebrow\">Civil Work &amp; Infrastructure</span>\r\n      </div>\r\n\r\n      <h1>Building Strong Foundations for <em>Successful Hospitality Ventures.</em></h1>\r\n      <p>Every successful hospitality space begins with a strong structural foundation. At Artha Hospitality Management, we focus on the civil and infrastructure requirements involved in developing functional, durable, and well-planned hospitality spaces.</p>\r\n\r\n      <div class=\"civil-hero-actions\">\r\n        <a href=\"http://localhost/artha-hospitality-management/contact-us\" class=\"btn btn-primary\">Partner With Artha <span class=\"arrow\">↗</span></a>\r\n        <a href=\"#focus-areas\" class=\"btn btn-ghost\">Our Civil Focus Areas</a>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Right Column: Stepped Monolith & Cantilever Foundation Stage (No Text) -->\r\n    <div class=\"civil-monolith-stage anim-base anim-fade-left delay-100\">\r\n      <svg class=\"cm-arcs-svg\" viewBox=\"0 0 220 220\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"110\" cy=\"110\" r=\"98\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"110\" cy=\"110\" r=\"70\" opacity=\"0.65\" />\r\n      </svg>\r\n\r\n      <div class=\"cm-foundation-plinth\" aria-hidden=\"true\"></div>\r\n      <div class=\"cm-cantilever-beam\" aria-hidden=\"true\"></div>\r\n      <div class=\"cm-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <div class=\"cm-main-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-civil-work-hero-img1.jpg\" alt=\"Hospitality civil structure and architectural development\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Hospitality civil structure and architectural development</figcaption>\r\n        </figure>\r\n      </div>\r\n\r\n      <!-- Docked 3-Icon Structural Utility Bar (Icons Only, No Text) -->\r\n      <div class=\"cm-utility-dock\" aria-hidden=\"true\">\r\n        <span><i class=\"fas fa-hard-hat\"></i></span>\r\n        <span><i class=\"fas fa-tint\"></i></span>\r\n        <span><i class=\"fas fa-bolt\"></i></span>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 1: CREATING SPACES BUILT FOR PERFORMANCE (OFFWHITE) -->\r\n<section class=\"civil-performance-sec\" id=\"civil-performance\">\r\n  <div class=\"wrap performance-split\">\r\n\r\n    <div class=\"performance-copy anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Structural &amp; Utility Engineering</span>\r\n      <h2>Creating Spaces Built for <em>Performance.</em></h2>\r\n      <p>A hospitality establishment requires more than an attractive interior. Its underlying structure and essential infrastructure must support everyday operations, safety, durability, and long-term functionality.</p>\r\n      <p>Whether you are developing a new restaurant, hotel, café, or resto-bar, we help coordinate and plan essential civil work requirements to ensure that the building infrastructure aligns with your outlet design and operational objectives.</p>\r\n\r\n      <div class=\"foundation-callout\">\r\n        <span>Essential Building Elements</span>\r\n        <p>“From foundation planning and structural development to flooring, plumbing, and electrical systems, we help ensure that essential building elements are considered carefully to support the operational needs of your hospitality business.”</p>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Right Column: Single Image with Shapes (No Text) -->\r\n    <div class=\"performance-arch-stage anim-base anim-fade-left delay-100\">\r\n      <svg class=\"pas-rings-svg\" viewBox=\"0 0 220 220\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.2\" aria-hidden=\"true\">\r\n        <circle cx=\"110\" cy=\"110\" r=\"98\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"110\" cy=\"110\" r=\"70\" opacity=\"0.65\" />\r\n      </svg>\r\n      <div class=\"pas-navy-slab\" aria-hidden=\"true\"></div>\r\n      <div class=\"pas-wireframe\" aria-hidden=\"true\"></div>\r\n      <div class=\"pas-dots\" aria-hidden=\"true\"></div>\r\n\r\n      <div class=\"pas-backdrop-img\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-civil-workd-img1.jpg\" alt=\"Durable civil construction and hospitality infrastructure\" loading=\"lazy\">\r\n          <figcaption class=\"cr-only\">Durable civil construction and hospitality infrastructure</figcaption>\r\n        </figure>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 2: OUR CIVIL WORK FOCUS AREAS (DEEP ARCHITECTURAL NAVY #0D2244 - 5-ZONE BLUEPRINT MATRIX) -->\r\n<section class=\"civil-focus-sec\" id=\"focus-areas\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Core Structural &amp; Utility Systems</span>\r\n      <h2>Our Civil Work Focus Areas.</h2>\r\n      <p>Comprehensive planning across structural foundations, spatial partitioning, durable surfaces, and critical water and power infrastructure.</p>\r\n    </div>\r\n\r\n    <div class=\"civil-blueprint anim-base anim-fade-up delay-100\">\r\n      <!-- Top Row: 01 & 02 -->\r\n      <div class=\"cb-row-top\">\r\n        <!-- 01. Foundation & Structural Development -->\r\n        <article class=\"cb-cell\">\r\n          <div class=\"cb-top\">\r\n            <span class=\"cb-num-pill\">01. Foundation &amp; Structure</span>\r\n            <span class=\"cb-icon\" aria-hidden=\"true\"><i class=\"fas fa-hard-hat\"></i></span>\r\n          </div>\r\n          <div class=\"cb-body\">\r\n            <h3>Foundation &amp; Structural Development</h3>\r\n            <p>We focus on essential foundation and structural requirements to support the stability, strength, and long-term functionality of your hospitality establishment.</p>\r\n          </div>\r\n        </article>\r\n\r\n        <!-- 02. Walls & Space Development -->\r\n        <article class=\"cb-cell\">\r\n          <div class=\"cb-top\">\r\n            <span class=\"cb-num-pill\">02. Walls &amp; Space Development</span>\r\n            <span class=\"cb-icon\" aria-hidden=\"true\"><i class=\"fas fa-border-all\"></i></span>\r\n          </div>\r\n          <div class=\"cb-body\">\r\n            <h3>Walls &amp; Space Development</h3>\r\n            <p>We consider wall construction, partitions, and internal space development to establish practical layouts that complement the overall outlet design.</p>\r\n          </div>\r\n        </article>\r\n      </div>\r\n\r\n      <!-- Bottom Row: 03, 04 & 05 -->\r\n      <div class=\"cb-row-bottom\">\r\n        <!-- 03. Flooring & Surface Development -->\r\n        <article class=\"cb-cell\">\r\n          <div class=\"cb-top\">\r\n            <span class=\"cb-num-pill\">03. Flooring &amp; Surfaces</span>\r\n            <span class=\"cb-icon\" aria-hidden=\"true\"><i class=\"fas fa-layer-group\"></i></span>\r\n          </div>\r\n          <div class=\"cb-body\">\r\n            <h3>Flooring &amp; Surface Development</h3>\r\n            <p>We consider suitable flooring and surface requirements based on the functional needs of different areas, including dining spaces, kitchens, and service zones.</p>\r\n          </div>\r\n        </article>\r\n\r\n        <!-- 04. Plumbing & Water Systems -->\r\n        <article class=\"cb-cell\">\r\n          <div class=\"cb-top\">\r\n            <span class=\"cb-num-pill\">04. Plumbing &amp; Water</span>\r\n            <span class=\"cb-icon\" aria-hidden=\"true\"><i class=\"fas fa-tint\"></i></span>\r\n          </div>\r\n          <div class=\"cb-body\">\r\n            <h3>Plumbing &amp; Water Systems</h3>\r\n            <p>We focus on essential plumbing requirements, water supply arrangements, drainage, and sanitation infrastructure to support smooth daily operations.</p>\r\n          </div>\r\n        </article>\r\n\r\n        <!-- 05. Electrical Infrastructure -->\r\n        <article class=\"cb-cell\">\r\n          <div class=\"cb-top\">\r\n            <span class=\"cb-num-pill\">05. Electrical Systems</span>\r\n            <span class=\"cb-icon\" aria-hidden=\"true\"><i class=\"fas fa-bolt\"></i></span>\r\n          </div>\r\n          <div class=\"cb-body\">\r\n            <h3>Electrical Infrastructure</h3>\r\n            <p>We consider electrical layouts, power requirements, lighting provisions, and essential electrical systems to accommodate kitchen equipment and other operational needs.</p>\r\n          </div>\r\n        </article>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 3: OUR APPROACH TO CIVIL WORK (LIGHT SLATE-BLUE TINT #EDF2F8 - 4 CARDS) -->\r\n<section class=\"approach-sec\" id=\"civil-approach\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Our Process</span>\r\n      <h2>Our Approach to Civil Work.</h2>\r\n      <p>A disciplined four-stage process to plan, coordinate, and verify essential structural and utility infrastructure for your hospitality space.</p>\r\n    </div>\r\n\r\n    <div class=\"approach-grid\">\r\n      <article class=\"approach-card anim-base anim-fade-up delay-100\">\r\n        <span class=\"ac-icon\" aria-hidden=\"true\"><i class=\"fas fa-clipboard-list\"></i></span>\r\n        <h3>Understanding Project Requirements</h3>\r\n        <p>We begin by understanding your hospitality concept, building requirements, available space, and essential infrastructure needs.</p>\r\n      </article>\r\n\r\n      <article class=\"approach-card anim-base anim-fade-up delay-200\">\r\n        <span class=\"ac-icon\" aria-hidden=\"true\"><i class=\"fas fa-drafting-compass\"></i></span>\r\n        <h3>Planning Structural Requirements</h3>\r\n        <p>We identify key civil work requirements, including foundations, walls, flooring, plumbing, and electrical provisions.</p>\r\n      </article>\r\n\r\n      <article class=\"approach-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"ac-icon\" aria-hidden=\"true\"><i class=\"fas fa-tasks\"></i></span>\r\n        <h3>Coordinating Development Activities</h3>\r\n        <p>We focus on coordinating the various development requirements to ensure that structural and infrastructure work aligns with the overall project plan.</p>\r\n      </article>\r\n\r\n      <article class=\"approach-card anim-base anim-fade-up delay-400\">\r\n        <span class=\"ac-icon\" aria-hidden=\"true\"><i class=\"fas fa-check-double\"></i></span>\r\n        <h3>Supporting Functional Readiness</h3>\r\n        <p>We consider the final infrastructure requirements to help ensure that the developed space is suitable for its intended hospitality operations.</p>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 4: CTA (WARM GOLD CHAMPAGNE #EFE3C6) -->\r\n<section class=\"cta\">\r\n  <div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n    <span class=\"eyebrow\">Let\'s Build the Foundation for Your Next Hospitality Venture.</span>\r\n    <h2>Strong Foundations. Better Hospitality Spaces.</h2>\r\n    <p>The success of a hospitality business depends not only on what guests see but also on the infrastructure that supports everything behind the scenes.</p>\r\n    <p>Let Artha Hospitality Management help you develop well-planned hospitality spaces with strong foundations and essential infrastructure designed around your business needs.</p>\r\n    <div class=\"cta-btns\">\r\n      <a href=\"http://localhost/artha-hospitality-management/contact-us\" class=\"btn btn-light\">Partner With Artha <span class=\"arrow\">↗</span></a>\r\n      <a href=\"http://localhost/artha-hospitality-management/contact-us#contact-form-section\" class=\"btn btn-outline-light\">Get in Touch</a>\r\n    </div>\r\n  </div>\r\n</section>\r\n</article>', 'Civil Work', '', 'publish', 'closed', 'closed', '', 'civil-work', '', '', '2026-11-26 09:43:24', '2026-11-26 09:43:24', '', 0, 'http://localhost/artha-hospitality-management/?page_id=34', 0, 'page', '', 0);
