INSERT INTO `wp_posts` VALUES(75, 1, '2026-11-26 11:41:48', '2026-11-26 11:41:48', '<article>\r\n<!-- 01 · HERO SECTION (75VH — OUR CLIENTS: TRUSTED PARTNERSHIPS. SHARED SUCCESS.) -->\r\n<section class=\"clients-hero\" id=\"clients-top\">\r\n  <div class=\"wrap clients-hero-layout\">\r\n\r\n    <!-- Left Column: Exact Provided Copy -->\r\n    <div class=\"clients-hero-copy anim-base anim-fade-right\">\r\n      <div class=\"hero-meta-row\">\r\n        <nav class=\"crumb-badge\" aria-label=\"Breadcrumb\">\r\n          <a href=\"http://localhost/artha-hospitality-management/\">Home</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <span class=\"curr\">Our Clients</span>\r\n        </nav>\r\n        <span class=\"eyebrow\">Our Clients</span>\r\n      </div>\r\n\r\n      <h1>Trusted Partnerships. <em>Shared Success.</em></h1>\r\n      <p>At Artha Hospitality Management, we take pride in the relationships we build and the businesses we support. Every partnership reflects our commitment to delivering practical hospitality solutions, operational expertise, and professional guidance.</p>\r\n      <p>We are grateful to the businesses that have placed their trust in us and chosen Artha as their hospitality management partner.</p>\r\n\r\n      <div class=\"clients-hero-actions\">\r\n        <a href=\"#client-logos\" class=\"btn btn-primary\">View Our Clients <span class=\"arrow\">↓</span></a>\r\n        <a href=\"http://localhost/artha-hospitality-management/contact-us\" class=\"btn btn-ghost\">Partner With Artha</a>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Right Column: Interlocking Dual-Arch Partnership Stage (No Text Overlays) -->\r\n    <div class=\"partnership-emblem-stage anim-base anim-fade-left delay-100\" aria-hidden=\"true\">\r\n      <svg class=\"pes-rings-svg\" viewBox=\"0 0 560 480\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.3\">\r\n        <circle cx=\"205\" cy=\"240\" r=\"175\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"355\" cy=\"240\" r=\"175\" opacity=\"0.5\" />\r\n      </svg>\r\n\r\n      <!-- Left Hospitality Pillar -->\r\n      <div class=\"pes-pillar-left\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-clients-hero-left.jpg\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Hospitality client partnership property</figcaption>\r\n        </figure>\r\n      </div>\r\n\r\n      <!-- Right Hospitality Pillar -->\r\n      <div class=\"pes-pillar-right\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-clients-hero-right.jpg\" alt=\"Restaurant client dining destination\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Restaurant client dining destination</figcaption>\r\n        </figure>\r\n      </div>\r\n\r\n      <!-- Central Partnership Handshake Seal -->\r\n      <div class=\"pes-center-seal\">\r\n        <i class=\"fas fa-handshake\"></i>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- 02 · CLIENT LOGO SHOWCASE (THE MAIN FOCUS OF THE PAGE) -->\r\n<section class=\"client-logos-showcase\" id=\"client-logos\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Valued Partnerships</span>\r\n      <h2>Businesses That Have Trusted Us</h2>\r\n      <p>Our clients represent the partnerships we have built through shared goals, industry understanding, and a commitment to hospitality excellence.</p>\r\n      <span class=\"logo-showcase-sub\"><i class=\"fas fa-award\"></i> A selection of our valued client partnerships</span>\r\n    </div>\r\n\r\n    <!-- Clean 8-Slot Grid of Client Company Logos (Consistent Size, Generous Spacing, Subtle Hover) -->\r\n    <div class=\"client-logo-grid\">\r\n\r\n      <!-- Client Logo 01: Spindrift -->\r\n<div class=\"client-logo-card anim-base anim-fade-up delay-100\">\r\n  <div class=\"client-logo-frame\">\r\n    <figure class=\"cr-figure\">\r\n      <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/spindrift-logo.jpg\" alt=\"Spindrift Logo\" loading=\"lazy\">\r\n      <figcaption class=\"cr-only\">Spindrift</figcaption>\r\n    </figure>\r\n  </div>\r\n</div>\r\n\r\n<!-- Client Logo 02: Shiv Sagar -->\r\n<div class=\"client-logo-card anim-base anim-fade-up delay-200\">\r\n  <div class=\"client-logo-frame\">\r\n    <figure class=\"cr-figure\">\r\n      <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/shiv-sagar-logo.jpg\" alt=\"Shiv Sagar Logo\" loading=\"lazy\">\r\n      <figcaption class=\"cr-only\">Shiv Sagar</figcaption>\r\n    </figure>\r\n  </div>\r\n</div>\r\n\r\n<!-- Client Logo 03: Mayapuri Veg Treats -->\r\n<div class=\"client-logo-card anim-base anim-fade-up delay-300\">\r\n  <div class=\"client-logo-frame\">\r\n    <figure class=\"cr-figure\">\r\n      <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/mayapuri-veg-treats-logo.jpg\" alt=\"Mayapuri Veg Treats Logo\" loading=\"lazy\">\r\n      <figcaption class=\"cr-only\">Mayapuri Veg Treats</figcaption>\r\n    </figure>\r\n  </div>\r\n</div>\r\n\r\n<!-- Client Logo 04: Andhra House -->\r\n<div class=\"client-logo-card anim-base anim-fade-up delay-100\">\r\n  <div class=\"client-logo-frame\">\r\n    <figure class=\"cr-figure\">\r\n      <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/andhra-house-logo.jpg\" alt=\"Andhra House Logo\" loading=\"lazy\">\r\n      <figcaption class=\"cr-only\">Andhra House</figcaption>\r\n    </figure>\r\n  </div>\r\n</div>\r\n\r\n<!-- Client Logo 05: Coverse Cafe -->\r\n<div class=\"client-logo-card anim-base anim-fade-up delay-200\">\r\n  <div class=\"client-logo-frame\">\r\n    <figure class=\"cr-figure\">\r\n      <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/coverse-cafe-logo.jpg\" alt=\"Coverse Cafe Logo\" loading=\"lazy\">\r\n      <figcaption class=\"cr-only\">Coverse Cafe</figcaption>\r\n    </figure>\r\n  </div>\r\n</div>\r\n\r\n<!-- Client Logo 06: Punjabi Dhaba -->\r\n<div class=\"client-logo-card anim-base anim-fade-up delay-300\">\r\n  <div class=\"client-logo-frame\">\r\n    <figure class=\"cr-figure\">\r\n      <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/punjabi-dhaba-logo.jpg\" alt=\"Punjabi Dhaba Logo\" loading=\"lazy\">\r\n      <figcaption class=\"cr-only\">Punjabi Dhaba</figcaption>\r\n    </figure>\r\n  </div>\r\n</div>\r\n\r\n<!-- Client Logo 07: The Narayan Cafe -->\r\n<div class=\"client-logo-card anim-base anim-fade-up delay-100\">\r\n  <div class=\"client-logo-frame\">\r\n    <figure class=\"cr-figure\">\r\n      <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/the-narayan-cafe-logo.jpg\" alt=\"The Narayan Cafe Logo\" loading=\"lazy\">\r\n      <figcaption class=\"cr-only\">The Narayan Cafe</figcaption>\r\n    </figure>\r\n  </div>\r\n</div>\r\n\r\n      <!-- Client Logo 08: Elite Group -->\r\n      <!-- <div class=\"client-logo-card anim-base anim-fade-up delay-200\">\r\n        <div class=\"client-logo-frame\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/sk-traders-client8.jpg\" alt=\"Elite Group Logo\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Elite Group</figcaption>\r\n          </figure>\r\n        </div>\r\n      </div> -->\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- 03 · CLOSING CTA (LET\'S BUILD A SUCCESSFUL PARTNERSHIP) -->\r\n<section class=\"cta\">\r\n  <div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n    <span class=\"eyebrow\">Work With Us</span>\r\n    <h2>Let\'s Build a Successful Partnership</h2>\r\n    <p>Are you planning a new hospitality venture or looking to take your existing business to the next level? Partner with Artha Hospitality Management and benefit from practical expertise and dedicated support.</p>\r\n    <div class=\"cta-lead-bold\">Let\'s Start Your Hospitality Journey Together.</div>\r\n    <div class=\"cta-btns\">\r\n      <a href=\"http://localhost/artha-hospitality-management/contact-us\" class=\"btn btn-light\">Partner With Artha <span class=\"arrow\">↗</span></a>\r\n      <a href=\"http://localhost/artha-hospitality-management/contact-us#contact-form-section\" class=\"btn btn-outline-light\">Get in Touch</a>\r\n    </div>\r\n  </div>\r\n</section>\r\n</article>', 'Clients', '', 'publish', 'closed', 'closed', '', 'clients', '', '', '2026-11-26 11:41:48', '2026-11-26 11:41:48', '', 0, 'http://localhost/artha-hospitality-management/?page_id=75', 0, 'page', '', 0);
INSERT INTO `wp_posts` VALUES(76, 1, '2026-11-26 11:41:48', '2026-11-26 11:41:48', '<article>\r\n<!-- 01 · HERO SECTION (75VH — OUR CLIENTS: TRUSTED PARTNERSHIPS. SHARED SUCCESS.) -->\r\n<section class=\"clients-hero\" id=\"clients-top\">\r\n  <div class=\"wrap clients-hero-layout\">\r\n\r\n    <!-- Left Column: Exact Provided Copy -->\r\n    <div class=\"clients-hero-copy anim-base anim-fade-right\">\r\n      <div class=\"hero-meta-row\">\r\n        <nav class=\"crumb-badge\" aria-label=\"Breadcrumb\">\r\n          <a href=\"http://localhost/artha-hospitality-management/\">Home</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <span class=\"curr\">Our Clients</span>\r\n        </nav>\r\n        <span class=\"eyebrow\">Our Clients</span>\r\n      </div>\r\n\r\n      <h1>Trusted Partnerships. <em>Shared Success.</em></h1>\r\n      <p>At Artha Hospitality Management, we take pride in the relationships we build and the businesses we support. Every partnership reflects our commitment to delivering practical hospitality solutions, operational expertise, and professional guidance.</p>\r\n      <p>We are grateful to the businesses that have placed their trust in us and chosen Artha as their hospitality management partner.</p>\r\n\r\n      <div class=\"clients-hero-actions\">\r\n        <a href=\"#client-logos\" class=\"btn btn-primary\">View Our Clients <span class=\"arrow\">↓</span></a>\r\n        <a href=\"http://localhost/artha-hospitality-management/contact-us\" class=\"btn btn-ghost\">Partner With Artha</a>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Right Column: Interlocking Dual-Arch Partnership Stage (No Text Overlays) -->\r\n    <div class=\"partnership-emblem-stage anim-base anim-fade-left delay-100\" aria-hidden=\"true\">\r\n      <svg class=\"pes-rings-svg\" viewBox=\"0 0 560 480\" fill=\"none\" stroke=\"#C4161C\" stroke-width=\"1.3\">\r\n        <circle cx=\"205\" cy=\"240\" r=\"175\" stroke-dasharray=\"6 6\" opacity=\"0.55\" />\r\n        <circle cx=\"355\" cy=\"240\" r=\"175\" opacity=\"0.5\" />\r\n      </svg>\r\n\r\n      <!-- Left Hospitality Pillar -->\r\n      <div class=\"pes-pillar-left\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-clients-hero-left.jpg\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Hospitality client partnership property</figcaption>\r\n        </figure>\r\n      </div>\r\n\r\n      <!-- Right Hospitality Pillar -->\r\n      <div class=\"pes-pillar-right\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-clients-hero-right.jpg\" alt=\"Restaurant client dining destination\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Restaurant client dining destination</figcaption>\r\n        </figure>\r\n      </div>\r\n\r\n      <!-- Central Partnership Handshake Seal -->\r\n      <div class=\"pes-center-seal\">\r\n        <i class=\"fas fa-handshake\"></i>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- 02 · CLIENT LOGO SHOWCASE (THE MAIN FOCUS OF THE PAGE) -->\r\n<section class=\"client-logos-showcase\" id=\"client-logos\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Valued Partnerships</span>\r\n      <h2>Businesses That Have Trusted Us</h2>\r\n      <p>Our clients represent the partnerships we have built through shared goals, industry understanding, and a commitment to hospitality excellence.</p>\r\n      <span class=\"logo-showcase-sub\"><i class=\"fas fa-award\"></i> A selection of our valued client partnerships</span>\r\n    </div>\r\n\r\n    <!-- Clean 8-Slot Grid of Client Company Logos (Consistent Size, Generous Spacing, Subtle Hover) -->\r\n    <div class=\"client-logo-grid\">\r\n\r\n      <!-- Client Logo 01: Spindrift -->\r\n<div class=\"client-logo-card anim-base anim-fade-up delay-100\">\r\n  <div class=\"client-logo-frame\">\r\n    <figure class=\"cr-figure\">\r\n      <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/spindrift-logo.jpg\" alt=\"Spindrift Logo\" loading=\"lazy\">\r\n      <figcaption class=\"cr-only\">Spindrift</figcaption>\r\n    </figure>\r\n  </div>\r\n</div>\r\n\r\n<!-- Client Logo 02: Shiv Sagar -->\r\n<div class=\"client-logo-card anim-base anim-fade-up delay-200\">\r\n  <div class=\"client-logo-frame\">\r\n    <figure class=\"cr-figure\">\r\n      <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/shiv-sagar-logo.jpg\" alt=\"Shiv Sagar Logo\" loading=\"lazy\">\r\n      <figcaption class=\"cr-only\">Shiv Sagar</figcaption>\r\n    </figure>\r\n  </div>\r\n</div>\r\n\r\n<!-- Client Logo 03: Mayapuri Veg Treats -->\r\n<div class=\"client-logo-card anim-base anim-fade-up delay-300\">\r\n  <div class=\"client-logo-frame\">\r\n    <figure class=\"cr-figure\">\r\n      <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/mayapuri-veg-treats-logo.jpg\" alt=\"Mayapuri Veg Treats Logo\" loading=\"lazy\">\r\n      <figcaption class=\"cr-only\">Mayapuri Veg Treats</figcaption>\r\n    </figure>\r\n  </div>\r\n</div>\r\n\r\n<!-- Client Logo 04: Andhra House -->\r\n<div class=\"client-logo-card anim-base anim-fade-up delay-100\">\r\n  <div class=\"client-logo-frame\">\r\n    <figure class=\"cr-figure\">\r\n      <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/andhra-house-logo.jpg\" alt=\"Andhra House Logo\" loading=\"lazy\">\r\n      <figcaption class=\"cr-only\">Andhra House</figcaption>\r\n    </figure>\r\n  </div>\r\n</div>\r\n\r\n<!-- Client Logo 05: Coverse Cafe -->\r\n<div class=\"client-logo-card anim-base anim-fade-up delay-200\">\r\n  <div class=\"client-logo-frame\">\r\n    <figure class=\"cr-figure\">\r\n      <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/coverse-cafe-logo.jpg\" alt=\"Coverse Cafe Logo\" loading=\"lazy\">\r\n      <figcaption class=\"cr-only\">Coverse Cafe</figcaption>\r\n    </figure>\r\n  </div>\r\n</div>\r\n\r\n<!-- Client Logo 06: Punjabi Dhaba -->\r\n<div class=\"client-logo-card anim-base anim-fade-up delay-300\">\r\n  <div class=\"client-logo-frame\">\r\n    <figure class=\"cr-figure\">\r\n      <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/punjabi-dhaba-logo.jpg\" alt=\"Punjabi Dhaba Logo\" loading=\"lazy\">\r\n      <figcaption class=\"cr-only\">Punjabi Dhaba</figcaption>\r\n    </figure>\r\n  </div>\r\n</div>\r\n\r\n<!-- Client Logo 07: The Narayan Cafe -->\r\n<div class=\"client-logo-card anim-base anim-fade-up delay-100\">\r\n  <div class=\"client-logo-frame\">\r\n    <figure class=\"cr-figure\">\r\n      <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/the-narayan-cafe-logo.jpg\" alt=\"The Narayan Cafe Logo\" loading=\"lazy\">\r\n      <figcaption class=\"cr-only\">The Narayan Cafe</figcaption>\r\n    </figure>\r\n  </div>\r\n</div>\r\n\r\n      <!-- Client Logo 08: Elite Group -->\r\n      <!-- <div class=\"client-logo-card anim-base anim-fade-up delay-200\">\r\n        <div class=\"client-logo-frame\">\r\n          <figure class=\"cr-figure\">\r\n            <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/clients/sk-traders-client8.jpg\" alt=\"Elite Group Logo\" loading=\"lazy\">\r\n            <figcaption class=\"cr-only\">Elite Group</figcaption>\r\n          </figure>\r\n        </div>\r\n      </div> -->\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- 03 · CLOSING CTA (LET\'S BUILD A SUCCESSFUL PARTNERSHIP) -->\r\n<section class=\"cta\">\r\n  <div class=\"wrap cta-inner anim-base anim-zoom-in\">\r\n    <span class=\"eyebrow\">Work With Us</span>\r\n    <h2>Let\'s Build a Successful Partnership</h2>\r\n    <p>Are you planning a new hospitality venture or looking to take your existing business to the next level? Partner with Artha Hospitality Management and benefit from practical expertise and dedicated support.</p>\r\n    <div class=\"cta-lead-bold\">Let\'s Start Your Hospitality Journey Together.</div>\r\n    <div class=\"cta-btns\">\r\n      <a href=\"http://localhost/artha-hospitality-management/contact-us\" class=\"btn btn-light\">Partner With Artha <span class=\"arrow\">↗</span></a>\r\n      <a href=\"http://localhost/artha-hospitality-management/contact-us#contact-form-section\" class=\"btn btn-outline-light\">Get in Touch</a>\r\n    </div>\r\n  </div>\r\n</section>\r\n</article>', 'Clients', '', 'inherit', 'closed', 'closed', '', '75-revision-v1', '', '', '2026-11-26 11:41:48', '2026-11-26 11:41:48', '', 75, 'http://localhost/artha-hospitality-management/?p=76', 0, 'revision', '', 0);
