INSERT INTO `wp_posts` VALUES(85, 1, '2026-11-27 09:25:56', '2026-11-27 09:25:56', '<article>\r\n<!-- UNIQUE 75VH OPENINGS HERO: ASCENDING CAREER STAIRCASE & TRAJECTORY ARC -->\r\n<section class=\"openings-hero\" id=\"openings-top\">\r\n  <div class=\"wrap openings-hero-grid\">\r\n\r\n    <!-- Left Column: Editorial Copy & CTAs -->\r\n    <div class=\"openings-hero-copy anim-base anim-fade-right\">\r\n      <div class=\"hero-meta-row\">\r\n        <nav class=\"crumb-badge\" aria-label=\"Breadcrumb\">\r\n          <a href=\"http://localhost/artha-hospitality-management/\">Home</a>\r\n          <span class=\"sep\"><i class=\"fas fa-chevron-right\"></i></span>\r\n          <span class=\"curr\">Careers</span>\r\n        </nav>\r\n        <span class=\"eyebrow\">Careers &amp; Opportunities</span>\r\n      </div>\r\n\r\n      <h1>Build Your Career in <em>Hospitality Excellence.</em></h1>\r\n      <p>At Artha Hospitality Management, we value passionate hospitality professionals who share our commitment to thoughtful planning, operational excellence, and memorable guest experiences.</p>\r\n\r\n      <div class=\"openings-hero-actions\">\r\n        <a href=\"http://localhost/artha-hospitality-management/contact-us#contact-form-section\" class=\"btn btn-primary\">Get in Touch <span class=\"arrow\">↗</span></a>\r\n        <a href=\"http://localhost/artha-hospitality-management/\" class=\"btn btn-ghost\">Back to Home</a>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Right Column: Sculpted Marquise Arch & Animated Geometric Career Crest (No Text) -->\r\n    <div class=\"openings-visual-stage anim-base anim-fade-left delay-100\" aria-hidden=\"true\">\r\n      <div class=\"ov-orbit-ring\"></div>\r\n      <div class=\"ov-navy-slab\"></div>\r\n      <div class=\"ov-gold-wireframe\"></div>\r\n      <div class=\"ov-dots\"></div>\r\n\r\n      <div class=\"ov-main-frame\">\r\n        <figure class=\"cr-figure\">\r\n          <img src=\"http://localhost/artha-hospitality-management/wp-content/themes/artha-child-theme/assets/images/artha-hospitality-openings-hero.jpg\" alt=\"Hospitality careers and leadership environment at Artha Hospitality Management\" loading=\"eager\">\r\n          <figcaption class=\"cr-only\">Hospitality careers and leadership environment at Artha Hospitality Management</figcaption>\r\n        </figure>\r\n      </div>\r\n\r\n      <div class=\"ov-badge-top\">\r\n        <i class=\"fas fa-briefcase\"></i>\r\n      </div>\r\n\r\n      <div class=\"ov-dock-bottom\">\r\n        <span><i class=\"fas fa-user-tie\"></i></span>\r\n        <span><i class=\"fas fa-utensils\"></i></span>\r\n        <span><i class=\"fas fa-award\"></i></span>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 1: JOB OPPORTUNITIES -->\r\n<section id=\"job-opportunities\" class=\"jobs-sec\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Job Opportunities</span>\r\n      <h2>We\'re Hiring — Build Your Career in Hospitality</h2>\r\n      <p>Artha Hospitality is hiring for leading hotels, restaurants, resorts and cafes in Mangalore and across Karnataka. Whether you are a fresher or experienced, we will help you find the right hotel job.</p>\r\n    </div>\r\n\r\n    <div class=\"jobs-grid\">\r\n      <article class=\"job-card anim-base anim-fade-up delay-100\">\r\n        <span class=\"job-ic\" aria-hidden=\"true\"><i class=\"fas fa-utensils\"></i></span>\r\n        <h3>Chef / Cook</h3>\r\n        <ul class=\"job-roles\">\r\n          <li>Commis</li>\r\n          <li>CDP</li>\r\n          <li>Sous Chef</li>\r\n          <li>South Indian / North Indian / Continental</li>\r\n        </ul>\r\n        <div class=\"job-card-footer\">\r\n          <span class=\"job-loc\"><i class=\"fas fa-location-dot\" aria-hidden=\"true\"></i> Location: Mangalore</span>\r\n          <a href=\"#application-form\" class=\"job-apply-btn\" data-job-role=\"Chef / Cook\">Apply Now &rarr;</a>\r\n        </div>\r\n      </article>\r\n\r\n      <article class=\"job-card anim-base anim-fade-up delay-200\">\r\n        <span class=\"job-ic\" aria-hidden=\"true\"><i class=\"fas fa-concierge-bell\"></i></span>\r\n        <h3>Front Office Executive</h3>\r\n        <ul class=\"job-roles\">\r\n          <li>Reception</li>\r\n          <li>Reservation</li>\r\n          <li>Guest Relations</li>\r\n        </ul>\r\n        <div class=\"job-card-footer\">\r\n          <span class=\"job-loc\"><i class=\"fas fa-location-dot\" aria-hidden=\"true\"></i> Location: Mangalore</span>\r\n          <a href=\"#application-form\" class=\"job-apply-btn\" data-job-role=\"Front Office Executive\">Apply Now &rarr;</a>\r\n        </div>\r\n      </article>\r\n\r\n      <article class=\"job-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"job-ic\" aria-hidden=\"true\"><i class=\"fas fa-bed\"></i></span>\r\n        <h3>Housekeeping Staff</h3>\r\n        <ul class=\"job-roles\">\r\n          <li>Room Attendant</li>\r\n          <li>Housekeeping Supervisor</li>\r\n        </ul>\r\n        <div class=\"job-card-footer\">\r\n          <span class=\"job-loc\"><i class=\"fas fa-location-dot\" aria-hidden=\"true\"></i> Location: Mangalore</span>\r\n          <a href=\"#application-form\" class=\"job-apply-btn\" data-job-role=\"Housekeeping Staff\">Apply Now &rarr;</a>\r\n        </div>\r\n      </article>\r\n\r\n      <article class=\"job-card anim-base anim-fade-up delay-100\">\r\n        <span class=\"job-ic\" aria-hidden=\"true\"><i class=\"fas fa-wine-glass\"></i></span>\r\n        <h3>F&amp;B Service — Steward / Waiter</h3>\r\n        <ul class=\"job-roles\">\r\n          <li>Restaurant</li>\r\n          <li>Banquet</li>\r\n          <li>Room Service</li>\r\n        </ul>\r\n        <div class=\"job-card-footer\">\r\n          <span class=\"job-loc\"><i class=\"fas fa-location-dot\" aria-hidden=\"true\"></i> Location: Mangalore</span>\r\n          <a href=\"#application-form\" class=\"job-apply-btn\" data-job-role=\"F&amp;B Service — Steward / Waiter\">Apply Now &rarr;</a>\r\n        </div>\r\n      </article>\r\n\r\n      <article class=\"job-card anim-base anim-fade-up delay-200\">\r\n        <span class=\"job-ic\" aria-hidden=\"true\"><i class=\"fas fa-martini-glass-citrus\"></i></span>\r\n        <h3>Barista / Bartender</h3>\r\n        <ul class=\"job-roles\">\r\n          <li>Cafe</li>\r\n          <li>Pub &amp; Resto Bar</li>\r\n        </ul>\r\n        <div class=\"job-card-footer\">\r\n          <span class=\"job-loc\"><i class=\"fas fa-location-dot\" aria-hidden=\"true\"></i> Location: Mangalore</span>\r\n          <a href=\"#application-form\" class=\"job-apply-btn\" data-job-role=\"Barista / Bartender\">Apply Now &rarr;</a>\r\n        </div>\r\n      </article>\r\n\r\n      <article class=\"job-card anim-base anim-fade-up delay-300\">\r\n        <span class=\"job-ic\" aria-hidden=\"true\"><i class=\"fas fa-user-graduate\"></i></span>\r\n        <h3>Hotel Management Trainee</h3>\r\n        <ul class=\"job-roles\">\r\n          <li>For Freshers</li>\r\n          <li>Hotel Management Students</li>\r\n        </ul>\r\n        <div class=\"job-card-footer\">\r\n          <span class=\"job-loc\"><i class=\"fas fa-location-dot\" aria-hidden=\"true\"></i> Location: Mangalore</span>\r\n          <a href=\"#application-form\" class=\"job-apply-btn\" data-job-role=\"Hotel Management Trainee\">Apply Now &rarr;</a>\r\n        </div>\r\n      </article>\r\n    </div>\r\n\r\n    <nav class=\"jobs-pagination\" id=\"jobsPagination\" aria-label=\"Job opportunities pagination\"></nav>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 2: APPLY FOR A HOTEL JOB -->\r\n<section id=\"application-form\" class=\"app-form-sec\">\r\n  <div class=\"wrap\">\r\n    <div class=\"head-center anim-base anim-fade-right\">\r\n      <span class=\"eyebrow\">Careers Application</span>\r\n      <h2>Apply for a Hotel Job</h2>\r\n      <p>Interested in building your career in hospitality? Submit your details and our recruitment team will get in touch with you.</p>\r\n    </div>\r\n\r\n    <div class=\"app-form-wrap\">\r\n      <form id=\"hotelJobApplicationForm\" class=\"app-form-card anim-base anim-fade-up\" novalidate>\r\n        <div class=\"app-form-grid\">\r\n          <div class=\"app-field\">\r\n            <label for=\"app-name\">Full Name <span>*</span></label>\r\n            <input type=\"text\" id=\"app-name\" name=\"fullName\" placeholder=\"Enter your full name\" required>\r\n          </div>\r\n\r\n          <div class=\"app-field\">\r\n            <label for=\"app-phone\">Phone / WhatsApp Number <span>*</span></label>\r\n            <input type=\"tel\" id=\"app-phone\" name=\"phone\" placeholder=\"Enter your mobile number\" required>\r\n          </div>\r\n\r\n          <div class=\"app-field\">\r\n            <label for=\"app-city\">City <span>*</span></label>\r\n            <select id=\"app-city\" name=\"city\" required>\r\n              <option value=\"\">Select city</option>\r\n              <option value=\"Mangalore\">Mangalore</option>\r\n              <option value=\"Other\">Other</option>\r\n            </select>\r\n          </div>\r\n\r\n          <div class=\"app-field\">\r\n            <label for=\"app-role-search\">Job Role Interested In <span>*</span></label>\r\n            <div class=\"searchable-select\" id=\"appRoleDropdown\">\r\n              <div class=\"searchable-select-control\">\r\n                <i class=\"fas fa-magnifying-glass searchable-select-search-ic\" aria-hidden=\"true\"></i>\r\n                <input\r\n                  type=\"text\"\r\n                  id=\"app-role-search\"\r\n                  class=\"searchable-select-input\"\r\n                  placeholder=\"Search or select job role...\"\r\n                  autocomplete=\"off\"\r\n                  role=\"combobox\"\r\n                  aria-expanded=\"false\"\r\n                  aria-autocomplete=\"list\"\r\n                  aria-controls=\"app-role-list\"\r\n                />\r\n                <button type=\"button\" class=\"searchable-select-toggle\" aria-label=\"Toggle job role options\" tabindex=\"-1\">\r\n                  <i class=\"fas fa-chevron-down\" aria-hidden=\"true\"></i>\r\n                </button>\r\n              </div>\r\n              <ul id=\"app-role-list\" class=\"searchable-select-list\" role=\"listbox\" hidden></ul>\r\n              <select id=\"app-role\" name=\"jobRole\" class=\"searchable-select-native\" required tabindex=\"-1\" aria-hidden=\"true\">\r\n                <option value=\"\">Select job role</option>\r\n                <option value=\"Chef\">Chef</option>\r\n                <option value=\"Front Office\">Front Office</option>\r\n                <option value=\"Housekeeping\">Housekeeping</option>\r\n                <option value=\"F&amp;B Service\">F&amp;B Service</option>\r\n                <option value=\"Barista / Bartender\">Barista / Bartender</option>\r\n                <option value=\"Management Trainee\">Management Trainee</option>\r\n              </select>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"app-field full\">\r\n            <label for=\"app-exp\">Experience <span>*</span></label>\r\n            <select id=\"app-exp\" name=\"experience\" required>\r\n              <option value=\"\">Select experience</option>\r\n              <option value=\"Fresher\">Fresher</option>\r\n              <option value=\"0–1 Year\">0–1 Year</option>\r\n              <option value=\"1–3 Years\">1–3 Years</option>\r\n              <option value=\"3+ Years\">3+ Years</option>\r\n            </select>\r\n          </div>\r\n\r\n          <div class=\"app-field full\">\r\n            <label for=\"app-cv\">Upload CV / Resume <small>(Optional)</small></label>\r\n            <div class=\"app-upload-box\">\r\n              <span class=\"app-upload-ic\" aria-hidden=\"true\"><i class=\"fas fa-cloud-arrow-up\"></i></span>\r\n              <div class=\"app-upload-text\">\r\n                <strong id=\"app-cv-filename\">Choose a file to upload</strong>\r\n                <small>Accepted formats: PDF, DOC, DOCX</small>\r\n              </div>\r\n              <input type=\"file\" id=\"app-cv\" name=\"resume\" accept=\".pdf,.doc,.docx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document\">\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"app-submit-row\">\r\n            <button type=\"submit\" class=\"app-submit-btn\">Submit Application</button>\r\n          </div>\r\n\r\n          <div id=\"app-form-status\" class=\"app-form-status\" role=\"status\" aria-live=\"polite\"></div>\r\n        </div>\r\n      </form>\r\n\r\n      <div class=\"wa-apply-box anim-base anim-fade-up delay-100\">\r\n        <div class=\"wa-apply-copy\">\r\n          <strong>Or Apply Directly on WhatsApp: +91 89515 11234</strong>\r\n          <p>Send: Name, City, Role, Experience</p>\r\n        </div>\r\n        <a href=\"https://wa.me/918951511234?text=Hello%20Artha%20Hospitality%2C%20I%20would%20like%20to%20apply%20for%20a%20hotel%20job.%0AName%3A%20%0ACity%3A%20%0ARole%3A%20%0AExperience%3A%20\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"wa-apply-btn\">\r\n          <i class=\"fab fa-whatsapp\" aria-hidden=\"true\"></i> Apply via WhatsApp\r\n        </a>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- SECTION 3: CTA -->\r\n<section class=\"cta\">\r\n  <div class=\"wrap\">\r\n    <div class=\"cta-split-grid\">\r\n      <article class=\"cta-box anim-base anim-fade-up delay-100\">\r\n        <span class=\"cta-box-ic\" aria-hidden=\"true\"><i class=\"fas fa-hotel\"></i></span>\r\n        <span class=\"eyebrow\">FOR HOTEL OWNERS</span>\r\n        <h2>Need Staff for Your Hotel?</h2>\r\n        <p>Hire trained, verified staff with Artha.</p>\r\n        <a href=\"http://localhost/artha-hospitality-management/contact-us#contact-form-section\" class=\"btn\">Hire Staff Now <span class=\"arrow\">&rarr;</span></a>\r\n      </article>\r\n\r\n      <article class=\"cta-box anim-base anim-fade-up delay-200\">\r\n        <span class=\"cta-box-ic\" aria-hidden=\"true\"><i class=\"fas fa-briefcase\"></i></span>\r\n        <span class=\"eyebrow\">FOR JOB SEEKERS</span>\r\n        <h2>Looking for a Hotel Job?</h2>\r\n        <p>Apply for Chef, Front Office, Housekeeping &amp; F&amp;B jobs.</p>\r\n        <a href=\"#job-opportunities\" class=\"btn\">Apply for Jobs <span class=\"arrow\">&rarr;</span></a>\r\n      </article>\r\n    </div>\r\n  </div>\r\n</section>\r\n</article>', 'Careers', '', 'inherit', 'closed', 'closed', '', '60-revision-v1', '', '', '2026-11-27 09:25:56', '2026-11-27 09:25:56', '', 60, 'http://localhost/artha-hospitality-management/?p=85', 0, 'revision', '', 0);
